/// Check whether `cargo-deny` is installed by running `cargo deny --version`.
/// Returns `true` when the subcommand is available, `false` otherwise.
fn cargo_deny_available() -> bool {
    Command::new("cargo")
        .args(["deny", "--version"])
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false)
}

#[test]
fn token_binding_canonicalization_preserves_default_serde_json_features() {
    let manifest = read_file(&repo_root().join("Cargo.toml"));
    assert!(
        !manifest.contains("serde_json_canonicalizer"),
        "serde_json_canonicalizer enables serde_json/float_roundtrip globally and changes ordinary wire parsing"
    );
    assert!(
        !manifest.contains("ryu-js"),
        "safe-integer-only canonicalization must not add a global JSON number parser/formatter"
    );
}

/// Run `cargo deny <deny_args>` and return `(success, combined_output)`.
/// Returns `None` (and prints a skip message) when cargo-deny is not installed.
fn run_cargo_deny(deny_args: &[&str]) -> Option<(bool, String)> {
    if !cargo_deny_available() {
        eprintln!(
            "Skipping: cargo-deny is not installed.\n\
             Install with: cargo install cargo-deny"
        );
        return None;
    }

    let mut args = vec!["deny"];
    args.extend_from_slice(deny_args);

    let output = Command::new("cargo")
        .args(&args)
        .current_dir(repo_root())
        .output()
        .expect("failed to execute cargo deny");

    let mut combined = String::from_utf8_lossy(&output.stdout).to_string();
    combined.push_str(&String::from_utf8_lossy(&output.stderr));
    Some((output.status.success(), combined))
}

/// Build and run a nested `cargo check` for one optional feature in an isolated
/// target directory with sanitizer-related environment variables removed.
///
/// This avoids false negatives in sanitizer jobs where nested Cargo invocations
/// can conflict with instrumentation flags and cached artifacts.
fn run_isolated_feature_check(feature: &str) -> (bool, String) {
    let root = repo_root();
    let target_dir = root
        .join("target")
        .join("ci-config-feature-check")
        .join(feature.replace([',', ' '], "_"));

    let output = Command::new("cargo")
        .args(["check", "--features", feature, "--locked"])
        .current_dir(&root)
        .env("CARGO_TARGET_DIR", &target_dir)
        .env_remove("RUSTFLAGS")
        .env_remove("CARGO_ENCODED_RUSTFLAGS")
        .env_remove("RUSTDOCFLAGS")
        .env_remove("ASAN_OPTIONS")
        .env_remove("LSAN_OPTIONS")
        .env_remove("UBSAN_OPTIONS")
        .env_remove("TSAN_OPTIONS")
        .env_remove("MIRIFLAGS")
        .output()
        .unwrap_or_else(|e| panic!("Failed to run cargo check for feature `{feature}`: {e}"));

    let mut combined = String::new();
    combined.push_str(&format!(
        "command: cargo check --features {feature} --locked\n"
    ));
    combined.push_str(&format!("CARGO_TARGET_DIR: {}\n\n", target_dir.display()));
    combined.push_str(&String::from_utf8_lossy(&output.stdout));
    combined.push_str(&String::from_utf8_lossy(&output.stderr));

    (output.status.success(), combined)
}

fn parse_github_slug_from_remote_url(remote_url: &str) -> Option<(String, String)> {
    let trimmed = remote_url.trim().trim_end_matches(".git");
    let slug = if let Some(rest) = trimmed.strip_prefix("git@github.com:") {
        rest
    } else if let Some(rest) = trimmed.strip_prefix("https://github.com/") {
        rest
    } else if let Some(rest) = trimmed.strip_prefix("http://github.com/") {
        rest
    } else {
        return None;
    };

    let (owner, repo) = slug.split_once('/')?;
    if owner.is_empty() || repo.is_empty() {
        return None;
    }

    Some((owner.to_lowercase(), repo.to_lowercase()))
}

fn expected_first_party_image_refs() -> std::collections::HashSet<String> {
    let mut refs = std::collections::HashSet::from([
        "ghcr.io/ambiguous-interactive/signal-fish-server".to_string(),
        "ambiguous-interactive/signal-fish-server".to_string(),
        // Legacy namespace retained to avoid false positives during migration.
        "ghcr.io/ambiguousinteractive/signal-fish-server".to_string(),
        "ambiguousinteractive/signal-fish-server".to_string(),
    ]);

    let remote_url = Command::new("git")
        .args(["remote", "get-url", "origin"])
        .current_dir(repo_root())
        .output()
        .ok()
        .filter(|output| output.status.success())
        .map(|output| String::from_utf8_lossy(&output.stdout).to_string());

    if let Some(remote_url) = remote_url {
        if let Some((owner, repo)) = parse_github_slug_from_remote_url(&remote_url) {
            refs.insert(format!("ghcr.io/{owner}/{repo}"));
            refs.insert(format!("{owner}/{repo}"));
        }
    }

    refs
}

/// Extract Shields.io URLs from text content with their 1-based line numbers.
fn extract_shields_urls(content: &str) -> Vec<(usize, String)> {
    const SHIELDS_PREFIX: &str = "https://img.shields.io/";
    let mut urls = Vec::new();

    for (line_idx, line) in content.lines().enumerate() {
        let mut rest = line;
        while let Some(start) = rest.find(SHIELDS_PREFIX) {
            let candidate = &rest[start..];
            let end = candidate
                .find(|c: char| c == '"' || c == '\'' || c == ')' || c == '>' || c.is_whitespace())
                .unwrap_or(candidate.len());
            urls.push((line_idx + 1, candidate[..end].to_string()));
            rest = &candidate[end..];
        }
    }

    urls
}

/// Return true when a Shields URL has `style=for-the-badge` as a query parameter.
///
/// This mirrors scripts/check-readme-badges.sh semantics:
/// - style must be preceded by '?' or '&'
/// - style must be followed by '&', '#', or end-of-string
fn shields_url_has_for_the_badge_style(url: &str) -> bool {
    const STYLE_PARAM: &str = "style=for-the-badge";

    url.match_indices(STYLE_PARAM).any(|(idx, _)| {
        let has_valid_prefix = idx > 0 && matches!(url.as_bytes()[idx - 1], b'?' | b'&');
        let suffix_idx = idx + STYLE_PARAM.len();
        let has_valid_suffix =
            suffix_idx == url.len() || matches!(url.as_bytes()[suffix_idx], b'&' | b'#');
        has_valid_prefix && has_valid_suffix
    })
}

fn normalize_local_script_token(token: &str) -> Option<String> {
    let token = token
        .trim_matches(['"', '\'', '`', '(', ')', '[', ']', ','])
        .trim_end_matches([';', ')', ',']);
    let mut path = token;
    for prefix in [
        "${{ github.workspace }}/",
        "$GITHUB_WORKSPACE/",
        "${GITHUB_WORKSPACE}/",
        "$PWD/",
        "${PWD}/",
    ] {
        if let Some(stripped) = path.strip_prefix(prefix) {
            path = stripped;
            break;
        }
    }
    let path = path.strip_prefix("./").unwrap_or(path);
    let is_local_script = path.starts_with("scripts/") || path.starts_with(".github/scripts/");
    let is_script_file = [".sh", ".awk", ".py", ".ps1", ".bash", ".js"]
        .iter()
        .any(|extension| path.ends_with(extension));

    if is_local_script && is_script_file {
        Some(path.to_string())
    } else {
        None
    }
}

fn invokes_script_through_interpreter(token: &str) -> bool {
    let token = token.trim_matches(|c: char| matches!(c, '"' | '\'' | '`' | '(' | ')' | ';'));
    matches!(
        token,
        "bash"
            | "sh"
            | "awk"
            | "perl"
            | "python"
            | "python3"
            | "shellcheck"
            | "pwsh"
            | "powershell"
            | "node"
            | "source"
            | "."
    ) || token.ends_with("/bash")
        || token.ends_with("/sh")
}

fn is_shell_command_string_option(token: &str) -> bool {
    let token = token.trim_matches(|c: char| matches!(c, '"' | '\'' | '`' | '(' | ')' | ';'));
    token.starts_with('-') && !token.starts_with("--") && token.contains('c')
}

fn strip_unquoted_shell_comment(text: &str) -> &str {
    let mut in_single = false;
    let mut in_double = false;
    let mut escaped = false;
    let mut previous = None;

    for (idx, ch) in text.char_indices() {
        if escaped {
            escaped = false;
            previous = Some(ch);
            continue;
        }
        if ch == '\\' && !in_single {
            escaped = true;
            previous = Some(ch);
            continue;
        }
        if ch == '\'' && !in_double {
            in_single = !in_single;
            previous = Some(ch);
            continue;
        }
        if ch == '"' && !in_single {
            in_double = !in_double;
            previous = Some(ch);
            continue;
        }
        if ch == '#' && !in_single && !in_double && previous.is_none_or(char::is_whitespace) {
            return text[..idx].trim_end();
        }
        previous = Some(ch);
    }

    text
}

fn is_awk_identifier_char(ch: char) -> bool {
    ch == '_' || ch.is_ascii_alphanumeric()
}

fn skip_ascii_whitespace(text: &str, mut byte_idx: usize) -> usize {
    while let Some(ch) = text[byte_idx..].chars().next() {
        if !ch.is_ascii_whitespace() {
            break;
        }
        byte_idx += ch.len_utf8();
    }
    byte_idx
}

fn awk_match_arguments_use_capture_array(text: &str, open_paren_byte: usize) -> bool {
    let mut depth = 1usize;
    let mut comma_count = 0usize;
    let mut in_string = false;
    let mut in_regex = false;
    let mut escaped = false;
    let mut previous_significant = Some('(');

    for ch in text[open_paren_byte + 1..].chars() {
        if escaped {
            escaped = false;
            continue;
        }

        if in_string {
            if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_string = false;
            }
            continue;
        }

        if in_regex {
            if ch == '\\' {
                escaped = true;
            } else if ch == '/' {
                in_regex = false;
                previous_significant = Some('/');
            }
            continue;
        }

        match ch {
            '"' => in_string = true,
            '/' if matches!(previous_significant, Some('(' | ',' | '~' | '!')) => {
                in_regex = true;
            }
            '(' => {
                depth += 1;
                previous_significant = Some('(');
            }
            ')' => {
                if depth == 1 {
                    return comma_count >= 2;
                }
                depth -= 1;
                previous_significant = Some(')');
            }
            ',' if depth == 1 => {
                comma_count += 1;
                previous_significant = Some(',');
            }
            '#' => return false,
            _ if ch.is_whitespace() => {}
            _ => previous_significant = Some(ch),
        }
    }

    false
}

fn awk_source_uses_gnu_match_capture(source: &str) -> bool {
    awk_source_gnu_match_capture_line(source).is_some()
}

fn awk_source_gnu_match_capture_line(source: &str) -> Option<usize> {
    let mut in_string = false;
    let mut escaped = false;
    let mut in_comment = false;

    for (byte_idx, ch) in source.char_indices() {
        if in_comment {
            if ch == '\n' {
                in_comment = false;
            }
            continue;
        }

        if escaped {
            escaped = false;
            continue;
        }

        if in_string {
            if ch == '\\' {
                escaped = true;
            } else if ch == '"' {
                in_string = false;
            }
            continue;
        }

        match ch {
            '"' => in_string = true,
            '#' => in_comment = true,
            'm' if source[byte_idx..].starts_with("match") => {
                let before_is_identifier = source[..byte_idx]
                    .chars()
                    .next_back()
                    .is_some_and(is_awk_identifier_char);
                let after_match = byte_idx + "match".len();
                let after_is_identifier = source[after_match..]
                    .chars()
                    .next()
                    .is_some_and(is_awk_identifier_char);

                if before_is_identifier || after_is_identifier {
                    continue;
                }

                let open_paren = skip_ascii_whitespace(source, after_match);
                if source[open_paren..].starts_with('(')
                    && awk_match_arguments_use_capture_array(source, open_paren)
                {
                    return Some(
                        source[..byte_idx]
                            .bytes()
                            .filter(|byte| *byte == b'\n')
                            .count()
                            + 1,
                    );
                }
            }
            _ => {}
        }
    }

    None
}

fn normalize_github_workspace_expression(command: &str) -> String {
    command
        .replace("${{ github.workspace }}", "$GITHUB_WORKSPACE")
        .replace("${{github.workspace}}", "$GITHUB_WORKSPACE")
}

fn line_indent(line: &str) -> usize {
    line.len() - line.trim_start().len()
}

fn workflow_run_command_lines(content: &str) -> Vec<(usize, String)> {
    let mut commands = Vec::new();
    let mut in_run_block = false;
    let mut run_block_indent = 0;

    for (line_idx, line) in content.lines().enumerate() {
        let line_number = line_idx + 1;
        let trimmed = line.trim();
        let indent = line_indent(line);

        if in_run_block {
            if trimmed.is_empty() || trimmed.starts_with('#') {
                continue;
            }
            if indent > run_block_indent {
                commands.push((line_number, trimmed.to_string()));
                continue;
            }
            in_run_block = false;
        }

        if trimmed.starts_with('#') {
            continue;
        }

        let command = trimmed
            .strip_prefix("- run:")
            .or_else(|| trimmed.strip_prefix("run:"))
            .map(str::trim_start);
        let Some(command) = command else {
            continue;
        };

        if matches!(command.chars().next(), Some('|') | Some('>')) {
            in_run_block = true;
            run_block_indent = indent;
            continue;
        }

        if !command.is_empty() {
            commands.push((line_number, command.to_string()));
        }
    }

    commands
}

fn workflow_direct_script_violations_for_content(
    workflow_name: &str,
    content: &str,
) -> Vec<String> {
    let mut violations = Vec::new();

    for (line_number, command) in workflow_run_command_lines(content) {
        let command = strip_unquoted_shell_comment(&command).trim();
        if command.is_empty() {
            continue;
        }
        if is_shell_assignment_only(command) {
            continue;
        }
        let command = normalize_github_workspace_expression(command);
        let mut token_text = command.replace("&&", " ").replace("||", " ");
        for separator in [';', '&', '|', '(', ')'] {
            token_text = token_text.replace(separator, " ");
        }
        let tokens: Vec<&str> = token_text.split_whitespace().collect();
        for (token_idx, token) in tokens.iter().enumerate() {
            let Some(script_path) = normalize_local_script_token(token) else {
                continue;
            };

            let start = token_idx.saturating_sub(8);
            let interpreted = (start..token_idx).rev().any(|previous_idx| {
                invokes_script_through_interpreter(tokens[previous_idx])
                    && !tokens[previous_idx + 1..token_idx]
                        .iter()
                        .any(|token| is_shell_command_string_option(token))
            });
            if interpreted {
                continue;
            }

            violations.push(format!(
                "  {workflow_name}:{line_number}: direct script invocation must use an interpreter\n\
                 script: {script_path}\n\
                 line: {command}"
            ));
        }
    }

    violations
}

fn is_shell_assignment_only(command: &str) -> bool {
    let command = command.trim();
    static ASSIGNMENT_RE: OnceLock<Regex> = OnceLock::new();
    let assignment = ASSIGNMENT_RE.get_or_init(|| {
        Regex::new(r#"^[A-Za-z_][A-Za-z0-9_]*(\[[^\]]+\])?="#)
            .expect("shell assignment regex should compile")
    });
    let Some(assignment_match) = assignment.find(command) else {
        return false;
    };

    shell_assignment_value_consumes_rest(&command[assignment_match.end()..])
}

fn shell_assignment_value_consumes_rest(value: &str) -> bool {
    let value = value.trim_start();
    let Some(first_char) = value.chars().next() else {
        return true;
    };

    if first_char != '"' && first_char != '\'' {
        return !value.chars().any(char::is_whitespace);
    }

    let mut escaped = false;
    for (idx, ch) in value.char_indices().skip(1) {
        if first_char == '"' && ch == '\\' && !escaped {
            escaped = true;
            continue;
        }

        if ch == first_char && !escaped {
            return value[idx + ch.len_utf8()..].trim().is_empty();
        }

        escaped = false;
    }

    false
}

#[test]
fn test_workflow_direct_script_detector_edge_cases() {
    let cases = [
        (
            "workspace expression direct path is rejected",
            "jobs:\n  test:\n    steps:\n      - run: ${{ github.workspace }}/scripts/foo.sh\n",
            true,
        ),
        (
            "shell command string still executes script directly",
            "jobs:\n  test:\n    steps:\n      - run: bash -c './scripts/foo.sh'\n",
            true,
        ),
        (
            "interpreter with options is allowed",
            "jobs:\n  test:\n    steps:\n      - run: bash --noprofile --norc -e scripts/foo.sh\n",
            false,
        ),
        (
            "inline comments are ignored",
            "jobs:\n  test:\n    steps:\n      - run: echo ok # ./scripts/foo.sh\n",
            false,
        ),
        (
            "source does not require executable bit",
            "jobs:\n  test:\n    steps:\n      - run: source scripts/foo.sh\n",
            false,
        ),
        (
            "assignment-only line may contain script path data",
            "jobs:\n  test:\n    steps:\n      - run: |\n          PATH_FILTERED_WORKFLOWS[\"Documentation Validation\"]=\"*.md scripts/check-internal-links.sh\"\n",
            false,
        ),
    ];

    for (name, workflow, should_reject) in cases {
        let violations = workflow_direct_script_violations_for_content("fixture.yml", workflow);
        assert_eq!(
            !violations.is_empty(),
            should_reject,
            "{name}: unexpected detector result: {violations:?}"
        );
    }
}

/// Collect README-style violations for Shields badge URLs that do not include
/// style=for-the-badge.
fn collect_shields_style_violations(file_name: &str, content: &str) -> Vec<String> {
    extract_shields_urls(content)
        .into_iter()
        .filter(|(_, url)| !shields_url_has_for_the_badge_style(url))
        .map(|(line_num, url)| format!("{file_name}:{line_num}: {url}"))
        .collect()
}

/// Write a temporary markdown file inside target/test-temp and return its path.
#[cfg(unix)]
fn write_temp_markdown_file(root: &Path, prefix: &str, content: &str) -> tempfile::NamedTempFile {
    use std::io::Write;
    let temp_dir = root.join("target").join("test-temp");
    fs::create_dir_all(&temp_dir).unwrap_or_else(|e| {
        panic!(
            "Failed to create temporary test directory {}: {e}",
            temp_dir.display()
        )
    });

    let mut temp_file = tempfile::Builder::new()
        .prefix(prefix)
        .suffix(".md")
        .tempfile_in(&temp_dir)
        .unwrap_or_else(|e| {
            panic!(
                "Failed to create temporary markdown file in {}: {e}",
                temp_dir.display()
            )
        });

    temp_file.write_all(content.as_bytes()).unwrap_or_else(|e| {
        panic!(
            "Failed to write temporary markdown file {}: {e}",
            temp_file.path().display()
        )
    });

    temp_file
}

/// Extract the value of a TOML field like `rust-version = "1.88.0"`
fn extract_toml_version(content: &str, field: &str) -> Option<String> {
    for line in content.lines() {
        let trimmed = line.trim();
        if let Some(rest) = trimmed.strip_prefix(field) {
            let rest = rest.trim();
            if let Some(rest) = rest.strip_prefix('=') {
                return Some(rest.trim().trim_matches('"').to_string());
            }
        }
    }
    None
}

/// Extract the value of a YAML field like `channel = "1.88.0"`
fn extract_yaml_version(content: &str, field: &str) -> Option<String> {
    for line in content.lines() {
        let trimmed = line.trim();
        if let Some(rest) = trimmed.strip_prefix(field) {
            let rest = rest.trim();
            if let Some(rest) = rest.strip_prefix('=') {
                return Some(rest.trim().trim_matches('"').to_string());
            } else if let Some(rest) = rest.strip_prefix(':') {
                return Some(rest.trim().trim_matches('"').to_string());
            }
        }
    }
    None
}

/// Extract the `if:` condition of a job from workflow YAML content.
///
/// Searches for a job key at 2-space indentation (`  job_key:`) and then
/// looks for the `if:` field at 4-space indentation within that job block.
/// Returns `None` if the job or its `if:` field is not found.
fn extract_job_if_condition(content: &str, job_key: &str) -> Option<String> {
    let job_header = format!("  {job_key}:");
    let mut in_target_job = false;

    for line in content.lines() {
        if line.starts_with(&job_header) {
            in_target_job = true;
            continue;
        }

        if in_target_job {
            let trimmed = line.trim();

            // If we hit another job definition (2-space indent, not a sub-key),
            // we've left the target job block
            if line.starts_with("  ") && !line.starts_with("    ") && !trimmed.is_empty() {
                return None;
            }

            // Look for "    if: <condition>" within the job block
            if let Some(rest) = line.strip_prefix("    if:") {
                return Some(rest.trim().to_string());
            }
        }
    }

    None
}

/// Return the number of leading spaces in a line.
fn yaml_indent_spaces(line: &str) -> usize {
    line.chars().take_while(|c| *c == ' ').count()
}

/// Returns true when `<indent><key>:` starts a block mapping, meaning there is
/// no inline scalar/flow value after `:` other than optional whitespace/comment.
fn yaml_key_starts_block_mapping(line: &str, key: &str, indent: usize) -> bool {
    if yaml_indent_spaces(line) != indent {
        return false;
    }

    let trimmed = line.trim_start();
    let Some(rest) = trimmed.strip_prefix(key) else {
        return false;
    };
    let Some(after_colon) = rest.trim_start().strip_prefix(':') else {
        return false;
    };

    let trailing = strip_yaml_inline_comment(after_colon).trim();
    trailing.is_empty()
}

/// Extract a YAML mapping block that starts with `<indent><key>:` and continues
/// until the next non-empty line with indentation <= `indent` (or EOF).
fn extract_yaml_mapping_block(content: &str, key: &str, indent: usize) -> Option<String> {
    let lines: Vec<&str> = content.lines().collect();

    for (idx, line) in lines.iter().enumerate() {
        if !yaml_key_starts_block_mapping(line, key, indent) {
            continue;
        }

        let mut block_lines = Vec::new();
        for follow in lines.iter().skip(idx + 1) {
            if !follow.trim().is_empty() && yaml_indent_spaces(follow) <= indent {
                break;
            }
            block_lines.push(*follow);
        }

        return Some(block_lines.join("\n"));
    }

    None
}

/// Extract one workflow step by its unquoted `name`, stopping at the next step
/// at the same indentation. This keeps structural assertions scoped to the
/// step they protect instead of accepting a matching token elsewhere.
fn extract_named_workflow_step(content: &str, name: &str) -> Option<String> {
    let marker = format!("- name: {name}");
    let lines: Vec<&str> = content.lines().collect();
    let start = lines.iter().position(|line| line.trim() == marker)?;
    let step_indent = yaml_indent_spaces(lines[start]);
    let end = lines
        .iter()
        .enumerate()
        .skip(start + 1)
        .find(|(_, line)| {
            !line.trim().is_empty()
                && yaml_indent_spaces(line) == step_indent
                && line.trim_start().starts_with("- ")
        })
        .map(|(index, _)| index)
        .unwrap_or(lines.len());

    Some(lines[start..end].join("\n"))
}

/// Detect the indentation level of the first non-empty line in a YAML block.
fn yaml_first_child_indent(content: &str) -> Option<usize> {
    content
        .lines()
        .find(|line| !line.trim().is_empty())
        .map(yaml_indent_spaces)
}

/// Strip YAML inline comments while preserving `#` inside quoted strings,
/// including escaped quotes in double-quoted scalars and doubled quotes in
/// single-quoted scalars.
fn strip_yaml_inline_comment(value: &str) -> &str {
    let mut in_single_quotes = false;
    let mut in_double_quotes = false;
    let mut previous_char: Option<char> = None;
    let mut consecutive_backslashes = 0usize;
    let mut chars = value.char_indices().peekable();

    while let Some((idx, ch)) = chars.next() {
        if in_single_quotes {
            if ch == '\'' {
                if matches!(chars.peek(), Some((_, '\''))) {
                    chars.next();
                    previous_char = Some('\'');
                    continue;
                }
                in_single_quotes = false;
            }

            previous_char = Some(ch);
            continue;
        }

        if in_double_quotes {
            match ch {
                '\\' => consecutive_backslashes += 1,
                '"' => {
                    if consecutive_backslashes.is_multiple_of(2) {
                        in_double_quotes = false;
                    }
                    consecutive_backslashes = 0;
                }
                _ => consecutive_backslashes = 0,
            }

            previous_char = Some(ch);
            continue;
        }

        match ch {
            '\'' => in_single_quotes = true,
            '"' => {
                in_double_quotes = true;
                consecutive_backslashes = 0;
            }
            '#' => {
                if idx == 0 || previous_char.is_some_and(char::is_whitespace) {
                    return &value[..idx];
                }
            }
            _ => {}
        }

        previous_char = Some(ch);
    }

    value
}

/// Extract values from a YAML field that may be inline (`field: [a, b]`) or
/// multi-line list form:
///   field:
///     - a
///     - b
fn extract_yaml_field_values(block: &str, field: &str) -> Vec<String> {
    let mut values = Vec::new();
    let lines: Vec<&str> = block.lines().collect();

    for (idx, line) in lines.iter().enumerate() {
        let trimmed = line.trim_start();
        let Some(rest) = trimmed.strip_prefix(field) else {
            continue;
        };
        let Some(rest_after_colon) = rest.trim_start().strip_prefix(':') else {
            continue;
        };

        let field_indent = yaml_indent_spaces(line);
        let scalar = strip_yaml_inline_comment(rest_after_colon).trim();
        if scalar.starts_with('[') && scalar.ends_with(']') {
            let inner = &scalar[1..scalar.len().saturating_sub(1)];
            for item in inner.split(',') {
                let value = item.trim().trim_matches('"').trim_matches('\'');
                if !value.is_empty() {
                    values.push(value.to_string());
                }
            }
            return values;
        }

        if !scalar.is_empty() {
            values.push(scalar.trim_matches('"').trim_matches('\'').to_string());
            return values;
        }

        for follow in lines.iter().skip(idx + 1) {
            if follow.trim().is_empty() {
                continue;
            }
            let follow_indent = yaml_indent_spaces(follow);
            if follow_indent <= field_indent {
                break;
            }

            let trimmed_follow = follow.trim_start();
            if let Some(item) = trimmed_follow.strip_prefix("- ") {
                let item = strip_yaml_inline_comment(item).trim();
                if !item.is_empty() {
                    values.push(item.trim_matches('"').trim_matches('\'').to_string());
                }
            }
        }

        return values;
    }

    values
}

fn extract_workflow_event_paths(workflow_content: &str, event: &str) -> Vec<String> {
    let on_block = extract_yaml_mapping_block(workflow_content, "on", 0)
        .unwrap_or_else(|| panic!("workflow must define top-level on block"));
    let on_child_indent = yaml_first_child_indent(&on_block)
        .unwrap_or_else(|| panic!("workflow on block must define events"));
    let event_block = extract_yaml_mapping_block(&on_block, event, on_child_indent)
        .unwrap_or_else(|| panic!("workflow must define {event} event block"));

    extract_yaml_field_values(&event_block, "paths")
}

fn release_preflight_pattern_for_doc_path(path: &str) -> String {
    match path {
        "**/*.md" => "*.md".to_string(),
        "**/*.rs" => "*.rs".to_string(),
        directory_glob if directory_glob.ends_with("/**") => {
            format!("{}/", directory_glob.trim_end_matches("/**"))
        }
        exact_path => exact_path.to_string(),
    }
}

#[test]
fn test_extract_yaml_mapping_block_ignores_inline_mapping_values() {
    let content = concat!(
        "permissions: read-all\n",
        "concurrency: { group: test, cancel-in-progress: true }\n",
        "permissions:\n",
        "  contents: read\n",
    );

    let extracted = extract_yaml_mapping_block(content, "permissions", 0)
        .expect("expected block-mapping permissions key to be extracted");
    assert!(
        extracted.contains("contents: read"),
        "block mapping should be extracted, not inline scalar form"
    );
    assert!(
        !extracted.contains("read-all"),
        "inline scalar value must be ignored by block-mapping extraction"
    );
}

#[test]
fn test_extract_yaml_mapping_block_allows_trailing_comments() {
    let content = concat!("permissions: # baseline\n", "  contents: read\n");
    let extracted = extract_yaml_mapping_block(content, "permissions", 0)
        .expect("expected key with trailing comment to be treated as block mapping");
    assert!(extracted.contains("contents: read"));
}

#[test]
fn test_strip_yaml_inline_comment_preserves_hash_after_escaped_double_quote() {
    let value = "\"value with escaped quote \\\" and # still scalar\" # comment";
    assert_eq!(
        strip_yaml_inline_comment(value),
        "\"value with escaped quote \\\" and # still scalar\" "
    );
}

#[test]
fn test_strip_yaml_inline_comment_preserves_hash_in_single_quoted_scalar() {
    let value = "'value with '' escaped quote and # still scalar' # comment";
    assert_eq!(
        strip_yaml_inline_comment(value),
        "'value with '' escaped quote and # still scalar' "
    );
}

/// Extract the display name of a job from workflow YAML content.
///
/// Searches for a job key at 2-space indentation (`  job_key:`) and then
/// looks for the `name:` field at 4-space indentation within that job block.
/// Returns `None` if the job or its name field is not found.
fn extract_job_display_name(content: &str, job_key: &str) -> Option<String> {
    let job_header = format!("  {job_key}:");
    let mut in_target_job = false;

    for line in content.lines() {
        if line.starts_with(&job_header) {
            in_target_job = true;
            continue;
        }

        if in_target_job {
            let trimmed = line.trim();

            // If we hit another job definition (2-space indent, not a sub-key),
            // we've left the target job block
            if line.starts_with("  ") && !line.starts_with("    ") && !trimmed.is_empty() {
                return None;
            }

            // Look for "    name: Display Name" within the job block
            if let Some(rest) = line.strip_prefix("    name:") {
                return Some(rest.trim().trim_matches('"').to_string());
            }
        }
    }

    None
}

/// Extract the `audit:` job section from CI workflow YAML content.
///
/// Finds the `  audit:` job header and collects all lines belonging to that job
/// block (4+-space-indented lines and blank lines) into a single string.
fn extract_audit_section(ci_content: &str) -> String {
    ci_content
        .lines()
        .skip_while(|line| !line.starts_with("  audit:"))
        .take_while(|line| {
            line.starts_with("  audit:") || line.starts_with("    ") || line.trim().is_empty()
        })
        .collect::<Vec<&str>>()
        .join("\n")
}

/// Extract the `sbom:` job section from CI workflow YAML content.
///
/// Finds the `  sbom:` job header and collects all lines belonging to that job
/// block (4+-space-indented lines and blank lines) into a single string.
fn extract_sbom_section(ci_content: &str) -> String {
    ci_content
        .lines()
        .skip_while(|line| !line.starts_with("  sbom:"))
        .take_while(|line| {
            line.starts_with("  sbom:") || line.starts_with("    ") || line.trim().is_empty()
        })
        .collect::<Vec<&str>>()
        .join("\n")
}

/// Validate that a workflow file contains all required jobs with the correct
/// display names.
///
/// Uses `extract_job_display_name()` for scoped name matching within each job
/// block, preventing false positives where a display name appears elsewhere
/// in the file (e.g., in comments or unrelated steps).
///
/// Panics with a detailed diagnostic message if any required jobs are missing
/// or have mismatched display names.
fn validate_workflow_has_required_jobs(
    workflow_path: &Path,
    required_jobs: &[(&str, &str, &str)],
    workflow_description: &str,
) {
    let content = read_live_file(workflow_path);

    let mut missing_jobs = Vec::new();
    let mut found_jobs = Vec::new();

    for (job_key, display_name, description) in required_jobs {
        // Look for "job-key:" pattern at 2-space indentation (top-level job definition)
        let job_pattern = format!("  {job_key}:");
        if content.contains(&job_pattern) {
            // Use scoped extraction to verify the display name belongs to this job block
            let actual_name = extract_job_display_name(&content, job_key);
            match actual_name {
                Some(ref name) if name == display_name => {
                    found_jobs.push(format!(
                        "  + {job_key} (name: \"{display_name}\", {description})"
                    ));
                }
                Some(ref wrong_name) => {
                    missing_jobs.push(format!(
                        "  x {job_key}: job exists but display name \"{wrong_name}\" does not match \
                         expected \"{display_name}\".\n\
                         Expected line: `    name: {display_name}`\n\
                         This changes the repository's stable GitHub check-name contract.\n\
                         To fix: Update the job's `name:` field to \"{display_name}\""
                    ));
                }
                None => {
                    missing_jobs.push(format!(
                        "  x {job_key}: job exists but has no `name:` field.\n\
                         Expected line: `    name: {display_name}`\n\
                         This changes the repository's stable GitHub check-name contract.\n\
                         To fix: Add `name: {display_name}` to the job definition"
                    ));
                }
            }
        } else {
            missing_jobs.push(format!("  x {job_key} ({display_name} - {description})"));
        }
    }

    if !missing_jobs.is_empty() {
        panic!(
            "{workflow_description} workflow is missing required jobs or display names:\n\n\
             Missing:\n{}\n\n\
             Found:\n{}\n\n\
             File: {}\n\n\
             These jobs are critical for CI/CD validation.\n\
             To fix:\n\
             1. Review git history to see when the job was removed or renamed\n\
             2. Restore the job definition in the jobs: section\n\
             3. Ensure the job key AND name: field match exactly (case-sensitive)\n\
             4. Update the repository-owned check-name policy if a rename was intentional",
            missing_jobs.join("\n"),
            found_jobs.join("\n"),
            workflow_path.display()
        );
    }
}

// ============================================================================
// Required Check Naming Contract
// ============================================================================
//
// These constants define the exact GitHub check names that this repository
// treats as its stable validation contract. They do not assert that every name
// is currently configured in GitHub branch protection. Workflow and job names
// are treated as API surface — any rename requires a synchronized update to:
//   1. The workflow/job definition in .github/workflows/
//   2. These constants and tests
//   3. CI/CD documentation (docs/ci-cd-testing.md, docs/ci-cd-testing-summary.md)
//   4. Any external consumer that has selected the check name
//
// GitHub constructs check names as: "{workflow name} / {job display name}"
//
// Current stable validation checks (Phase 1-2):
//   - CI / Lint (ubuntu-latest)
//   - CI / Lint (windows-latest)
//   - CI / Lint (macos-latest)
//   - CI / Nextest (ubuntu-latest)
//   - CI / Nextest (windows-latest)
//   - CI / Nextest (macos-latest)
//   - CI / Relay Allocation Ceilings
//   - CI / Dependency Audit
//   - CI / MSRV Verification
//   - CI / Docker Build
//   - CI / Coverage (llvm-cov)
//   - CI / Panic Policy
//   - CI / SBOM (CycloneDX)
//   - Documentation Validation / Rustdoc Validation
//   - Documentation Validation / Documentation Tests
//   - Documentation Validation / Markdown Code Validation
//   - Documentation Validation / Documentation Link Check

