/// Container image platforms that MUST be published as a single multi-arch
/// manifest list by `docker-publish.yml`.
///
/// Root cause this guards (issue #122): `docker/build-push-action` was invoked
/// without a `platforms:` key, so the published `ghcr.io/.../signal-fish-server`
/// image only carried a `linux/amd64` entry. Pulling on ARM64 Linux (AWS
/// Graviton, Raspberry Pi, Ampere, Apple Silicon under Docker) failed with
/// "no matching manifest for linux/arm64/v8 in the manifest list entries".
///
/// Keep this list in lockstep with:
///   - the `platforms:` value passed to `docker/build-push-action` in
///     `docker-publish.yml`
///   - the cross-compilation target map in the `Dockerfile`
///
/// The build strategy is cross-compilation (the builder stage runs natively on
/// `$BUILDPLATFORM` and cross-compiles to `$TARGETARCH`), NOT QEMU emulation, so
/// adding a platform here also requires a Rust target triple + cross linker in
/// the Dockerfile's arch map.
const REQUIRED_CONTAINER_PLATFORMS: &[&str] = &["linux/amd64", "linux/arm64", "linux/arm/v7"];

/// Standalone release binaries that MUST be built and attached to every GitHub
/// Release created by `release.yml`.
///
/// `release.yml` historically published only the crate to crates.io and a
/// changelog-only GitHub Release with no downloadable executables, leaving
/// Windows / macOS / ARM users with no prebuilt binary. Each tuple is
/// `(rust target triple, human-facing platform label)`.
///
/// Keep this list in lockstep with the build matrix in `release.yml`. Every
/// triple must appear in the workflow, each produced artifact must ship with a
/// SHA-256 checksum, and all artifacts must be uploaded to the GitHub Release.
const REQUIRED_RELEASE_TARGETS: &[(&str, &str)] = &[
    ("x86_64-unknown-linux-gnu", "Linux x86_64"),
    ("aarch64-unknown-linux-gnu", "Linux ARM64"),
    ("x86_64-apple-darwin", "macOS Intel"),
    ("aarch64-apple-darwin", "macOS Apple Silicon"),
    ("x86_64-pc-windows-msvc", "Windows x86_64"),
    ("aarch64-pc-windows-msvc", "Windows ARM64"),
];

/// Every git-tracked package manifest must declare an explicit `unsafe_code`
/// lint policy under `[lints.rust]` (issue #205).
///
/// The signaling server and its reference clients contain no `unsafe` block.
/// That was true by habit, not by construction — nothing stopped a future
/// change from introducing one silently. Discovery is dynamic (`git ls-files`)
/// so a package added later cannot opt out by omission, which is the failure
/// mode this guards: a manifest that simply never mentions the policy.
///
/// `forbid` is required everywhere except packages listed in
/// `DENY_UNSAFE_PACKAGES`, which need a small, reviewed number of unsafe sites
/// (godot-rust's `unsafe impl ExtensionLibrary` marker) and therefore use
/// `deny` plus a local `#[allow(unsafe_code)]` at each site.
#[test]
fn test_every_package_manifest_declares_an_unsafe_code_policy() {
    /// Packages permitted to use `deny` instead of `forbid`, with the reason.
    const DENY_UNSAFE_PACKAGES: &[(&str, &str)] = &[(
        "clients/fortress-wasm/Cargo.toml",
        "godot-rust requires one `unsafe impl ExtensionLibrary` marker",
    )];
    /// Asserted present so a broken discovery cannot pass vacuously.
    const REQUIRED_MANIFESTS: &[&str] = &[
        "Cargo.toml",
        "clients/fortress/Cargo.toml",
        "clients/fortress-wasm/Cargo.toml",
        "clients/native/Cargo.toml",
        "fuzz/Cargo.toml",
    ];

    let root = repo_root();
    let manifests = tracked_package_manifests(&root);
    let mut checked: Vec<String> = Vec::new();
    let mut problems: Vec<String> = Vec::new();

    for relative in &manifests {
        let manifest = read_file(&root.join(relative));
        // Only packages carry lints; a pure `[workspace]` manifest has none.
        if !manifest.lines().any(|line| line.trim() == "[package]") {
            continue;
        }
        checked.push(relative.clone());
        let expected = if DENY_UNSAFE_PACKAGES
            .iter()
            .any(|(path, _)| path == relative)
        {
            "deny"
        } else {
            "forbid"
        };
        match unsafe_code_lint_level(&manifest) {
            Some(level) if level == expected => {}
            Some(level) => problems.push(format!(
                "  - {relative}  declares `unsafe_code = \"{level}\"`, expected \"{expected}\""
            )),
            None => problems.push(format!(
                "  - {relative}  has no `unsafe_code` entry under [lints.rust]"
            )),
        }
    }

    assert!(
        problems.is_empty(),
        "Package manifest(s) missing the no-unsafe policy (issue #205):\n{}\n\n\
         Add `unsafe_code = \"forbid\"` under a `[lints.rust]` table. If the package \
         genuinely requires an unsafe site, use \"deny\" instead, add a local \
         `#[allow(unsafe_code)]` with a SAFETY comment at that site, and record the \
         package in DENY_UNSAFE_PACKAGES in this test.",
        problems.join("\n")
    );
    for required in REQUIRED_MANIFESTS {
        assert!(
            checked.iter().any(|relative| relative == required),
            "expected to check `{required}`, but only checked {checked:?}; manifest \
             discovery may be broken or the package moved"
        );
    }
}

/// Read the `unsafe_code` level from a manifest's `[lints.rust]` table.
///
/// A small section scan rather than a toml dependency, matching the style of
/// the MSRV and lockfile guards in this repository.
fn unsafe_code_lint_level(manifest: &str) -> Option<String> {
    let mut in_lints_rust = false;
    for line in manifest.lines() {
        let trimmed = line.trim();
        if trimmed.starts_with('[') && trimmed.ends_with(']') {
            in_lints_rust = trimmed == "[lints.rust]";
            continue;
        }
        if !in_lints_rust {
            continue;
        }
        let Some(rest) = trimmed.strip_prefix("unsafe_code") else {
            continue;
        };
        let rest = rest.trim_start().strip_prefix('=')?.trim();
        // Accept both `unsafe_code = "forbid"` and the table form
        // `unsafe_code = { level = "forbid", .. }`.
        let value = rest.strip_prefix('"').and_then(|s| s.strip_suffix('"'));
        return match value {
            Some(level) => Some(level.to_string()),
            None => rest
                .split("level")
                .nth(1)
                .and_then(|s| s.split('"').nth(1))
                .map(str::to_string),
        };
    }
    None
}

/// Repository-relative paths of every git-tracked `Cargo.toml`.
///
/// Uses git rather than a filesystem walk so vendored/ignored manifests under
/// `target/` are excluded and any newly committed package is picked up with no
/// list to maintain.
///
/// `*/Cargo.toml` reaches **any** depth, not just one level: git pathspec globs
/// do not set `FNM_PATHNAME`, so `*` matches `/`. It therefore covers
/// `clients/fortress/Cargo.toml` as well as `fuzz/Cargo.toml`. This reads like
/// a shell glob, where it would mean one level only — `REQUIRED_MANIFESTS`
/// names a two-level path precisely so a wrong assumption here fails loudly
/// instead of silently shrinking the guard's coverage.
fn tracked_package_manifests(root: &Path) -> Vec<String> {
    let output = Command::new("git")
        .arg("-C")
        .arg(root)
        .args(["ls-files", "-z", "--", "Cargo.toml", "*/Cargo.toml"])
        .output()
        .unwrap_or_else(|error| {
            panic!("`git ls-files` failed ({error}); this guard requires a git checkout")
        });
    assert!(
        output.status.success(),
        "`git ls-files` exited with {}; this guard requires a git checkout",
        output.status
    );
    let manifests: Vec<String> = String::from_utf8_lossy(&output.stdout)
        .split('\0')
        .filter(|entry| !entry.is_empty())
        .map(|entry| entry.replace('\\', "/"))
        .collect();
    assert!(
        !manifests.is_empty(),
        "`git ls-files` returned no Cargo.toml paths; this guard requires a git checkout"
    );
    manifests
}

fn tracked_cargo_lockfiles(root: &Path) -> BTreeSet<String> {
    let output = Command::new("git")
        .arg("-C")
        .arg(root)
        .args(["ls-files", "-z", "--", "Cargo.lock", "*/Cargo.lock"])
        .output()
        .unwrap_or_else(|error| {
            panic!("`git ls-files` failed ({error}); this guard requires a git checkout")
        });
    assert!(
        output.status.success(),
        "`git ls-files` exited with {}; this guard requires a git checkout",
        output.status
    );
    let lockfiles = String::from_utf8_lossy(&output.stdout)
        .split('\0')
        .filter(|entry| !entry.is_empty())
        .map(|entry| entry.replace('\\', "/"))
        .collect::<BTreeSet<_>>();
    assert!(
        lockfiles.contains("Cargo.lock"),
        "the tracked Cargo lockfile inventory must include the server graph"
    );
    lockfiles
}

#[test]
fn test_msrv_consistency_across_config_files() {
    // This test prevents the MSRV inconsistency issue that was fixed in commit d9eac0f
    // All configuration files must use the same Rust version as defined in Cargo.toml

    let root = repo_root();

    // Extract MSRV from Cargo.toml (single source of truth)
    let cargo_toml = root.join("Cargo.toml");
    let cargo_content = read_file(&cargo_toml);
    let msrv = extract_toml_version(&cargo_content, "rust-version")
        .expect("Could not extract rust-version from Cargo.toml");

    assert!(
        !msrv.is_empty(),
        "MSRV must be set in Cargo.toml rust-version field"
    );

    // Validate rust-toolchain.toml
    let rust_toolchain = root.join("rust-toolchain.toml");
    if rust_toolchain.exists() {
        let toolchain_content = read_file(&rust_toolchain);
        let toolchain_version = extract_yaml_version(&toolchain_content, "channel")
            .expect("Could not extract channel from rust-toolchain.toml");

        assert_eq!(
            toolchain_version, msrv,
            "rust-toolchain.toml channel must match Cargo.toml rust-version.\n\
             Expected: {msrv}\n\
             Found: {toolchain_version}\n\
             Fix: Update rust-toolchain.toml to use channel = \"{msrv}\""
        );
    }

    // Validate clippy.toml
    let clippy_toml = root.join("clippy.toml");
    if clippy_toml.exists() {
        let clippy_content = read_file(&clippy_toml);
        if let Some(clippy_msrv) = extract_toml_version(&clippy_content, "msrv") {
            assert_eq!(
                clippy_msrv, msrv,
                "clippy.toml msrv must match Cargo.toml rust-version.\n\
                 Expected: {msrv}\n\
                 Found: {clippy_msrv}\n\
                 Fix: Update clippy.toml to use msrv = \"{msrv}\""
            );
        }
    }

    // Validate Dockerfile
    let dockerfile = root.join("Dockerfile");
    if dockerfile.exists() {
        let dockerfile_content = read_file(&dockerfile);

        // Look for FROM rust:X.Y line
        let rust_version_in_dockerfile = dockerfile_content
            .lines()
            .find(|line| line.trim().starts_with("FROM rust:"))
            .and_then(|line| {
                // Extract version from "FROM rust:1.88-bookworm" or "FROM rust:1.88"
                line.split(':')
                    .nth(1)
                    .and_then(|s| s.split_whitespace().next())
                    .and_then(|s| s.split('-').next())
                    .map(String::from)
            });

        if let Some(dockerfile_version) = rust_version_in_dockerfile {
            // Docker images may use shortened versions (1.88 instead of 1.88.0)
            // Check if dockerfile version matches MSRV or is a valid prefix
            let msrv_major_minor = to_major_minor(&msrv);
            let version_matches =
                dockerfile_version == msrv || dockerfile_version == msrv_major_minor;

            assert!(
                version_matches,
                "Dockerfile Rust version must match Cargo.toml rust-version.\n\
                 Expected: FROM rust:{msrv} or FROM rust:{msrv_major_minor}\n\
                 Found: FROM rust:{dockerfile_version}\n\
                 Fix: Update Dockerfile to use FROM rust:{msrv}-bookworm or FROM rust:{msrv_major_minor}-bookworm"
            );
        }
    }
}

#[test]
fn test_msrv_version_normalization_logic() {
    // This test validates that our version comparison logic correctly handles
    // both full semver (1.88.0) and Docker's shortened format (1.88).
    //
    // Background: Docker images use "rust:1.88" while Cargo.toml uses "1.88.0".
    // The CI/local scripts must normalize both formats to major.minor for comparison.
    //
    // This test prevents regression of the bug where CI compared "1.88" != "1.88.0"
    // and failed even though the versions were semantically identical.

    // Test case 1: Full semver version (Cargo.toml format)
    let msrv_full = "1.88.0";
    let msrv_major_minor = to_major_minor(msrv_full);
    assert_eq!(msrv_major_minor, "1.88");

    // Test case 2: Docker shortened version should match normalized MSRV
    let dockerfile_version = "1.88";
    assert_eq!(
        dockerfile_version, msrv_major_minor,
        "Normalized MSRV should match Docker version format"
    );

    // Test case 3: Verify that different major.minor versions correctly fail
    let wrong_version = "1.87";
    assert_ne!(
        wrong_version, msrv_major_minor,
        "Different versions should not match"
    );

    // Test case 4: Patch version differences in MSRV shouldn't matter for Docker comparison
    let msrv_different_patch = "1.88.1";
    let normalized_patch = to_major_minor(msrv_different_patch);
    assert_eq!(
        normalized_patch, dockerfile_version,
        "Patch version should be ignored when comparing to Docker format"
    );

    // Test case 5: Verify edge cases with single-digit patch versions
    let msrv_zero_patch = "1.88.0";
    let msrv_nonzero_patch = "1.88.5";
    let norm1 = to_major_minor(msrv_zero_patch);
    let norm2 = to_major_minor(msrv_nonzero_patch);
    assert_eq!(
        norm1, norm2,
        "Both should normalize to same major.minor regardless of patch"
    );
}

#[test]
fn test_ci_workflow_msrv_normalization() {
    // The CI workflow should call the standalone script instead of duplicating
    // MSRV comparison logic inline. The script owns Docker major.minor
    // normalization and has dedicated local tests.

    let root = repo_root();
    let ci_workflow = root.join(".github/workflows/ci.yml");
    let content = read_live_file(&ci_workflow);
    let script_content = read_live_file(&root.join("scripts/check-msrv-consistency.sh"));

    assert!(
        content.contains("bash scripts/check-msrv-consistency.sh"),
        "CI workflow must run scripts/check-msrv-consistency.sh for MSRV consistency.\n\
         Keeping the logic in one script prevents local/CI drift. Invoke through \
         bash so CI does not depend on checkout executable-bit metadata."
    );

    assert!(
        script_content
            .contains("MSRV_SHORT=$(echo \"$MSRV\" | sed -E 's/([0-9]+\\.[0-9]+).*/\\1/')"),
        "scripts/check-msrv-consistency.sh must normalize MSRV to major.minor \
         format for Dockerfile comparison. This prevents false failures when \
         comparing 1.88.0 (Cargo.toml) to 1.88 (Dockerfile)."
    );

    assert!(
        script_content.contains("check_file \"Dockerfile\" \"$MSRV_SHORT\" \"$DOCKERFILE_RUST\""),
        "scripts/check-msrv-consistency.sh must compare Dockerfile version \
         against normalized MSRV_SHORT, not full MSRV."
    );
}

#[test]
fn test_msrv_script_consistency_with_ci() {
    // This test ensures that the local MSRV check script and the CI workflow
    // use the same logic for version comparison.
    //
    // Both must normalize versions to major.minor format to avoid inconsistent
    // behavior between local checks and CI validation.

    let root = repo_root();
    let script = root.join("scripts/check-msrv-consistency.sh");
    let ci_workflow = root.join(".github/workflows/ci.yml");

    if !script.exists() {
        panic!(
            "MSRV consistency check script not found at {}",
            script.display()
        );
    }

    let script_content = read_live_file(&script);
    let ci_content = read_live_file(&ci_workflow);

    // The script should normalize MSRV to major.minor for Dockerfile comparison,
    // and CI should call that script instead of maintaining duplicate logic.
    let normalization_pattern = "sed -E 's/([0-9]+\\.[0-9]+).*/\\1/'";

    assert!(
        script_content.contains(normalization_pattern),
        "Local script must normalize MSRV version (found in check-msrv-consistency.sh)"
    );

    assert!(
        script_content.contains("MSRV_SHORT"),
        "Local script should use MSRV_SHORT variable for normalized version"
    );

    assert!(
        ci_content.contains("bash scripts/check-msrv-consistency.sh"),
        "CI workflow should call scripts/check-msrv-consistency.sh so MSRV \
         consistency logic has a single source of truth."
    );
}

#[test]
fn test_required_ci_workflows_exist() {
    // This test ensures critical CI validation workflows are present
    // Prevents accidental deletion of important CI checks

    let root = repo_root();
    let workflows_dir = root.join(".github/workflows");

    let mut missing_workflows = Vec::new();

    for (workflow_file, description) in REQUIRED_WORKFLOW_FILES {
        let workflow_path = workflows_dir.join(workflow_file);
        if !workflow_path.exists() {
            missing_workflows.push(format!(
                "  - {} ({})\n    Expected at: {}",
                workflow_file,
                description,
                workflow_path.display()
            ));
        }
    }

    if !missing_workflows.is_empty() {
        panic!(
            "Required workflows are missing:\n\n{}\n\n\
             These workflows are required for CI/CD hygiene.\n\
             To fix:\n\
             1. Restore missing workflow files from git history\n\
             2. Or create new workflow files following project patterns\n\
             3. Ensure all workflows are in .github/workflows/",
            missing_workflows.join("\n")
        );
    }
}

