#[test]
fn test_ci_lint_job_reports_clippy_failure_diagnostics() {
    let root = repo_root();
    let workflow = read_live_file(&root.join(".github/workflows/ci.yml"));

    assert!(
        workflow.contains("Show Rust tool versions")
            && workflow.contains("rustc -Vv")
            && workflow.contains("cargo clippy -V")
            && workflow.contains("cargo fmt --version"),
        "ci.yml lint job must print Rust tool versions before linting so \
         platform-only clippy failures include enough environment context."
    );

    let clippy_start = workflow
        .find("      - name: Run clippy")
        .expect("ci.yml must contain a Run clippy step");
    let after_start = &workflow[clippy_start..];
    let clippy_end = after_start
        .find("\n      - name: Check optional feature matrix")
        .expect("Run clippy step must be followed by optional feature matrix step");
    let clippy_step = &after_start[..clippy_end];

    for required in [
        "shell: bash",
        "set -o pipefail",
        "set +e",
        "cargo clippy --locked --all-targets --all-features -- -D warnings",
        "tee clippy-output.txt",
        "pipeline_status=(\"${PIPESTATUS[@]}\")",
        "clippy_status=\"${pipeline_status[0]}\"",
        "tee_status=\"${pipeline_status[1]}\"",
        "status=\"$clippy_status\"",
        "status=\"$tee_status\"",
        "set -e",
        "GITHUB_STEP_SUMMARY",
        "Clippy failure diagnostics",
        "Runner OS: $RUNNER_OS",
        "ansi_escape=\"$(printf '\\033')\"",
        "sed -E",
        "head -n 120",
        "|| true",
        "exit \"$status\"",
    ] {
        assert!(
            clippy_step.contains(required),
            "ci.yml Run clippy step must contain `{required}` for robust failure diagnostics.\n\
             Step block:\n{clippy_step}"
        );
    }
}

#[test]
#[cfg(unix)]
fn test_ci_clippy_shell_status_handling_preserves_pipeline_failures() {
    let cases = [
        (
            "clippy_failure_preserved",
            5,
            "tee clippy-output.txt",
            5,
            "summary=yes",
        ),
        (
            "tee_failure_preserved",
            0,
            "bash -c 'cat >/dev/null; exit 7'",
            7,
            "summary=no",
        ),
        (
            "success_remains_success",
            0,
            "tee clippy-output.txt",
            0,
            "summary=no",
        ),
    ];

    for (name, clippy_exit, tee_command, expected_exit, expected_summary) in cases {
        let temp_dir = tempfile::Builder::new()
            .prefix("signal-fish-clippy-status-")
            .tempdir()
            .unwrap_or_else(|e| panic!("failed to create temp dir: {e}"));
        let script = format!(
            r#"
set -o pipefail
set +e
bash -c 'printf "error: fixture\n"; exit {clippy_exit}' 2>&1 | {tee_command}
pipeline_status=("${{PIPESTATUS[@]}}")
clippy_status="${{pipeline_status[0]}}"
tee_status="${{pipeline_status[1]}}"
status="$clippy_status"
if [ "$status" -eq 0 ] && [ "$tee_status" -ne 0 ]; then
  status="$tee_status"
fi
set -e
if [ "$clippy_status" -ne 0 ]; then
  echo "summary=yes"
else
  echo "summary=no"
fi
echo "clippy=$clippy_status tee=$tee_status status=$status"
exit "$status"
"#
        );

        let output = bash_command()
            .arg("-c")
            .arg(script)
            .current_dir(temp_dir.path())
            .output()
            .unwrap_or_else(|e| panic!("{name}: failed to run status contract script: {e}"));
        let stdout = String::from_utf8_lossy(&output.stdout);
        let stderr = String::from_utf8_lossy(&output.stderr);

        assert_eq!(
            output.status.code(),
            Some(expected_exit),
            "{name}: shell status contract produced wrong exit code.\nstdout:\n{stdout}\nstderr:\n{stderr}"
        );
        assert!(
            stdout.contains(expected_summary),
            "{name}: shell status contract produced wrong summary state.\n\
             Expected marker: {expected_summary}\nstdout:\n{stdout}\nstderr:\n{stderr}"
        );
        assert!(
            stdout.contains(&format!("status={expected_exit}")),
            "{name}: shell status contract did not report final status.\nstdout:\n{stdout}\nstderr:\n{stderr}"
        );
    }
}

#[test]
fn test_ci_workflow_matrix_os_values_match_constant() {
    // Validates that the MATRIX_OS_VALUES constant matches the actual
    // strategy.matrix.os lists in ci.yml. If these drift apart, the
    // bidirectional consistency test will silently produce wrong check names.
    //
    // Multiple jobs (lint, nextest) use matrix.os, so we validate ALL
    // `os:` lines at 8-space indent to ensure consistency across jobs.

    let root = repo_root();
    let ci_content = read_live_file(&root.join(".github/workflows/ci.yml"));

    // Collect ALL "os: [...]" lines from matrix sections (8-space indent).
    // Multiple jobs (lint, nextest) each have their own matrix.os list.
    let os_lines: Vec<&str> = ci_content
        .lines()
        .filter(|line| {
            let trimmed = line.trim();
            trimmed.starts_with("os:") && line.starts_with("        ")
        })
        .collect();

    assert!(
        !os_lines.is_empty(),
        "Could not find any matrix os: lines in ci.yml.\n\
         Expected lines like '        os: [ubuntu-latest, windows-latest, macos-latest]'"
    );

    for (i, os_line) in os_lines.iter().enumerate() {
        // Parse the OS values from the YAML list: "os: [a, b, c]"
        let list_str = os_line
            .trim()
            .strip_prefix("os:")
            .expect("os: prefix missing")
            .trim();
        let inner = list_str
            .strip_prefix('[')
            .and_then(|s| s.strip_suffix(']'))
            .unwrap_or_else(|| {
                panic!(
                    "Could not parse matrix os list #{} from ci.yml.\n\
                     Found: {os_line}\n\
                     Expected format: os: [ubuntu-latest, windows-latest, macos-latest]",
                    i + 1
                )
            });

        let yaml_os_values: Vec<&str> = inner.split(',').map(|s| s.trim()).collect();

        assert_eq!(
            yaml_os_values.len(),
            MATRIX_OS_VALUES.len(),
            "MATRIX_OS_VALUES has {} entries but ci.yml matrix.os line #{} has {} entries.\n\
             MATRIX_OS_VALUES: {:?}\n\
             ci.yml matrix.os: {:?}\n\
             To fix: Update MATRIX_OS_VALUES or the matrix in ci.yml so they match.",
            MATRIX_OS_VALUES.len(),
            i + 1,
            yaml_os_values.len(),
            MATRIX_OS_VALUES,
            yaml_os_values
        );

        for os in &yaml_os_values {
            assert!(
                MATRIX_OS_VALUES.contains(os),
                "ci.yml matrix.os line #{} contains \"{os}\" but MATRIX_OS_VALUES does not.\n\
                 To fix: Add \"{os}\" to MATRIX_OS_VALUES.",
                i + 1
            );
        }

        for os in MATRIX_OS_VALUES {
            assert!(
                yaml_os_values.contains(os),
                "MATRIX_OS_VALUES contains \"{os}\" but ci.yml matrix.os line #{} does not.\n\
                 To fix: Either add \"{os}\" to the matrix in ci.yml or remove it from MATRIX_OS_VALUES.",
                i + 1
            );
        }
    }
}

#[test]
fn test_relay_timing_observations_workflow_is_bounded_complete_and_retainable() {
    let root = repo_root();
    let workflow_path = root.join(".github/workflows/relay-timing-observations.yml");
    assert!(
        workflow_path.exists(),
        "issue #274 requires .github/workflows/relay-timing-observations.yml so hosted timing \n\
         policy is based on retained multi-run evidence instead of isolated log lines"
    );
    let workflow = read_live_file(&workflow_path);
    let documents = Yaml::load_from_str(&workflow).expect("relay timing workflow must parse");
    let document = documents.first().expect("workflow YAML document");
    let triggers = document
        .as_mapping_get("on")
        .or_else(|| document.as_mapping_get("true"))
        .expect("workflow must define triggers");
    let schedule = triggers
        .as_mapping_get("schedule")
        .and_then(Yaml::as_sequence)
        .expect("workflow must define a schedule");
    assert_eq!(
        schedule.len(),
        1,
        "timing sampling has one canonical cadence"
    );
    assert_eq!(
        schedule[0].as_mapping_get("cron").and_then(Yaml::as_str),
        Some("30 5 * * *")
    );
    assert!(
        triggers.as_mapping_get("workflow_dispatch").is_some(),
        "manual diagnostic sampling must remain available"
    );
    let pull_request = triggers
        .as_mapping_get("pull_request")
        .expect("workflow changes must validate on pull requests");
    assert_eq!(
        pull_request
            .as_mapping_get("branches")
            .and_then(Yaml::as_sequence)
            .expect("pull request branch filter")
            .iter()
            .map(|value| value.as_str().expect("branch string"))
            .collect::<Vec<_>>(),
        vec!["main"]
    );
    assert_eq!(
        pull_request
            .as_mapping_get("paths")
            .and_then(Yaml::as_sequence)
            .expect("pull request path filter")
            .iter()
            .map(|value| value.as_str().expect("path string"))
            .collect::<BTreeSet<_>>(),
        BTreeSet::from([
            "tests/sixteen_player_matrix_e2e.rs",
            ".github/workflows/relay-timing-observations.yml",
        ])
    );

    let concurrency = document
        .as_mapping_get("concurrency")
        .expect("timing attempts need explicit concurrency semantics");
    assert_eq!(
        concurrency
            .as_mapping_get("cancel-in-progress")
            .and_then(Yaml::as_bool),
        Some(false),
        "manual or overlapping runs must not cancel an eligible scheduled attempt"
    );
    assert_eq!(
        document
            .as_mapping_get("env")
            .and_then(|env| env.as_mapping_get("REPETITIONS"))
            .and_then(Yaml::as_integer),
        Some(5)
    );
    assert_eq!(
        document
            .as_mapping_get("env")
            .and_then(|env| env.as_mapping_get("SIGNAL_FISH_RELAY_WORKLOAD_VERSION"))
            .and_then(Yaml::as_str),
        Some("relay-clean-v1")
    );

    let job = document
        .as_mapping_get("jobs")
        .and_then(|jobs| jobs.as_mapping_get("observations"))
        .expect("workflow must define the observations job");
    assert!(
        job.as_mapping_get("if").is_none(),
        "job must be unconditional"
    );
    assert!(
        job.as_mapping_get("needs").is_none(),
        "a skipped dependency must not erase a timing attempt"
    );
    assert_failure_is_not_swallowed(job, "the observations job");
    assert_eq!(
        job.as_mapping_get("runs-on").and_then(Yaml::as_str),
        Some("${{ matrix.os }}")
    );
    assert_eq!(
        job.as_mapping_get("timeout-minutes")
            .and_then(Yaml::as_integer),
        Some(45)
    );
    let strategy = job.as_mapping_get("strategy").expect("matrix strategy");
    assert_eq!(
        strategy.as_mapping_get("fail-fast").and_then(Yaml::as_bool),
        Some(false)
    );
    let matrix = strategy
        .as_mapping_get("matrix")
        .expect("observation OS matrix");
    for narrowing in ["include", "exclude"] {
        assert!(
            matrix.as_mapping_get(narrowing).is_none(),
            "matrix.{narrowing} can silently narrow the platform evidence"
        );
    }
    assert_eq!(
        matrix
            .as_mapping_get("os")
            .and_then(Yaml::as_sequence)
            .expect("matrix.os")
            .iter()
            .map(|value| value.as_str().expect("OS string"))
            .collect::<Vec<_>>(),
        vec!["ubuntu-latest", "windows-latest", "macos-latest"]
    );

    let steps = job
        .as_mapping_get("steps")
        .and_then(Yaml::as_sequence)
        .expect("observation steps");
    for step in steps {
        assert_failure_is_not_swallowed(step, "every observation step");
    }
    let named_step = |name: &str| {
        steps
            .iter()
            .find(|step| step.as_mapping_get("name").and_then(Yaml::as_str) == Some(name))
            .unwrap_or_else(|| panic!("missing `{name}` step"))
    };
    let capture = named_step("Capture repeated clean relay observations");
    assert!(capture.as_mapping_get("if").is_none());
    assert_eq!(
        capture.as_mapping_get("shell").and_then(Yaml::as_str),
        Some("bash")
    );
    let capture_run = capture
        .as_mapping_get("run")
        .and_then(Yaml::as_str)
        .expect("capture command");
    for required in [
        "set -euo pipefail",
        "SIGNAL_FISH_RELAY_OBSERVATIONS_JSONL=relay-timing-observations.jsonl",
        "expected_rows=$((REPETITIONS * 6))",
    ] {
        assert!(
            capture_run.contains(required),
            "capture step lost `{required}`"
        );
    }
    assert!(
        !capture_run.contains("|| true"),
        "capture must propagate every semantic test failure"
    );
    let cargo_commands: Vec<String> = shell_logical_lines(capture_run)
        .into_iter()
        .filter(|line| line.contains("cargo test"))
        .collect();
    assert_eq!(
        cargo_commands,
        vec![
            "cargo test --locked --all-features --test sixteen_player_matrix_e2e \
             hosted_timing_profile_keeps_backpressure_gate_without_wall_clock_gate -- --exact",
            "SIGNAL_FISH_RELAY_OBSERVATIONS_JSONL=relay-timing-observations.jsonl \
             SIGNAL_FISH_RELAY_OBSERVATION_SAMPLE=\"$sample\" cargo test --locked \
             --all-features --test sixteen_player_matrix_e2e \
             hosted_relay_timing_observations_preserve_semantic_oracles -- --exact --ignored \
             --nocapture --test-threads=1 2>&1 | tee -a relay-timing-output.log",
        ],
        "the profile guard and the one repeated observation invocation must each \
         retain their exact all-feature selector and harness flags"
    );

    let manifest = named_step("Write attempt manifest");
    assert_eq!(
        manifest.as_mapping_get("if").and_then(Yaml::as_str),
        Some("always()")
    );
    let manifest_run = manifest
        .as_mapping_get("run")
        .and_then(Yaml::as_str)
        .expect("attempt manifest command");
    for required in [
        "GITHUB_EVENT_NAME",
        "GITHUB_RUN_ATTEMPT",
        "SIGNAL_FISH_RELAY_WORKLOAD_VERSION",
        "SIGNAL_FISH_RUST_TOOLCHAIN",
        "ImageVersion",
        "actual_rows",
        "complete",
        "eligible",
        "relay-timing-attempt.json",
    ] {
        assert!(
            manifest_run.contains(required),
            "attempt manifest lost `{required}`"
        );
    }

    let upload = named_step("Upload raw and machine-readable observations");
    assert_eq!(
        upload.as_mapping_get("if").and_then(Yaml::as_str),
        Some("always()")
    );
    assert_eq!(
        upload.as_mapping_get("uses").and_then(Yaml::as_str),
        Some("actions/upload-artifact@v7.0.1")
    );
    let with = upload.as_mapping_get("with").expect("upload settings");
    let paths = with
        .as_mapping_get("path")
        .and_then(Yaml::as_str)
        .expect("artifact paths");
    for required in [
        "relay-timing-observations.jsonl",
        "relay-timing-output.log",
        "relay-timing-attempt.json",
    ] {
        assert!(paths.lines().any(|line| line.trim() == required));
    }
    assert_eq!(
        with.as_mapping_get("retention-days")
            .and_then(Yaml::as_integer),
        Some(30),
        "the repository caps artifact retention at 30 days; the workflow must request the \n\
         effective value instead of emitting a warning while claiming 90 days"
    );
    assert_eq!(
        with.as_mapping_get("if-no-files-found")
            .and_then(Yaml::as_str),
        Some("error")
    );

    let nightly_path = root.join(".github/workflows/verification-nightly.yml");
    let nightly = read_live_file(&nightly_path);
    let nightly_documents =
        Yaml::load_from_str(&nightly).expect("verification nightly workflow must parse");
    let nightly_job = nightly_documents
        .first()
        .and_then(|document| document.as_mapping_get("jobs"))
        .and_then(|jobs| jobs.as_mapping_get("scenario-profiles"))
        .expect("verification nightly must retain the scenario-profiles job");
    let nightly_matrix_run = nightly_job
        .as_mapping_get("steps")
        .and_then(Yaml::as_sequence)
        .and_then(|steps| {
            steps.iter().find(|step| {
                step.as_mapping_get("name").and_then(Yaml::as_str)
                    == Some("Run 16-player relay matrix and knee sweep")
            })
        })
        .and_then(|step| step.as_mapping_get("run"))
        .and_then(Yaml::as_str)
        .expect("verification nightly relay-matrix command");
    let nightly_cargo_commands: Vec<String> = shell_logical_lines(nightly_matrix_run)
        .into_iter()
        .filter(|line| line.contains("cargo nextest"))
        .collect();
    assert_eq!(
        nightly_cargo_commands,
        vec![
            "cargo nextest run --profile ci --locked --all-features --test \
             sixteen_player_matrix_e2e --run-ignored all --success-output final -- --skip \
             hosted_relay_timing_observations_preserve_semantic_oracles 2>&1 | tee \
             relay-matrix-output.txt"
        ],
        "nightly must retain its complete matrix/fault/knee selection and exclude only the \
         dedicated hosted observation selector"
    );
}

#[test]
fn test_verification_nightly_retains_h14_hosted_attempt_evidence() {
    let root = repo_root();
    let workflow_path = root.join(".github/workflows/verification-nightly.yml");
    let workflow = read_live_file(&workflow_path);
    let documents = Yaml::load_from_str(&workflow).expect("verification nightly must parse");
    let document = documents.first().expect("workflow YAML document");
    let job = document
        .as_mapping_get("jobs")
        .and_then(|jobs| jobs.as_mapping_get("scenario-profiles"))
        .expect("verification nightly must retain the scenario-profiles job");
    assert!(
        job.as_mapping_get("needs").is_none(),
        "a skipped dependency must not erase an eligible H14 attempt"
    );
    assert_eq!(
        document
            .as_mapping_get("env")
            .and_then(|env| env.as_mapping_get("SIGNAL_FISH_H14_CONTRACT_VERSION"))
            .and_then(Yaml::as_str),
        Some("h14-capacity-v1"),
        "the hosted cohort needs a stable contract identifier"
    );

    let steps = job
        .as_mapping_get("steps")
        .and_then(Yaml::as_sequence)
        .expect("scenario-profiles steps");
    let named_step_index = |name: &str| {
        steps
            .iter()
            .position(|step| step.as_mapping_get("name").and_then(Yaml::as_str) == Some(name))
            .unwrap_or_else(|| panic!("missing `{name}` step"))
    };
    for (name, id) in [
        ("Checkout repository", "checkout"),
        ("Read Rust toolchain", "toolchain"),
        ("Install Rust toolchain", "install-rust"),
        ("Install cargo-nextest", "install-nextest"),
    ] {
        let step = &steps[named_step_index(name)];
        assert_eq!(
            step.as_mapping_get("id").and_then(Yaml::as_str),
            Some(id),
            "`{name}` needs a stable id so H14 can distinguish setup failure from a test RED"
        );
    }

    let h14_index = named_step_index("Run mixed-encoding amplification experiment");
    let h14 = &steps[h14_index];
    assert_eq!(h14.as_mapping_get("id").and_then(Yaml::as_str), Some("h14"));
    let h14_condition = h14
        .as_mapping_get("if")
        .and_then(Yaml::as_str)
        .expect("H14 condition");
    assert_eq!(
        h14_condition.split_whitespace().collect::<Vec<_>>(),
        "${{ github.event_name != 'pull_request' && always() && !cancelled() && \
         steps.checkout.outcome == 'success' && \
         steps.toolchain.outcome == 'success' && steps.install-rust.outcome == 'success' && \
         steps.install-nextest.outcome == 'success' }}"
            .split_whitespace()
            .collect::<Vec<_>>(),
        "H14 must survive unrelated test failures without running after cancellation or missing setup"
    );
    assert!(
        h14.as_mapping_get("continue-on-error").is_none(),
        "a RED H14 result must still fail the nightly job"
    );
    let h14_run = h14
        .as_mapping_get("run")
        .and_then(Yaml::as_str)
        .expect("H14 command");
    for required in ["set -euo pipefail", ": > h14-started", "h14-exit-code.txt"] {
        assert!(h14_run.contains(required), "H14 step lost `{required}`");
    }
    assert!(
        !h14_run.contains("|| true"),
        "H14 must propagate the exact selector's exit status"
    );
    let h14_cargo_commands: Vec<String> = shell_logical_lines(h14_run)
        .into_iter()
        .filter(|line| line.contains("cargo nextest"))
        .collect();
    assert_eq!(
        h14_cargo_commands,
        vec![
            "cargo nextest run --profile ci --locked --all-features --test \
             mixed_encoding_relay_e2e --run-ignored ignored-only -E \
             'test(=unsupported_message_pack_fallback_does_not_flap_weaker_recipient)' \
             --no-tests fail --success-output final 2>&1 | tee mixed-encoding-output.txt"
        ],
        "the hosted cohort must retain its existing Nextest context and exact H14 selector"
    );
    let selector_occurrences = steps
        .iter()
        .filter_map(|step| step.as_mapping_get("run").and_then(Yaml::as_str))
        .map(|run| {
            run.matches("unsupported_message_pack_fallback_does_not_flap_weaker_recipient")
                .count()
        })
        .sum::<usize>();
    assert_eq!(
        selector_occurrences, 1,
        "H14 must execute exactly once per scenario-profiles job"
    );

    let manifest_index = named_step_index("Write H14 attempt manifest");
    assert_eq!(
        manifest_index,
        h14_index + 1,
        "capture H14 metadata before a later experiment can fail or time out"
    );
    let manifest = &steps[manifest_index];
    assert_eq!(
        manifest.as_mapping_get("if").and_then(Yaml::as_str),
        Some("always() && github.event_name != 'pull_request'")
    );
    let manifest_env = manifest
        .as_mapping_get("env")
        .expect("manifest environment");
    assert_eq!(
        manifest_env
            .as_mapping_get("H14_OUTCOME")
            .and_then(Yaml::as_str),
        Some("${{ steps.h14.outcome }}"),
        "aggregate job.status would misclassify H14 after an unrelated precursor failure"
    );
    let manifest_run = manifest
        .as_mapping_get("run")
        .and_then(Yaml::as_str)
        .expect("manifest command");
    for required in [
        "GITHUB_EVENT_NAME",
        "GITHUB_RUN_ID",
        "GITHUB_RUN_ATTEMPT",
        "GITHUB_SHA",
        "SIGNAL_FISH_H14_CONTRACT_VERSION",
        "SIGNAL_FISH_RUST_TOOLCHAIN",
        "ImageOS",
        "ImageVersion",
        "H14_OUTCOME",
        "raw_log_present",
        "raw_log_bytes",
        "evidence_complete",
        "passed",
        "eligible",
        "h14-attempt.json",
        "[ \"$raw_log_bytes\" -gt 0 ]",
        "[ \"$evidence_complete\" = true ]",
    ] {
        assert!(
            manifest_run.contains(required),
            "H14 attempt manifest lost `{required}`"
        );
    }
    assert!(
        manifest_run.contains(
            "if [ \"$GITHUB_EVENT_NAME\" = \"schedule\" ] && [ \"$GITHUB_RUN_ATTEMPT\" = \"1\" ]"
        ),
        "eligibility must depend only on a scheduled first attempt, never its outcome"
    );

    let upload_index = named_step_index("Upload H14 attempt evidence");
    assert_eq!(
        upload_index,
        manifest_index + 1,
        "upload H14 evidence immediately after writing its manifest"
    );
    let upload = &steps[upload_index];
    assert_eq!(
        upload.as_mapping_get("if").and_then(Yaml::as_str),
        Some("always() && github.event_name != 'pull_request'")
    );
    assert_eq!(
        upload.as_mapping_get("uses").and_then(Yaml::as_str),
        Some("actions/upload-artifact@v7.0.1")
    );
    let upload_with = upload.as_mapping_get("with").expect("H14 upload settings");
    assert_eq!(
        upload_with.as_mapping_get("name").and_then(Yaml::as_str),
        Some("h14-${{ github.run_id }}-${{ github.run_attempt }}")
    );
    let paths = upload_with
        .as_mapping_get("path")
        .and_then(Yaml::as_str)
        .expect("H14 artifact paths");
    assert_eq!(
        paths.lines().map(str::trim).collect::<Vec<_>>(),
        vec!["mixed-encoding-output.txt", "h14-attempt.json"]
    );
    assert_eq!(
        upload_with
            .as_mapping_get("retention-days")
            .and_then(Yaml::as_integer),
        Some(30),
        "request the repository's effective retention maximum"
    );
    assert_eq!(
        upload_with
            .as_mapping_get("if-no-files-found")
            .and_then(Yaml::as_str),
        Some("error")
    );
}

#[test]
fn test_verification_nightly_retains_multiprocess_pause_resume_evidence() {
    let workflow = read_live_file(&repo_root().join(".github/workflows/verification-nightly.yml"));
    let documents =
        Yaml::load_from_str(&workflow).expect("verification nightly workflow must parse");
    let job = documents[0]
        .as_mapping_get("jobs")
        .and_then(|jobs| jobs.as_mapping_get("multiprocess-delivery"))
        .expect("verification nightly must retain multiprocess-delivery");
    assert_failure_is_not_swallowed(job, "multiprocess-delivery job");
    assert_eq!(
        job.as_mapping_get("runs-on").and_then(Yaml::as_str),
        Some("ubuntu-latest")
    );
    let steps = job
        .as_mapping_get("steps")
        .and_then(Yaml::as_sequence)
        .expect("multiprocess-delivery steps");
    let run_index = steps
        .iter()
        .position(|step| {
            step.as_mapping_get("name").and_then(Yaml::as_str)
                == Some("Run multi-process delivery fault tests")
        })
        .expect("multiprocess run step");
    let run = &steps[run_index];
    assert_failure_is_not_swallowed(run, "multiprocess delivery fault-test step");
    assert_eq!(
        run.as_mapping_get("env")
            .and_then(|env| env.as_mapping_get("SIGNAL_FISH_CLIENT_BIN"))
            .and_then(Yaml::as_str),
        Some("${{ github.workspace }}/clients/native/target/debug/signal-fish-reference-native")
    );
    assert_eq!(
        run.as_mapping_get("env")
            .and_then(|env| env.as_mapping_get("SIGNAL_FISH_MULTIPROCESS_EVIDENCE_DIR"))
            .and_then(Yaml::as_str),
        Some("${{ runner.temp }}/multiprocess-delivery")
    );
    let command = run
        .as_mapping_get("run")
        .and_then(Yaml::as_str)
        .expect("multiprocess run command");
    let logical_lines = shell_logical_lines(command);
    assert_eq!(
        logical_lines.first().map(String::as_str),
        Some("set -o pipefail")
    );
    assert_eq!(
        logical_lines
            .iter()
            .filter(|line| line.contains("cargo nextest"))
            .map(String::as_str)
            .collect::<Vec<_>>(),
        vec![
            "cargo nextest run --profile ci --locked --all-features --test \
             multiprocess_delivery_e2e --run-ignored all --success-output final 2>&1 | tee \
             multiprocess-output.txt"
        ]
    );
    assert!(
        !command.contains("|| true") && !command.contains("; true"),
        "multiprocess failures must not be swallowed"
    );

    let source = read_file(&repo_root().join("tests/multiprocess_delivery_e2e.rs"));
    let file = syn::parse_file(&source).expect("multiprocess_delivery_e2e.rs must parse as Rust");
    let resume_tests = file
        .items
        .iter()
        .filter_map(|item| match item {
            Item::Fn(function)
                if function.sig.ident
                    == "sigstop_then_resume_preserves_v3_delivery_accountability" =>
            {
                Some(function)
            }
            _ => None,
        })
        .collect::<Vec<_>>();
    assert_eq!(
        resume_tests.len(),
        2,
        "multiprocess suite must define Linux and unsupported-platform pause/resume registrations"
    );
    let resume_test = resume_tests
        .iter()
        .copied()
        .find(|function| {
            function.attrs.iter().any(|attribute| {
                attribute.path().is_ident("cfg")
                    && matches!(
                        &attribute.meta,
                        Meta::List(list) if list.tokens.to_string() == "target_os = \"linux\""
                    )
            })
        })
        .expect("multiprocess suite must define the Linux pause/resume test");
    assert!(
        resume_test.attrs.iter().any(|attribute| {
            attribute.path().is_ident("cfg")
                && matches!(
                    &attribute.meta,
                    Meta::List(list) if list.tokens.to_string() == "target_os = \"linux\""
                )
        }),
        "nightly pause/resume test must be explicitly Linux-only"
    );
    assert!(
        resume_test.attrs.iter().any(|attribute| {
            attribute.path().is_ident("ignore")
                && matches!(
                    &attribute.meta,
                    Meta::NameValue(value)
                        if matches!(
                            &value.value,
                            Expr::Lit(literal)
                                if matches!(
                                    &literal.lit,
                                    Lit::Str(reason)
                                        if reason.value()
                                            == "nightly-only (verification-nightly.yml): Linux SIGSTOP/SIGCONT with the clients/native binary"
                                )
                        )
                )
        }),
        "nightly pause/resume test must retain its exact ignored-test reason"
    );
    let unsupported = resume_tests
        .iter()
        .copied()
        .find(|function| {
            function.attrs.iter().any(|attribute| {
                attribute.path().is_ident("cfg")
                    && matches!(
                        &attribute.meta,
                        Meta::List(list)
                            if list.tokens.to_string()
                                == "not (target_os = \"linux\")"
                    )
            })
        })
        .expect("multiprocess suite must register an unsupported-platform pause/resume test");
    assert!(
        unsupported
            .attrs
            .iter()
            .any(|attribute| attribute.path().is_ident("test")),
        "unsupported-platform pause/resume registration must remain a test"
    );
    assert!(
        unsupported.attrs.iter().any(|attribute| {
            attribute.path().is_ident("ignore")
                && matches!(
                    &attribute.meta,
                    Meta::NameValue(value)
                        if matches!(
                            &value.value,
                            Expr::Lit(literal)
                                if matches!(
                                    &literal.lit,
                                    Lit::Str(reason)
                                        if reason.value()
                                            == "unsupported platform: requires Linux SIGSTOP/SIGCONT plus /proc process-state synchronization"
                                )
                        )
                )
        }),
        "unsupported-platform pause/resume test must retain its exact ignored reason"
    );

    let upload = steps
        .get(run_index + 1)
        .expect("evidence upload immediately follows the multiprocess run");
    assert_eq!(
        upload.as_mapping_get("name").and_then(Yaml::as_str),
        Some("Upload multi-process delivery evidence")
    );
    assert_eq!(
        upload.as_mapping_get("if").and_then(Yaml::as_str),
        Some("always()")
    );
    assert_eq!(
        upload.as_mapping_get("uses").and_then(Yaml::as_str),
        Some("actions/upload-artifact@v7.0.1")
    );
    let with = upload.as_mapping_get("with").expect("upload settings");
    assert_eq!(
        with.as_mapping_get("name").and_then(Yaml::as_str),
        Some("multiprocess-delivery-${{ github.run_id }}-${{ github.run_attempt }}")
    );
    let paths = with
        .as_mapping_get("path")
        .and_then(Yaml::as_str)
        .expect("multiprocess artifact paths");
    for required in [
        "multiprocess-output.txt",
        "${{ runner.temp }}/multiprocess-delivery/**",
    ] {
        assert!(
            paths.lines().any(|line| line.trim() == required),
            "multiprocess artifact paths lost `{required}`"
        );
    }
    assert_eq!(
        with.as_mapping_get("retention-days")
            .and_then(Yaml::as_integer),
        Some(30)
    );
    assert_eq!(
        with.as_mapping_get("if-no-files-found")
            .and_then(Yaml::as_str),
        Some("error")
    );
}

#[test]
fn test_h14_pr_gate_is_isolated_and_covers_its_complete_input_surface() {
    let root = repo_root();
    let workflow_path = root.join(".github/workflows/h14-pr.yml");
    let workflow = read_live_file(&workflow_path);
    let documents = Yaml::load_from_str(&workflow).expect("H14 PR workflow must parse");
    let document = documents.first().expect("workflow YAML document");
    let triggers = document
        .as_mapping_get("on")
        .or_else(|| document.as_mapping_get("true"))
        .expect("H14 PR workflow triggers");
    assert_eq!(
        triggers.as_mapping().map(saphyr::Mapping::len),
        Some(1),
        "the isolated H14 gate must allocate only for pull requests"
    );
    let pull_request = triggers
        .as_mapping_get("pull_request")
        .expect("H14 gate must run for pull requests");
    let configured = pull_request
        .as_mapping_get("paths")
        .and_then(Yaml::as_sequence)
        .expect("H14 pull-request paths")
        .iter()
        .map(|value| value.as_str().expect("each trigger path is a string"))
        .collect::<BTreeSet<_>>();
    let expected = [
        "src/**",
        "tests/mixed_encoding_relay_e2e.rs",
        "tests/test_helpers.rs",
        "tests/websocket_test_helpers/**",
        "Cargo.toml",
        "Cargo.lock",
        "rust-toolchain.toml",
        ".config/nextest.toml",
        "scripts/read-toml-string.sh",
        ".github/workflows/h14-pr.yml",
        ".github/workflows/verification-nightly.yml",
    ]
    .into_iter()
    .collect::<BTreeSet<_>>();
    assert_eq!(configured, expected, "H14 trigger inputs drifted");

    let nightly_workflow = read_live_file(&root.join(".github/workflows/verification-nightly.yml"));
    let nightly_documents =
        Yaml::load_from_str(&nightly_workflow).expect("verification nightly must parse");
    let nightly_triggers = nightly_documents[0]
        .as_mapping_get("on")
        .or_else(|| nightly_documents[0].as_mapping_get("true"))
        .expect("verification nightly triggers");
    let broad_pr_paths = nightly_triggers
        .as_mapping_get("pull_request")
        .and_then(|trigger| trigger.as_mapping_get("paths"))
        .and_then(Yaml::as_sequence)
        .expect("verification nightly pull-request paths");
    assert!(
        !broad_pr_paths
            .iter()
            .any(|path| { path.as_str() == Some("tests/mixed_encoding_relay_e2e.rs") }),
        "the isolated H14 test must not allocate the complete nightly workflow"
    );

    let job = document
        .as_mapping_get("jobs")
        .and_then(|jobs| jobs.as_mapping_get("h14"))
        .expect("isolated H14 job");
    assert_eq!(
        job.as_mapping_get("timeout-minutes")
            .and_then(Yaml::as_integer),
        Some(20)
    );
    let steps = job
        .as_mapping_get("steps")
        .and_then(Yaml::as_sequence)
        .expect("H14 PR steps");
    let h14_run = steps
        .iter()
        .find(|step| {
            step.as_mapping_get("name").and_then(Yaml::as_str)
                == Some("Run mixed-encoding amplification experiment")
        })
        .and_then(|step| step.as_mapping_get("run"))
        .and_then(Yaml::as_str)
        .expect("H14 PR command");
    let cargo_commands = shell_logical_lines(h14_run)
        .into_iter()
        .filter(|line| line.contains("cargo nextest"))
        .collect::<Vec<_>>();
    assert_eq!(
        cargo_commands,
        vec![
            "cargo nextest run --profile ci --locked --all-features --test \
             mixed_encoding_relay_e2e --run-ignored ignored-only -E \
             'test(=unsupported_message_pack_fallback_does_not_flap_weaker_recipient)' \
             --no-tests fail --success-output final 2>&1 | tee mixed-encoding-output.txt"
        ],
        "the isolated PR gate must retain the exact hosted H14 selector and context"
    );
    let upload = steps
        .iter()
        .find(|step| {
            step.as_mapping_get("name").and_then(Yaml::as_str) == Some("Upload H14 diagnostics")
        })
        .expect("H14 PR diagnostic upload");
    assert_eq!(
        upload.as_mapping_get("if").and_then(Yaml::as_str),
        Some("always()")
    );
    assert_eq!(
        upload.as_mapping_get("uses").and_then(Yaml::as_str),
        Some("actions/upload-artifact@v7.0.1")
    );
    let upload_with = upload.as_mapping_get("with").expect("upload settings");
    assert_eq!(
        upload_with.as_mapping_get("path").and_then(Yaml::as_str),
        Some("mixed-encoding-output.txt")
    );
    assert_eq!(
        upload_with
            .as_mapping_get("if-no-files-found")
            .and_then(Yaml::as_str),
        Some("error")
    );
}

#[test]
#[cfg(unix)]
fn test_h14_attempt_manifest_classifies_behavioral_fixtures() {
    let workflow = read_live_file(&repo_root().join(".github/workflows/verification-nightly.yml"));
    let documents = Yaml::load_from_str(&workflow).expect("verification nightly must parse");
    let steps = documents[0]
        .as_mapping_get("jobs")
        .and_then(|jobs| jobs.as_mapping_get("scenario-profiles"))
        .and_then(|job| job.as_mapping_get("steps"))
        .and_then(Yaml::as_sequence)
        .expect("scenario-profiles steps");
    let manifest_run = steps
        .iter()
        .find(|step| {
            step.as_mapping_get("name").and_then(Yaml::as_str) == Some("Write H14 attempt manifest")
        })
        .and_then(|step| step.as_mapping_get("run"))
        .and_then(Yaml::as_str)
        .expect("H14 attempt manifest command");

    struct Case {
        name: &'static str,
        started: bool,
        exit_code: Option<i32>,
        raw_log: Option<&'static str>,
        h14_outcome: &'static str,
        job_status: &'static str,
        expected_complete: bool,
        expected_passed: bool,
    }

    let cases = [
        Case {
            name: "success_after_unrelated_failure",
            started: true,
            exit_code: Some(0),
            raw_log: Some("nextest H14 passed\n"),
            h14_outcome: "success",
            job_status: "failure",
            expected_complete: true,
            expected_passed: true,
        },
        Case {
            name: "h14_failure",
            started: true,
            exit_code: Some(101),
            raw_log: Some("nextest H14 failed\n"),
            h14_outcome: "failure",
            job_status: "failure",
            expected_complete: true,
            expected_passed: false,
        },
        Case {
            name: "upstream_skipped",
            started: false,
            exit_code: None,
            raw_log: None,
            h14_outcome: "skipped",
            job_status: "failure",
            expected_complete: false,
            expected_passed: false,
        },
        Case {
            name: "empty_log_cannot_pass",
            started: true,
            exit_code: Some(0),
            raw_log: Some(""),
            h14_outcome: "success",
            job_status: "success",
            expected_complete: false,
            expected_passed: false,
        },
    ];

    for case in cases {
        let temp_dir = unique_temp_dir(&format!("h14-manifest-{}", case.name));
        if case.started {
            write_file(&temp_dir.path().join("h14-started"), "");
        }
        if let Some(exit_code) = case.exit_code {
            write_file(
                &temp_dir.path().join("h14-exit-code.txt"),
                &format!("{exit_code}\n"),
            );
        }
        if let Some(raw_log) = case.raw_log {
            write_file(&temp_dir.path().join("mixed-encoding-output.txt"), raw_log);
        }

        let output = bash_command()
            .arg("-c")
            .arg(manifest_run)
            .current_dir(temp_dir.path())
            .env("H14_OUTCOME", case.h14_outcome)
            .env("JOB_STATUS", case.job_status)
            .env("SIGNAL_FISH_RUST_TOOLCHAIN", "1.91.0")
            .env("SIGNAL_FISH_H14_CONTRACT_VERSION", "h14-capacity-v1")
            .env("GITHUB_EVENT_NAME", "schedule")
            .env("GITHUB_RUN_ID", "123456")
            .env("GITHUB_RUN_ATTEMPT", "1")
            .env("GITHUB_SHA", "0123456789abcdef")
            .env("RUNNER_OS", "Linux")
            .env("ImageOS", "ubuntu24")
            .env("ImageVersion", "20260801.1")
            .output()
            .unwrap_or_else(|e| panic!("{}: failed to run manifest script: {e}", case.name));
        assert!(
            output.status.success(),
            "{}: manifest script failed:\nstdout:\n{}\nstderr:\n{}",
            case.name,
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        );

        let manifest_text = read_file(&temp_dir.path().join("h14-attempt.json"));
        let manifest: serde_json::Value = serde_json::from_str(&manifest_text)
            .unwrap_or_else(|e| panic!("{}: invalid manifest JSON: {e}", case.name));
        assert_eq!(manifest["eligible"].as_bool(), Some(true), "{}", case.name);
        assert_eq!(
            manifest["evidence_complete"].as_bool(),
            Some(case.expected_complete),
            "{}",
            case.name
        );
        assert_eq!(
            manifest["passed"].as_bool(),
            Some(case.expected_passed),
            "{}",
            case.name
        );
        assert_eq!(
            manifest["h14_outcome"].as_str(),
            Some(case.h14_outcome),
            "{}",
            case.name
        );
        assert_eq!(
            manifest["job_status"].as_str(),
            Some(case.job_status),
            "{}",
            case.name
        );
    }
}

