#[test]
fn test_automation_files_avoid_unpinned_tool_execution_patterns() {
    // Prevent recurrence of supply-chain patterns in executable automation:
    // - npx runtime downloads
    // - external Docker image :latest tags
    let root = repo_root();
    let mut automation_files = Vec::new();

    for dir in [root.join("scripts"), root.join(".github/workflows")] {
        if !dir.exists() {
            continue;
        }
        for entry in std::fs::read_dir(dir).expect("read_dir should succeed") {
            let entry = entry.expect("directory entry should be readable");
            let path = entry.path();
            if !path.is_file() {
                continue;
            }
            let is_sh = path.extension().map(|e| e == "sh").unwrap_or(false);
            let is_yaml = path
                .extension()
                .map(|e| e == "yml" || e == "yaml")
                .unwrap_or(false);
            if is_sh || is_yaml {
                automation_files.push(path);
            }
        }
    }
    let pre_commit_hook = root.join(".githooks/pre-commit");
    if pre_commit_hook.exists() {
        automation_files.push(pre_commit_hook);
    }

    let npx_pattern = regex::Regex::new(
        r"(?m)^[[:space:]]*npx([[:space:]]|$)|[;&|][[:space:]]*npx([[:space:]]|$)",
    )
    .expect("valid npx invocation regex");
    let external_latest_pattern =
        regex::Regex::new(r"([A-Za-z0-9._-]+/[A-Za-z0-9._/-]+):[Ll][Aa][Tt][Ee][Ss][Tt]")
            .expect("valid docker image regex");

    let mut violations = Vec::new();
    let first_party_refs = expected_first_party_image_refs();

    for path in automation_files {
        let content = read_file(&path);
        if npx_pattern.is_match(&content) {
            violations.push(format!(
                "{}: contains 'npx' invocation (runtime package execution is disallowed in automation)",
                path.display()
            ));
        }

        for captures in external_latest_pattern.captures_iter(&content) {
            let image = captures.get(1).map(|m| m.as_str()).unwrap_or_default();
            let is_allowed_first_party = first_party_refs.contains(image);
            if !is_allowed_first_party {
                violations.push(format!(
                    "{}: external image uses mutable ':latest' tag: {image}:latest",
                    path.display()
                ));
            }
        }
    }

    assert!(
        violations.is_empty(),
        "Automation files contain unpinned tooling execution patterns.\n\
         Fix by pinning tool versions and avoiding npx/runtime latest tags.\n\
         Violations:\n  - {}",
        violations.join("\n  - ")
    );
}

#[test]
fn test_docker_publish_workflow_generates_owner_derived_metadata_locally() {
    let root = repo_root();
    let workflow_path = root.join(".github/workflows/docker-publish.yml");
    let content = read_file(&workflow_path);
    let content_live = strip_comment_lines(&content);
    let metadata_step = extract_named_workflow_step(&content_live, "Prepare Docker metadata")
        .expect("docker-publish.yml must contain its local metadata step");
    let build_step = extract_named_workflow_step(&content_live, "Build and push Docker image")
        .expect("docker-publish.yml must contain its Docker build step");

    assert!(
        content_live.contains("GITHUB_REPOSITORY_OWNER"),
        "docker-publish.yml must derive GHCR image owner from GITHUB_REPOSITORY_OWNER."
    );
    assert!(
        content_live.contains("GITHUB_REPOSITORY#*/"),
        "docker-publish.yml must derive GHCR repository name from GITHUB_REPOSITORY."
    );
    assert!(
        metadata_step.contains("IMAGE: ${{ steps.image.outputs.name }}"),
        "docker-publish.yml must pass the derived image name to its local metadata step."
    );
    assert!(
        !metadata_step.contains("docker/metadata-action"),
        "docker-publish.yml local metadata step must not call the GitHub repository API through docker/metadata-action."
    );
    for required in [
        "image_title=${GITHUB_REPOSITORY#*/}",
        "Cargo.toml description package",
        "Cargo.toml license package",
        "image_created=$(date -u +'%Y-%m-%dT%H:%M:%SZ')",
        "tags+=(\"${IMAGE}:latest\")",
        "tags+=(\"${IMAGE}:sha-${SHORT_SHA}\")",
        "\"${IMAGE}:${RELEASE_TAG}\"",
        "\"${IMAGE}:${RELEASE_VERSION}\"",
        "\"${IMAGE}:${MAJOR_MINOR}\"",
        "org.opencontainers.image.created=${image_created}",
        "org.opencontainers.image.description=${image_description}",
        "org.opencontainers.image.licenses=${image_licenses}",
        "org.opencontainers.image.source=https://github.com/${GITHUB_REPOSITORY}",
        "org.opencontainers.image.title=${image_title}",
        "org.opencontainers.image.revision=${SOURCE_REVISION}",
        "org.opencontainers.image.url=${image_url}",
        "org.opencontainers.image.version=${IMAGE_VERSION}",
        "for level in manifest index",
    ] {
        assert!(
            metadata_step.contains(required),
            "docker-publish.yml local metadata generation is missing `{required}`."
        );
    }
    assert!(
        metadata_step.contains("if: steps.existing.outputs.reuse != 'true'"),
        "docker-publish.yml must skip metadata generation when a verified release digest is reused."
    );
    for required in [
        "tags: ${{ steps.meta.outputs.tags }}",
        "labels: ${{ steps.meta.outputs.labels }}",
        "annotations: ${{ steps.meta.outputs.annotations }}",
    ] {
        assert!(
            build_step.contains(required),
            "docker-publish.yml build step must consume local metadata output `{required}`."
        );
    }

    for forbidden in ["curl ", "gh api", "api.github.com", "uses:"] {
        assert!(
            !metadata_step.contains(forbidden),
            "docker-publish.yml local metadata step must not perform network/API access through `{forbidden}`."
        );
    }
}

/// Map a container platform to the (TARGETARCH/variant `case` token, Rust target
/// triple) the `Dockerfile` arch map must handle for it. Panics for an unmapped
/// platform so that adding an entry to `REQUIRED_CONTAINER_PLATFORMS` forces a
/// matching Dockerfile arch-map expectation here (and a conscious test update).
fn container_platform_expectations(platform: &str) -> (&'static str, &'static str) {
    match platform {
        "linux/amd64" => ("amd64", "x86_64-unknown-linux-gnu"),
        "linux/arm64" => ("arm64", "aarch64-unknown-linux-gnu"),
        "linux/arm/v7" => ("v7", "armv7-unknown-linux-gnueabihf"),
        other => panic!(
            "REQUIRED_CONTAINER_PLATFORMS contains '{other}' but the test has no Dockerfile \
             arch-map expectation for it. Add its (TARGETARCH/variant case token, Rust triple) \
             to container_platform_expectations() AND the matching `case` arm to the Dockerfile."
        ),
    }
}

/// Locate the mapping for a `docker/build-push-action` step in a workflow and
/// return its `with:` block as raw text. Returns `None` if no such step exists.
///
/// We intentionally read the raw `with:` text rather than fully parsing the
/// YAML: the assertions below only need substring/token presence, and the raw
/// form keeps the failure messages pointing at literal workflow content the
/// maintainer can grep for.
fn build_push_action_with_block(workflow_content: &str) -> Option<String> {
    let lines: Vec<&str> = workflow_content.lines().collect();
    // Find the step that uses docker/build-push-action.
    let uses_idx = lines
        .iter()
        .position(|l| l.contains("uses:") && l.contains("docker/build-push-action"))?;

    // The `with:` block belongs to the same step. Walk forward to the `with:`
    // key, then collect the indented block beneath it.
    let with_idx = lines[uses_idx..]
        .iter()
        .position(|l| l.trim_start().starts_with("with:"))
        .map(|rel| uses_idx + rel)?;

    let with_indent = lines[with_idx].len() - lines[with_idx].trim_start().len();
    let mut block = String::new();
    for line in &lines[with_idx + 1..] {
        if line.trim().is_empty() {
            block.push('\n');
            continue;
        }
        let indent = line.len() - line.trim_start().len();
        if indent <= with_indent {
            break;
        }
        block.push_str(line);
        block.push('\n');
    }
    Some(block)
}

#[test]
fn test_required_container_platforms_cover_issue_122_arm64() {
    // Documents intent and guards the constant itself: the issue that motivated
    // multi-arch publishing was specifically a missing linux/arm64 manifest.
    assert!(
        REQUIRED_CONTAINER_PLATFORMS.contains(&"linux/amd64"),
        "linux/amd64 must remain a published platform (regression baseline)."
    );
    assert!(
        REQUIRED_CONTAINER_PLATFORMS.contains(&"linux/arm64"),
        "linux/arm64 must be a published platform (root cause of issue #122)."
    );
    // Pin the full set so the constant cannot silently SHRINK. Every other test
    // here loops over REQUIRED_CONTAINER_PLATFORMS, so a quiet deletion would
    // shrink coverage everywhere at once; force it to be a deliberate edit.
    assert_eq!(
        REQUIRED_CONTAINER_PLATFORMS,
        ["linux/amd64", "linux/arm64", "linux/arm/v7"],
        "REQUIRED_CONTAINER_PLATFORMS changed. If intentional, update this assertion together with \
         the docker-publish.yml `platforms:` list, the Dockerfile arch map, and \
         container_platform_expectations()."
    );
}

#[test]
fn test_docker_publish_builds_multi_arch_manifest() {
    // Regression guard for issue #122: the GHCR image must be a multi-arch
    // manifest list. A single-platform build-push-action (no `platforms:` key)
    // publishes only linux/amd64 and breaks every ARM64 consumer.
    let root = repo_root();
    let workflow_path = root.join(".github/workflows/docker-publish.yml");
    // Read the LIVE (comment-stripped) workflow so every presence check below —
    // the build-push-action step count, the `with:` block, `platforms:`, and the
    // buildx/qemu setup actions — is satisfied only by real config, never by a
    // commented-out line that still mentions the token.
    let content = read_live_file(&workflow_path);

    // The with-block helper assumes a single build-push-action step (and reads
    // the `with:` that follows it). Assert that assumption holds.
    let build_push_steps = content
        .lines()
        .filter(|l| l.contains("uses:") && l.contains("docker/build-push-action"))
        .count();
    assert_eq!(
        build_push_steps, 1,
        "docker-publish.yml must have exactly one docker/build-push-action step \
         (found {build_push_steps}); the multi-arch assertions below assume it."
    );

    let with_block = build_push_action_with_block(&content).unwrap_or_else(|| {
        panic!(
            "docker-publish.yml must invoke docker/build-push-action with a `with:` block.\n\
             Issue #122: without a multi-platform build the image is amd64-only."
        )
    });

    // Match a LIVE `platforms:` mapping line, not a commented-out one — a
    // `# platforms: ...` comment must NOT satisfy this (that would let the image
    // silently revert to amd64-only, exactly regression #122).
    let platforms_line = with_block
        .lines()
        .find(|l| l.trim_start().starts_with("platforms:"))
        .unwrap_or_else(|| {
            panic!(
                "docker-publish.yml's build-push-action step must set a live `platforms:` key to \
                 emit a multi-arch manifest. Without it the image is linux/amd64-only (issue \
                 #122).\nwith: block was:\n{with_block}"
            )
        });

    for platform in REQUIRED_CONTAINER_PLATFORMS {
        assert!(
            platforms_line.contains(platform),
            "docker-publish.yml `platforms:` must build container platform '{platform}'.\n\
             Add it to the `platforms:` list AND the Dockerfile cross-compile arch map. Keep \
             REQUIRED_CONTAINER_PLATFORMS in sync.\n`platforms:` line was:\n{platforms_line}"
        );
    }

    // setup-buildx-action is required for multi-platform output; setup-qemu is
    // required so the arm64/armv7 runtime stage (useradd/apt-get) can execute
    // under emulation (the Rust compile is cross-compiled, the runtime is not).
    assert!(
        content.contains("docker/setup-buildx-action"),
        "docker-publish.yml must set up docker/setup-buildx-action; multi-platform \
         manifests cannot be produced by the classic builder."
    );
    assert!(
        content.contains("docker/setup-qemu-action"),
        "docker-publish.yml must set up docker/setup-qemu-action so the non-native runtime \
         stages (useradd + apt-get for arm64/armv7) can run under emulation."
    );
}

#[test]
fn test_dockerfile_cross_compiles_for_target_platform() {
    // The chosen strategy is cross-compilation, not QEMU emulation: the builder
    // stage runs natively on the build platform and cross-compiles to the target
    // arch. This test guards the Dockerfile primitives that make that possible so
    // a future "simplification" cannot silently revert to an amd64-only build (or
    // to slow/flaky emulated compiles) while the workflow still requests arm64.
    let root = repo_root();
    // Live (comment-stripped) Dockerfile: the header comment block legitimately
    // mentions `$BUILDPLATFORM`, `TARGETARCH`, and `rustup target add` to explain
    // the strategy, so a raw `contains` would pass on prose alone even if the
    // real instructions were deleted. Assert against live config only.
    let dockerfile = read_live_file(&root.join("Dockerfile"));

    // The builder stage must pin itself to the native build platform so cross
    // compiles never execute target-arch binaries (which would require QEMU).
    // Anchor to the builder stage's own `FROM ... AS builder` line: a stray
    // `--platform=$BUILDPLATFORM` elsewhere (or only on chef/planner) must not
    // satisfy this — the stage that runs the expensive cross-compile is builder.
    assert!(
        dockerfile.lines().any(|line| {
            let trimmed = line.trim_start();
            trimmed.starts_with("FROM ")
                && (trimmed.contains("--platform=$BUILDPLATFORM")
                    || trimmed.contains("--platform=${BUILDPLATFORM}"))
                && trimmed.contains(" AS builder")
        }),
        "Dockerfile's builder stage must pin `FROM --platform=$BUILDPLATFORM ... AS builder` so \
         cross-compilation runs natively (no QEMU). Multi-arch is built by cross-compiling, not \
         emulating."
    );

    // The build must be parameterized by the target arch buildx injects.
    assert!(
        dockerfile.contains("TARGETARCH")
            || dockerfile.contains("TARGETPLATFORM")
            || dockerfile.contains("TARGETTRIPLE"),
        "Dockerfile must consume the buildx-provided target arch (TARGETARCH/TARGETPLATFORM) \
         to select the Rust cross-compilation target."
    );

    // A genuine cross-compile adds a Rust target and links with a cross linker.
    assert!(
        dockerfile.contains("rustup target add") || dockerfile.contains("--target"),
        "Dockerfile must add/select the Rust cross-compilation target triple \
         (`rustup target add` / `cargo build --target`)."
    );
}

#[test]
fn test_dockerfile_arch_map_covers_required_platforms() {
    // Issue #122 was an arm64 *build* gap, not just a missing manifest entry:
    // the workflow requesting a platform is useless if the Dockerfile's
    // cross-compile arch map cannot resolve it (it would hit the `*) Unsupported
    // TARGETARCH; exit 1` branch at build time). The doc comments on
    // REQUIRED_CONTAINER_PLATFORMS and in the Dockerfile both promise these stay
    // "in lockstep" — this test is what actually enforces it.
    let root = repo_root();
    let live = read_live_file(&root.join("Dockerfile"));

    for platform in REQUIRED_CONTAINER_PLATFORMS {
        let (arch_token, triple) = container_platform_expectations(platform);
        // Require the triple to be SELECTED by the matching `case` arm on one
        // line, e.g. `arm64) triple=aarch64-unknown-linux-gnu; ...`. A bare
        // file-wide `contains(arch_token)` would pass spuriously because the
        // token is a substring of triples/package names (`v7` ⊂ `armv7-...`,
        // `arm64` ⊂ `libc6-dev-arm64-cross`), so anchor to the case-arm line.
        let case_arm = format!("{arch_token})");
        let triple_assign = format!("triple={triple}");
        let has_case_arm = live
            .lines()
            .any(|l| l.contains(&case_arm) && l.contains(&triple_assign));
        assert!(
            has_case_arm,
            "Dockerfile arch map must have a `case` arm `{case_arm} ... {triple_assign}` that \
             cross-compiles '{platform}' to '{triple}'. Keep the arch map in lockstep with \
             REQUIRED_CONTAINER_PLATFORMS."
        );
    }
}

// ---------------------------------------------------------------------------
// Meta-tests: the comment-stripping mechanism the drift guards above rely on.
//
// Every guard in this file that asserts a config file still *contains* a
// required token reads the file via `read_live_file` (or strips an extracted
// block via `strip_comment_lines`) so a commented-out line cannot satisfy the
// assertion. These tests lock that mechanism in place: they prove the helper
// removes `#`/`//` comment lines, preserves live config (including inline
// trailing comments), and — crucially — that a guard built on the live view
// would FAIL when the real config line is merely commented out. If someone
// weakens `strip_comment_lines`/`read_live_file`, these go red first.
// ---------------------------------------------------------------------------

#[test]
fn test_strip_comment_lines_removes_full_line_hash_and_slash_comments() {
    let input = "\
# a leading hash comment
    # an indented hash comment
keep: real-yaml-value
// a leading slash comment
    // an indented slash comment
RUN cargo build  # inline trailing comment is preserved";

    let live = strip_comment_lines(input);

    // Full-line comment bodies are gone, in both `#` and `//` styles, indented
    // or not — so a token that survives only inside such a line is dropped.
    assert!(
        !live.contains("leading hash comment"),
        "strip_comment_lines must drop full-line `#` comments. live:\n{live}"
    );
    assert!(
        !live.contains("indented hash comment"),
        "strip_comment_lines must drop indented `#` comments. live:\n{live}"
    );
    assert!(
        !live.contains("leading slash comment"),
        "strip_comment_lines must drop full-line `//` comments (JSONC). live:\n{live}"
    );
    assert!(
        !live.contains("indented slash comment"),
        "strip_comment_lines must drop indented `//` comments. live:\n{live}"
    );

    // Live config lines survive untouched, and an inline trailing comment on a
    // real line is deliberately preserved (that line is live config; stripping
    // its tail could corrupt a token a guard looks for).
    assert!(
        live.contains("keep: real-yaml-value"),
        "strip_comment_lines must keep live config lines. live:\n{live}"
    );
    assert!(
        live.contains("RUN cargo build  # inline trailing comment is preserved"),
        "strip_comment_lines must preserve inline trailing comments on live lines. live:\n{live}"
    );
}

#[test]
fn test_read_live_file_is_strip_of_read_file() {
    // read_live_file is exactly strip_comment_lines ∘ read_file. Lock the
    // identity so the convenience reader can never drift from the primitive.
    let root = repo_root();
    let path = root.join("Dockerfile");
    assert_eq!(
        read_live_file(&path),
        strip_comment_lines(&read_file(&path)),
        "read_live_file must equal strip_comment_lines(read_file(..))."
    );
}

#[test]
fn test_drift_guards_reject_commented_out_config() {
    // RED/GREEN proof for the whole class: when a required config line is merely
    // commented out, the LIVE view a guard asserts against must NOT contain the
    // token (so the guard fails), even though the RAW file still does.

    // (1) A YAML setup-action commented out — the exact shape of regression the
    // `test_docker_publish_builds_multi_arch_manifest` buildx/qemu checks guard.
    let yaml_commented = "\
steps:
  - name: Set up Buildx
    # uses: docker/setup-qemu-action@v3   # temporarily disabled";
    assert!(
        yaml_commented.contains("docker/setup-qemu-action"),
        "sanity: the raw fixture still mentions the token in its comment"
    );
    assert!(
        !strip_comment_lines(yaml_commented).contains("docker/setup-qemu-action"),
        "a guard asserting the LIVE view must reject a commented-out setup-qemu-action line"
    );

    // (2) A Dockerfile builder-stage pin commented out — the regression shape
    // the `test_dockerfile_cross_compiles_for_target_platform` BUILDPLATFORM
    // check guards.
    let dockerfile_commented = "\
# FROM --platform=$BUILDPLATFORM chef AS builder
FROM chef AS builder";
    let live = strip_comment_lines(dockerfile_commented);
    let has_pinned_builder = live.lines().any(|line| {
        let trimmed = line.trim_start();
        trimmed.starts_with("FROM ")
            && trimmed.contains("--platform=$BUILDPLATFORM")
            && trimmed.contains(" AS builder")
    });
    assert!(
        !has_pinned_builder,
        "a guard anchoring to the live `FROM --platform=$BUILDPLATFORM ... AS builder` line must \
         reject a Dockerfile where that pin is only present in a comment. live:\n{live}"
    );

    // (3) A JSONC (devcontainer.json) feature commented out with `//`.
    let jsonc_commented = "\
{
  // \"ghcr.io/devcontainers/features/docker-outside-of-docker\": {}
}";
    assert!(
        !strip_comment_lines(jsonc_commented).contains("docker-outside-of-docker"),
        "a guard asserting the LIVE view must reject a `//`-commented JSONC feature line"
    );
}

#[test]
fn test_prepare_release_workflow_creates_a_ci_triggering_semver_release_pr() {
    let root = repo_root();
    let workflow = read_live_file(&root.join(".github/workflows/prepare-release.yml"));
    let permissions = extract_yaml_mapping_block(&workflow, "permissions", 0)
        .expect("prepare-release.yml must define workflow-level permissions");
    let prepare = extract_workflow_job_block(&workflow, "prepare")
        .expect("prepare-release.yml must define the prepare job");

    assert!(workflow.contains("name: Prepare Release"));
    assert!(workflow.contains("workflow_dispatch:"));
    for required in [
        "bump:",
        "type: choice",
        "- patch",
        "- minor",
        "- major",
        "dry_run:",
        "cancel-in-progress: false",
    ] {
        assert!(
            workflow.contains(required),
            "prepare-release.yml must contain `{required}` so a maintainer can choose a safe, \
             non-cancellable semantic-version preparation run."
        );
    }

    assert_eq!(permissions.trim(), "contents: read");
    for required in [
        "Require default branch dispatch",
        "actions/create-github-app-token@v3.2.0",
        "permission-contents: write",
        "permission-pull-requests: write",
        "ref: ${{ github.event.repository.default_branch }}",
        "Read Rust toolchain",
        "dtolnay/rust-toolchain@v1",
        "toolchain: ${{ steps.toolchain.outputs.channel }}",
        "bash scripts/prepare-release.sh --bump \"$BUMP\"",
        "git diff --check",
        "Validate prepared release state",
        "cargo test --locked --test release_prepare_tests --test workspace_lockfile_consistency",
        "bash scripts/list-release-lockfiles.sh",
        "release_files=(",
        "git add \"${release_files[@]}\"",
        "bash scripts/resolve-prepared-release.sh",
        "VERIFIED_BRANCH_SHA: ${{ steps.release.outputs.branch_sha }}",
        "if: ${{ always() && !inputs.dry_run }}",
        "bash scripts/ensure-release-pr.sh",
        "\"$body_file\" \"$expected_head_sha\"",
        "auth_header=$(printf 'x-access-token:%s' \"$GH_TOKEN\" | base64 | tr -d '\\n')",
        "push origin \"HEAD:refs/heads/${BRANCH}\"",
        "Release - Publish Crate",
        "actions/upload-artifact@v7.0.1",
    ] {
        assert!(
            prepare.contains(required),
            "prepare-release.yml prepare job must contain `{required}`.\nJob block:\n{prepare}"
        );
    }

    assert!(
        prepare.contains("GH_TOKEN: ${{ steps.app-token.outputs.token }}"),
        "The release PR must be created with the installation token so normal pull_request CI \
         runs; workflow-created PRs made with GITHUB_TOKEN do not trigger new workflows."
    );

    assert_eq!(
        prepare.matches("fuzz/Cargo.toml").count(),
        2,
        "The synchronized fuzz dependency manifest must appear once in the exact prepared-diff \
         allowlist and once in the staged release_files array.\nJob block:\n{prepare}"
    );

    let prepare_files_position = prepare
        .find("- name: Prepare release files")
        .expect("release files must be prepared");
    let diff_scope_position = prepare
        .find("- name: Validate prepared diff scope")
        .expect("prepared diff scope must be validated");
    let prepared_state_position = prepare
        .find("- name: Validate prepared release state")
        .expect("prepared release state must be tested");
    let prepared_state_command =
        "cargo test --locked --test release_prepare_tests --test workspace_lockfile_consistency";
    assert_eq!(
        prepare.matches(prepared_state_command).count(),
        1,
        "the prepared-state command must occur exactly once"
    );
    let prepared_state_command_position = prepare
        .find(prepared_state_command)
        .expect("prepared-state command must be present");
    let resolve_position = prepare
        .find("- name: Resolve prepared release identity")
        .expect("prepared release identity must be resolved");
    let push_position = prepare
        .find("- name: Push release branch and open pull request")
        .expect("release branch must be pushed");
    assert!(
        prepare_files_position < diff_scope_position
            && diff_scope_position < prepared_state_position
            && prepared_state_position < prepared_state_command_position
            && prepared_state_command_position < resolve_position
            && resolve_position < push_position,
        "release delivery must prepare files, validate their exact scope and state, resolve the \
         immutable identity, then push/open the PR, in that order.\nJob block:\n{prepare}"
    );

    let reuse_guard = prepare
        .find("if [ \"$BRANCH_EXISTS\" = \"true\" ]; then")
        .expect("release delivery must branch on verified remote branch existence");
    let absent_branch = reuse_guard
        + prepare[reuse_guard..]
            .find("\n          else\n")
            .expect("release delivery must have an absent-branch arm");
    let delivery_end = absent_branch
        + prepare[absent_branch..]
            .find("\n          fi\n")
            .expect("release delivery branch must terminate before PR verification");
    let verified_sha_positions: Vec<_> = prepare
        .match_indices("expected_head_sha=$VERIFIED_BRANCH_SHA")
        .map(|(position, _)| position)
        .collect();
    assert_eq!(
        verified_sha_positions.len(),
        1,
        "exact branch reuse must propagate the verified remote SHA exactly once.\nJob block:\n{prepare}"
    );
    assert!(
        verified_sha_positions[0] > reuse_guard && verified_sha_positions[0] < absent_branch,
        "the existing-branch arm must use VERIFIED_BRANCH_SHA before the absent-branch arm.\n\
         Job block:\n{prepare}"
    );
    for mutation in [
        "git checkout -b \"$BRANCH\"",
        "release_files=(",
        "git add \"${release_files[@]}\"",
        "git commit -m \"release: ${VERSION}\"",
        "push origin \"HEAD:refs/heads/${BRANCH}\"",
        "expected_head_sha=$(git rev-parse HEAD)",
    ] {
        let positions: Vec<_> = prepare
            .match_indices(mutation)
            .map(|(position, _)| position)
            .collect();
        assert_eq!(
            positions.len(),
            1,
            "release delivery must contain `{mutation}` exactly once.\nJob block:\n{prepare}"
        );
        let position = positions[0];
        assert!(
            position > absent_branch && position < delivery_end,
            "`{mutation}` must run only when the verified release branch is absent; an exact \
             existing branch must be reused without a redundant local commit.\nJob block:\n{prepare}"
        );
    }
    let ensure_positions: Vec<_> = prepare
        .match_indices("bash scripts/ensure-release-pr.sh")
        .map(|(position, _)| position)
        .collect();
    assert_eq!(
        ensure_positions.len(),
        1,
        "release delivery must verify its PR exactly once.\nJob block:\n{prepare}"
    );
    assert!(
        ensure_positions[0] > delivery_end,
        "PR verification must run after either branch-delivery arm.\nJob block:\n{prepare}"
    );

    assert!(
        prepare
            .contains("The workflow derives version \\`${VERSION}\\` from the reviewed Cargo.toml")
            && !prepare.contains("with \\`release_version=${VERSION}\\`"),
        "The generated release PR must direct maintainers to dispatch from the default branch \
         without retyping the reviewed version. Redundant release identity input caused the \
         failed 0.10.1 dispatch for the 0.4.1 release.\nJob block:\n{prepare}"
    );

    assert_eq!(
        prepare
            .matches(
                "git -c \"http.https://github.com/.extraheader=AUTHORIZATION: basic \
                 ${auth_header}\""
            )
            .count(),
        1,
        "The release-branch push must use the installation-token authorization header; the \
         tested release-state helper authenticates its remote probes separately."
    );

    let checkout = prepare
        .find("Checkout default branch")
        .expect("prepare job must check out the repository");
    let read_toolchain = prepare
        .find("Read Rust toolchain")
        .expect("prepare job must read the pinned Rust toolchain");
    let install_toolchain = prepare
        .find("Install Rust toolchain")
        .expect("prepare job must install the pinned Rust toolchain");
    let prepare_files = prepare
        .find("Prepare release files")
        .expect("prepare job must run the release transformer");
    assert!(
        checkout < read_toolchain
            && read_toolchain < install_toolchain
            && install_toolchain < prepare_files,
        "The pinned Rust toolchain must be installed after checkout and before release \
         preparation invokes Cargo."
    );

    let recovery = prepare
        .find("Create recovery patch")
        .expect("prepare job must capture recovery state");
    let push = prepare
        .find("Push release branch and open pull request")
        .expect("prepare job must deliver the release branch");
    let upload = prepare
        .find("Upload release preparation recovery patch")
        .expect("prepare job must upload recovery state after a failure");
    assert!(
        recovery < push && push < upload,
        "Recovery data must be captured before delivery can fail and uploaded only after that \
         failure."
    );
}

#[test]
fn test_release_dispatch_derives_identity_and_reuses_only_safe_tags() {
    let root = repo_root();
    let release = read_live_file(&root.join(".github/workflows/release.yml"));
    let on_block = extract_yaml_mapping_block(&release, "on", 0)
        .expect("release.yml must define workflow triggers");
    let resolve = extract_workflow_job_block(&release, "resolve-release")
        .expect("release.yml must define resolve-release");
    let resolver = read_live_file(&root.join("scripts/resolve-release-source.sh"));

    assert!(
        on_block.contains("workflow_dispatch:") && !on_block.contains("release_version:"),
        "Manual release publication must derive the reviewed Cargo.toml version instead of \
         asking an operator to retype it.\nTrigger block:\n{on_block}"
    );
    assert!(
        release.contains("group: release-publish")
            && !release.contains("github.event.inputs.release_version"),
        "All release attempts must share one non-cancelling publication lock and must not derive \
         concurrency identity from removed manual input."
    );

    for required in [
        "RELEASE_EVENT_NAME: ${{ github.event_name }}",
        "RELEASE_DEFAULT_BRANCH: ${{ github.event.repository.default_branch }}",
        "RELEASE_EVENT_REF: ${{ github.ref }}",
        "run: bash scripts/resolve-release-source.sh",
    ] {
        assert!(
            resolve.contains(required),
            "resolve-release must pass `{required}` to the tested release resolver.\n\
             Job block:\n{resolve}"
        );
    }

    for required in [
        "Release publication must be dispatched from ${DEFAULT_BRANCH}",
        "dispatch_revision=$(git rev-parse \"HEAD^{commit}\")",
        "version=$(read_cargo_version)",
        "tag=\"v${version}\"",
        "find_version_introduction \"$dispatch_revision\" \"$version\"",
        "git rev-parse --is-shallow-repository",
        "git rev-list --first-parent \"$dispatch_revision\" -- Cargo.toml",
        "multiple first-parent introduction commits",
        "git ls-remote --exit-code --tags origin \"refs/tags/${tag}\"",
        "Existing release tag ${candidate_tag} is lightweight",
        "source_revision=$(git rev-parse \"refs/tags/${tag}^{commit}\")",
        "git merge-base --is-ancestor \"$source_revision\" \"$dispatch_revision\"",
        "git merge-base --is-ancestor \"$source_revision\" \"origin/${DEFAULT_BRANCH}\"",
        "resolver_scratch=$(mktemp -d \"${scratch_base}/release-resolver.XXXXXX\")",
        "cp scripts/read-toml-string.sh \"${resolver_scratch}/read-toml-string.sh\"",
        "git checkout --detach \"$source_revision\"",
        "source Cargo.toml (${cargo_version}) disagree",
    ] {
        assert!(
            resolver.contains(required),
            "resolve-release must contain `{required}` so a manual retry can safely reuse an \
             immutable annotated release tag while rejecting unmerged or mismatched sources.\n\
             Resolver:\n{resolver}"
        );
    }
    assert!(
        !resolver.contains("source_revision=$dispatch_revision"),
        "An absent release tag must resolve the reviewed version-introduction commit, not a \
         later default-branch tip.\nResolver:\n{resolver}"
    );
}

#[test]
fn test_release_publication_keeps_probes_outside_the_checkout() {
    let root = repo_root();
    let release = read_live_file(&root.join(".github/workflows/release.yml"));
    let readiness = extract_workflow_job_block(&release, "publication-readiness")
        .expect("release.yml must define publication-readiness");
    let ensure_tag = extract_workflow_job_block(&release, "ensure-tag")
        .expect("release.yml must define ensure-tag");
    let publish =
        extract_workflow_job_block(&release, "publish").expect("release.yml must define publish");
    let probe = extract_named_workflow_step(&readiness, "Check for an idempotent crates.io retry")
        .expect("publication-readiness must define the crates.io retry probe");
    let clean = extract_named_workflow_step(&publish, "Verify clean checkout before publication")
        .expect("publish must define a clean-checkout publication gate");
    let crate_check = read_live_file(&root.join("scripts/check-crates-io-release.sh"));
    let clean_check = read_live_file(&root.join("scripts/check-clean-release-worktree.sh"));

    for required in [
        "needs: [resolve-release, preflight]",
        "crate_exists: ${{ steps.crate.outputs.exists }}",
        "Check for an idempotent crates.io retry",
        "Require crates.io token",
        "if: steps.crate.outputs.exists != 'true'",
        "CARGO_REGISTRY_TOKEN: ${{ secrets.CRATES_IO_TOKEN }}",
        "cargo publish --locked --all-features --dry-run --quiet",
        "Verify dry-run preserved a clean checkout",
    ] {
        assert!(
            readiness.contains(required),
            "publication-readiness must contain `{required}` before any irreversible release \
             mutation.\nJob block:\n{readiness}"
        );
    }
    assert!(
        ensure_tag.contains("needs: [resolve-release, publication-readiness]"),
        "ensure-tag must run only after credentials and the exact package pass readiness.\n\
         Job block:\n{ensure_tag}"
    );
    assert!(
        publish.contains("cargo publish --locked --all-features --quiet"),
        "crate publication must use the same all-feature, reviewed-diagnostic package policy"
    );

    for required in [
        "mktemp -d \"${RUNNER_TEMP}/crates-io-retry.XXXXXX\"",
        "trap cleanup EXIT",
        "response_file=\"${scratch_dir}/crate-version.json\"",
        "crate_file=\"${scratch_dir}/signal-fish-server-${VERSION}.crate\"",
        "--output \"$response_file\"",
    ] {
        assert!(
            crate_check.contains(required),
            "The crates.io retry probe must contain `{required}` so generated registry files \
             cannot dirty the package checkout.\nScript:\n{crate_check}"
        );
    }
    for forbidden in [
        "--output crate-version.json",
        "crate_file=\"signal-fish-server-${VERSION}.crate\"",
    ] {
        assert!(
            !crate_check.contains(forbidden),
            "The crates.io retry probe must not write checkout-relative scratch path \
             `{forbidden}`.\nScript:\n{crate_check}"
        );
    }
    assert!(
        probe.contains("run: bash publication-tools/scripts/check-crates-io-release.sh"),
        "Publication readiness must execute the tested crates.io probe helper.\nStep:\n{probe}"
    );

    for required in [
        "git status --porcelain=v1 --untracked-files=all",
        "Refusing to publish a dirty release checkout",
        "Release probes and generated files must use RUNNER_TEMP",
    ] {
        assert!(
            clean_check.contains(required),
            "The clean-checkout gate must contain `{required}` with actionable diagnostics.\n\
             Script:\n{clean_check}"
        );
    }
    assert!(
        clean.contains("run: bash ../publication-tools/scripts/check-clean-release-worktree.sh"),
        "The final clean gate must execute the tested helper.\nStep:\n{clean}"
    );
    let clean_position = publish
        .find("Verify clean checkout before publication")
        .expect("clean gate position");
    let publish_position = publish
        .find("Publish to crates.io")
        .expect("publish position");
    assert!(
        clean_position < publish_position,
        "The checkout must be verified immediately before Cargo \
         publication.\nJob block:\n{publish}"
    );
    let between = &publish[clean_position..publish_position];
    assert_eq!(
        between.matches("      - name:").count(),
        1,
        "No step may mutate the checkout between the clean gate and Cargo publication.\n\
         Intervening block:\n{between}"
    );
    assert!(
        !release.contains("--allow-dirty"),
        "Release automation must never bypass Cargo's dirty-checkout protection with \
         --allow-dirty."
    );
}

