#[test]
fn test_standalone_dependabot_jobs_reaching_root_inherit_all_root_holds() {
    let root = repo_root();
    let canonical_root = fs::canonicalize(&root).expect("repository root must resolve");
    let path_dependency =
        Regex::new(r#"path\s*=\s*"([^"]+)""#).expect("path-dependency regex must compile");
    let holds_by_directory = dependabot_cargo_holds_by_directory();
    let root_holds = holds_by_directory
        .get("/")
        .expect("Dependabot must define root Cargo holds");
    let mut root_path_jobs = BTreeSet::new();

    for (directory, holds) in &holds_by_directory {
        if directory == "/" {
            continue;
        }
        let manifest = root
            .join(directory.trim_start_matches('/'))
            .join("Cargo.toml");
        let manifest_content = read_live_file(&manifest);
        let manifest_directory = manifest
            .parent()
            .expect("standalone Cargo.toml must have a parent directory");
        let reaches_root = path_dependency
            .captures_iter(&manifest_content)
            .any(|capture| {
                fs::canonicalize(manifest_directory.join(&capture[1]))
                    .is_ok_and(|dependency_path| dependency_path == canonical_root)
            });
        if !reaches_root {
            continue;
        }

        root_path_jobs.insert(directory.as_str());
        let missing = root_holds.difference(holds).cloned().collect::<Vec<_>>();
        assert!(
            missing.is_empty(),
            "Dependabot Cargo job `{directory}` traverses a path dependency to the root crate, \
             so it can edit the root manifest and must inherit every root hold.\n\
             Missing holds: {missing:?}\nFile: {}",
            manifest.display()
        );
    }

    assert_eq!(
        root_path_jobs,
        BTreeSet::from(["/clients/native", "/fuzz"]),
        "The live Dependabot/path-dependency inventory changed. Every standalone Cargo job that \
         reaches the root crate must remain covered by the root-hold superset check."
    );
}

#[test]
fn test_dependabot_cargo_directories_cover_every_automated_package() {
    // These are exact-release interoperability fixtures, not independently
    // evolving products. Their dependency graphs move only when the pinned
    // released client/Godot fixture is deliberately advanced and its
    // interoperability cell is requalified.
    const EXCLUDED_FIXTURES: &[(&str, &str)] = &[
        (
            "clients/fortress/Cargo.toml",
            "native exact-release Fortress interoperability fixture",
        ),
        (
            "clients/fortress-wasm/Cargo.toml",
            "Godot/WASM exact-release Fortress interoperability fixture",
        ),
    ];

    let root = repo_root();
    let path = root.join(".github/dependabot.yml");
    let content = read_live_file(&path);
    let documents = Yaml::load_from_str(&content).expect("dependabot.yml must parse as YAML");
    let updates = documents
        .first()
        .and_then(|document| document.as_mapping_get("updates"))
        .unwrap_or_else(|| panic!("dependabot.yml must define an updates sequence"));
    let Yaml::Sequence(updates) = updates else {
        panic!("dependabot.yml updates must be a sequence");
    };

    let configured: Vec<String> = updates
        .iter()
        .filter(|entry| {
            entry
                .as_mapping_get("package-ecosystem")
                .and_then(Yaml::as_str)
                == Some("cargo")
        })
        .map(|entry| {
            let directory = entry
                .as_mapping_get("directory")
                .and_then(Yaml::as_str)
                .unwrap_or_else(|| panic!("every Dependabot Cargo entry must define `directory`"));
            assert!(
                directory == "/"
                    || (directory.starts_with('/')
                        && !directory.ends_with('/')
                        && !directory.contains("//")),
                "Dependabot Cargo directory `{directory}` must be a canonical absolute \
                 repository path (exactly `/` or `/path` with no trailing slash)"
            );
            directory.to_string()
        })
        .collect();
    let configured_set: BTreeSet<String> = configured.iter().cloned().collect();
    assert_eq!(
        configured.len(),
        configured_set.len(),
        "Dependabot Cargo directories must be unique; configured {configured:?}"
    );

    let manifests: BTreeSet<String> = tracked_package_manifests(&root)
        .into_iter()
        .filter(|manifest| {
            read_file(&root.join(manifest))
                .lines()
                .any(|line| line.trim() == "[package]")
        })
        .collect();
    let excluded: BTreeSet<&str> = EXCLUDED_FIXTURES
        .iter()
        .map(|(manifest, reason)| {
            assert!(
                !reason.trim().is_empty(),
                "Dependabot exclusion `{manifest}` must have a documented rationale"
            );
            assert!(
                manifests.contains(*manifest),
                "Dependabot exclusion `{manifest}` does not name a tracked Cargo package"
            );
            *manifest
        })
        .collect();
    assert_eq!(
        excluded.len(),
        EXCLUDED_FIXTURES.len(),
        "Dependabot package exclusions must be unique"
    );
    let expected: BTreeSet<String> = manifests
        .iter()
        .filter(|manifest| !excluded.contains(manifest.as_str()))
        .map(|manifest| match manifest.rsplit_once('/') {
            Some((directory, "Cargo.toml")) => format!("/{directory}"),
            None if manifest == "Cargo.toml" => "/".to_string(),
            _ => panic!("tracked package manifest has an unexpected path: {manifest}"),
        })
        .collect();

    assert_eq!(
        configured_set, expected,
        "Dependabot Cargo coverage must equal the tracked package inventory minus the explicit \
         exact-release fixture exclusions.\n\
         Expected directories: {expected:?}\n\
         Configured directories: {configured_set:?}\n\
         Fix: remove stale entries and add one Cargo update entry for every newly evolving \
         standalone package in .github/dependabot.yml."
    );
}

#[test]
fn test_dependabot_npm_directories_cover_every_locked_package() {
    let root = repo_root();
    let output = Command::new("git")
        .arg("-C")
        .arg(&root)
        .args([
            "ls-files",
            "-z",
            "--",
            "package-lock.json",
            "*/package-lock.json",
        ])
        .output()
        .expect("`git ls-files` must be available to inventory npm lockfiles");
    assert!(
        output.status.success(),
        "`git ls-files` must succeed to inventory npm lockfiles"
    );
    let expected = String::from_utf8_lossy(&output.stdout)
        .split('\0')
        .filter(|path| !path.is_empty())
        .map(|lockfile| match lockfile.rsplit_once('/') {
            Some((directory, "package-lock.json")) => format!("/{directory}"),
            None if lockfile == "package-lock.json" => "/".to_owned(),
            _ => panic!("tracked npm lockfile has an unexpected path: {lockfile}"),
        })
        .collect::<BTreeSet<_>>();
    let configured = dependabot_npm_directories();

    assert_eq!(
        configured, expected,
        "Dependabot npm coverage must equal the tracked package-lock.json inventory.\n\
         Expected directories: {expected:?}\n\
         Configured directories: {configured:?}\n\
         Fix: add one canonical npm update entry per locked package to \
         .github/dependabot.yml and remove stale entries."
    );
}

#[test]
fn test_workflow_consumed_configuration_paths_trigger_validation() {
    let root = repo_root();
    let cases = [
        (
            ".github/workflows/actionlint.yml",
            vec![".github/actionlint.yaml"],
        ),
        (
            ".github/workflows/llm-file-sizes.yml",
            vec![".github/workflows/llm-file-sizes.yml"],
        ),
    ];

    for (workflow_path, required_paths) in cases {
        let workflow = read_file(&root.join(workflow_path));
        for event in ["push", "pull_request"] {
            let paths = extract_workflow_event_paths(&workflow, event)
                .into_iter()
                .collect::<BTreeSet<_>>();
            for required_path in &required_paths {
                assert!(
                    paths.contains(*required_path),
                    "{workflow_path} {event}.paths must include {required_path} because the workflow consumes it"
                );
            }
        }
    }
}

#[test]
fn test_fuzz_dependency_resolution_is_locked_in_ci() {
    let root = repo_root();
    let tracked = Command::new("git")
        .arg("-C")
        .arg(&root)
        .args(["ls-files", "--error-unmatch", "fuzz/Cargo.lock"])
        .output()
        .expect("`git ls-files` must be available to verify fuzz/Cargo.lock");
    assert!(
        tracked.status.success(),
        "fuzz/Cargo.lock must be committed so the standalone fuzz graph is reproducible.\n\
         Fix: remove Cargo.lock from fuzz/.gitignore, generate the lockfile with the pinned \
         toolchain, and add it to version control."
    );

    let ci_path = root.join(".github/workflows/ci.yml");
    let ci = read_live_file(&ci_path);
    let ci_commands: Vec<String> = workflow_run_command_lines(&ci)
        .into_iter()
        .map(|(_, command)| command)
        .collect();
    assert!(
        ci_commands
            .iter()
            .any(|command| command == "cargo check --manifest-path fuzz/Cargo.toml --bins --locked"),
        "ci.yml must type-check every fuzz target with `--locked` so manifest drift fails \
         instead of silently rewriting fuzz/Cargo.lock."
    );

    let fuzz_path = root.join(".github/workflows/fuzz.yml");
    let fuzz = read_live_file(&fuzz_path);
    let pull_request_paths: BTreeSet<String> = extract_workflow_event_paths(&fuzz, "pull_request")
        .into_iter()
        .collect();
    for required_path in [
        "Cargo.toml",
        "build.rs",
        "src/**",
        ".llm/code-samples/protocol/**",
        ".github/scripts/run-fuzz-targets.sh",
    ] {
        assert!(
            pull_request_paths.contains(required_path),
            "fuzz.yml pull_request paths must include {required_path} because the declared \
             state-machine targets compile and exercise the root package. Narrow filters \
             silently skip behavioral fuzz coverage when production surfaces change."
        );
    }
    let fuzz_documents =
        Yaml::load_from_str(&fuzz).expect("fuzz.yml live configuration must parse as YAML");
    let fuzz_job = fuzz_documents
        .first()
        .and_then(|document| document.as_mapping_get("jobs"))
        .and_then(|jobs| jobs.as_mapping_get("fuzz"))
        .unwrap_or_else(|| panic!("fuzz.yml must define jobs.fuzz"));
    assert!(
        fuzz_job.as_mapping_get("strategy").is_none(),
        "fuzz.yml must keep all fuzz targets in one hosted job so they share one build"
    );
    let configured_target_list: Vec<String> = fuzz_job
        .as_mapping_get("env")
        .and_then(|env| env.as_mapping_get("FUZZ_TARGETS"))
        .and_then(Yaml::as_str)
        .unwrap_or_else(|| panic!("fuzz.yml jobs.fuzz.env.FUZZ_TARGETS must be a string"))
        .split_whitespace()
        .map(str::to_string)
        .collect();
    let configured_targets: BTreeSet<String> = configured_target_list.iter().cloned().collect();
    assert_eq!(
        configured_target_list.len(),
        configured_targets.len(),
        "fuzz.yml must list every fuzz target exactly once"
    );
    let fuzz_manifest = read_file(&root.join("fuzz/Cargo.toml"));
    let mut in_bin = false;
    let mut current_bin_has_name = false;
    let mut manifest_bin_count = 0usize;
    let mut manifest_targets = BTreeSet::new();
    for raw_line in fuzz_manifest.lines() {
        let line = raw_line.split('#').next().unwrap_or_default().trim();
        if line == "[[bin]]" {
            assert!(
                !in_bin || current_bin_has_name,
                "every fuzz [[bin]] block must declare exactly one non-empty name"
            );
            in_bin = true;
            current_bin_has_name = false;
            manifest_bin_count += 1;
            continue;
        }
        if line.starts_with('[') {
            assert!(
                !in_bin || current_bin_has_name,
                "every fuzz [[bin]] block must declare exactly one non-empty name"
            );
            in_bin = false;
            continue;
        }
        if !in_bin {
            continue;
        }
        let Some((key, value)) = line.split_once('=') else {
            continue;
        };
        if key.trim() == "name" {
            assert!(
                !current_bin_has_name,
                "every fuzz [[bin]] block must declare exactly one name"
            );
            let name = value.trim().trim_matches(['"', '\'']);
            assert!(!name.is_empty(), "every fuzz [[bin]] must declare a name");
            assert!(
                manifest_targets.insert(name.to_string()),
                "fuzz/Cargo.toml must not declare duplicate [[bin]] name '{name}'"
            );
            current_bin_has_name = true;
        }
    }
    assert!(
        !in_bin || current_bin_has_name,
        "every fuzz [[bin]] block must declare exactly one non-empty name"
    );
    assert!(
        !manifest_targets.is_empty(),
        "fuzz/Cargo.toml must declare [[bin]] fuzz targets"
    );
    assert_eq!(
        manifest_bin_count,
        manifest_targets.len(),
        "every fuzz [[bin]] block must contribute one unique target"
    );
    assert_eq!(
        configured_targets, manifest_targets,
        "fuzz.yml must smoke-run every fuzz/Cargo.toml [[bin]] target. A compile-only stable \
         check cannot replace nightly libFuzzer execution."
    );
    let fuzz_steps = fuzz_job
        .as_mapping_get("steps")
        .and_then(Yaml::as_sequence)
        .unwrap_or_else(|| panic!("fuzz.yml jobs.fuzz must define a steps sequence"));
    let locked_preflight_index = fuzz_steps
        .iter()
        .position(|step| {
            step.as_mapping_get("name").and_then(Yaml::as_str)
                == Some("Verify locked fuzz dependency graph")
        })
        .unwrap_or_else(|| panic!("fuzz.yml must define a live locked dependency preflight"));
    let locked_preflight = fuzz_steps
        .get(locked_preflight_index)
        .and_then(|step| step.as_mapping_get("run"))
        .and_then(Yaml::as_str)
        .unwrap_or_else(|| panic!("the locked fuzz dependency preflight must define `run`"));
    assert!(
        locked_preflight
            == "cargo +nightly-2026-08-01 metadata --manifest-path fuzz/Cargo.toml --locked \
                --format-version 1 >/dev/null",
        "fuzz.yml must run a locked metadata preflight before cargo-fuzz. cargo-fuzz itself \
         does not accept `--locked`, so the preflight is the reproducibility gate."
    );

    let shared_build_index = fuzz_steps
        .iter()
        .position(|step| {
            step.as_mapping_get("name").and_then(Yaml::as_str)
                == Some("Build all fuzz targets once")
        })
        .unwrap_or_else(|| panic!("fuzz.yml must define one live all-target cargo-fuzz build"));
    let shared_build = fuzz_steps
        .get(shared_build_index)
        .and_then(|step| step.as_mapping_get("run"))
        .and_then(Yaml::as_str)
        .unwrap_or_else(|| panic!("the shared fuzz build step must define `run`"));
    assert_eq!(
        shared_build,
        "timeout --signal=TERM --kill-after=10s 600s cargo +nightly-2026-08-01 fuzz build --target x86_64-unknown-linux-gnu",
        "fuzz.yml must build every declared bin together so Cargo shares the production-crate \
         and libFuzzer compile prefix, while bounding a stuck best-effort prewarm below the job \
         timeout so authoritative target runs still execute"
    );
    let fuzz_run_index = fuzz_steps
        .iter()
        .position(|step| {
            step.as_mapping_get("name").and_then(Yaml::as_str)
                == Some("Fuzz all targets concurrently")
        })
        .unwrap_or_else(|| panic!("fuzz.yml must define the concurrent cargo-fuzz command"));
    let fuzz_run = fuzz_steps
        .get(fuzz_run_index)
        .and_then(|step| step.as_mapping_get("run"))
        .and_then(Yaml::as_str)
        .unwrap_or_else(|| panic!("the live all-target cargo-fuzz step must define `run`"));
    assert!(
        locked_preflight_index < shared_build_index && shared_build_index < fuzz_run_index,
        "fuzz.yml must verify the committed dependency graph before cargo-fuzz can resolve or \
         build it, then finish the shared build before launching targets \
         (preflight {locked_preflight_index}, build {shared_build_index}, fuzz {fuzz_run_index})."
    );
    assert_eq!(
        fuzz_run, "bash .github/scripts/run-fuzz-targets.sh",
        "the fuzz workflow must delegate supervision to its regression-tested helper"
    );
    let fuzz_supervisor = read_live_file(&root.join(".github/scripts/run-fuzz-targets.sh"));
    for required_fragment in [
        "10#$MAX_TOTAL_TIME > 300",
        "watchdog_seconds=$((10#$MAX_TOTAL_TIME + 10#$watchdog_grace_seconds))",
        "read -r -a targets <<< \"$FUZZ_TARGETS\"",
        "if ((${#targets[@]} == 0))",
        "for target in \"${targets[@]}\"",
        "timeout --signal=TERM --kill-after=10s",
        "fuzz run \"$target\"",
        ">\"$logs_dir/$target.log\" 2>&1 &",
        "pids+=(\"$!\")",
        "trap cleanup_children EXIT",
        "trap 'exit 130' INT TERM",
        "for index in \"${!targets[@]}\"",
        "if wait \"${pids[$index]}\"",
        "pids[index]=\"\"",
        "cat \"$logs_dir/$target.log\"",
        "failures+=(\"$target:$status\")",
        "if ((${#failures[@]} != 0))",
        "exit 1",
    ] {
        assert!(
            fuzz_supervisor.contains(required_fragment),
            "the concurrent fuzz supervisor must contain `{required_fragment}` so every \
             target starts independently, reaches a terminal result, retains diagnostics, and \
             contributes to the final failure status.\nSupervisor:\n{fuzz_supervisor}"
        );
    }
    assert!(
        !fuzz_supervisor.contains("--locked"),
        "cargo-fuzz 0.13 rejects `--locked`; fuzz.yml must enforce the committed graph with \
         the native Cargo metadata preflight and leave the cargo-fuzz invocation unflagged.\n\
         Supervisor:\n{fuzz_supervisor}"
    );

    let cache_index = fuzz_steps
        .iter()
        .position(|step| {
            step.as_mapping_get("name").and_then(Yaml::as_str) == Some("Cache cargo build")
        })
        .unwrap_or_else(|| panic!("fuzz.yml must define the Rust build cache step"));
    let cache_step = fuzz_steps
        .get(cache_index)
        .unwrap_or_else(|| panic!("the fuzz cache step index must remain valid"));
    let shared_build_step = fuzz_steps
        .get(shared_build_index)
        .unwrap_or_else(|| panic!("the shared fuzz build step index must remain valid"));
    assert!(
        cache_index < shared_build_index
            && cache_step.as_mapping_get("continue-on-error").is_none()
            && shared_build_step.as_mapping_get("if").is_none()
            && shared_build_step
                .as_mapping_get("continue-on-error")
                .and_then(Yaml::as_bool)
                == Some(true)
            && fuzz_steps
                .get(fuzz_run_index)
                .is_some_and(|step| step.as_mapping_get("if").is_none()),
        "the Rust cache and shared prebuild may accelerate the fuzz job but must never substitute \
         for the unconditional, gating per-target runs. A cache miss or restore warning must fall \
         back to live compilation; a target-specific prebuild failure must still let every target \
         report independently."
    );

    let upload_steps: BTreeSet<(String, String)> = fuzz_steps
        .iter()
        .filter_map(|step| {
            let uses = step.as_mapping_get("uses").and_then(Yaml::as_str)?;
            if !uses.starts_with("actions/upload-artifact@") {
                return None;
            }
            let with = step.as_mapping_get("with")?;
            let name = with.as_mapping_get("name").and_then(Yaml::as_str)?;
            let path = with.as_mapping_get("path").and_then(Yaml::as_str)?;
            assert_eq!(
                step.as_mapping_get("if").and_then(Yaml::as_str),
                Some("failure()"),
                "fuzz failure artifacts must upload after any target failure"
            );
            assert_eq!(
                with.as_mapping_get("if-no-files-found").and_then(Yaml::as_str),
                Some("ignore"),
                "a target that failed before writing an artifact must not hide the original failure"
            );
            Some((name.to_string(), path.to_string()))
        })
        .collect();
    let expected_upload_steps: BTreeSet<(String, String)> = configured_targets
        .iter()
        .map(|target| {
            (
                format!("fuzz-artifacts-{target}"),
                format!(
                    "fuzz/artifacts/{target}/\n${{{{ runner.temp }}}}/fuzz-logs/{target}.log\n"
                ),
            )
        })
        .collect();
    assert_eq!(
        upload_steps, expected_upload_steps,
        "fuzz.yml must retain one independently named artifact bundle and log per fuzz target"
    );
    assert_eq!(
        fuzz_steps
            .iter()
            .skip(fuzz_run_index + 1)
            .filter(|step| {
                step.as_mapping_get("uses")
                    .and_then(Yaml::as_str)
                    .is_some_and(|uses| uses.starts_with("actions/upload-artifact@"))
            })
            .count(),
        configured_targets.len(),
        "every per-target artifact upload must run after the authoritative fuzz supervisor"
    );

    let ci_documents =
        Yaml::load_from_str(&ci).expect("ci.yml live configuration must parse as YAML");
    let deny_steps = ci_documents
        .first()
        .and_then(|document| document.as_mapping_get("jobs"))
        .and_then(|jobs| jobs.as_mapping_get("deny"))
        .and_then(|job| job.as_mapping_get("steps"))
        .and_then(Yaml::as_sequence)
        .unwrap_or_else(|| panic!("ci.yml must define jobs.deny.steps"));
    let fuzz_deny = deny_steps
        .iter()
        .find(|step| {
            step.as_mapping_get("name").and_then(Yaml::as_str)
                == Some("Run cargo-deny (fuzz package)")
        })
        .unwrap_or_else(|| panic!("ci.yml must define the live fuzz cargo-deny step"));
    let fuzz_deny_action = fuzz_deny
        .as_mapping_get("uses")
        .and_then(Yaml::as_str)
        .and_then(parse_remote_action_reference);
    assert!(
        fuzz_deny_action.is_some_and(|(action, reference)| {
            action == "EmbarkStudios/cargo-deny-action" && is_action_version_ref(reference)
        }) && fuzz_deny
            .as_mapping_get("with")
            .and_then(|with| with.as_mapping_get("manifest-path"))
            .and_then(Yaml::as_str)
            == Some("fuzz/Cargo.toml")
            && ci_commands
                .iter()
                .any(|command| command == "cargo audit --file fuzz/Cargo.lock"),
        "ci.yml must apply both cargo-deny policy and the cargo-audit second opinion to the \
         committed standalone fuzz graph."
    );
}

#[test]
#[cfg(target_os = "linux")]
fn test_fuzz_supervisor_waits_logs_times_out_and_aggregates_all_targets() {
    use std::os::unix::fs::PermissionsExt;
    use std::time::{Duration, Instant};

    let root = repo_root();
    let supervisor = root.join(".github/scripts/run-fuzz-targets.sh");
    let fixture = unique_temp_dir("fuzz-supervisor");
    let fake_bin = fixture.path().join("bin");
    let fake_cargo = fake_bin.join("cargo");
    let trace = fixture.path().join("trace.txt");
    let hung_pid = fixture.path().join("hung.pid");
    write_file(
        &fake_cargo,
        r#"#!/usr/bin/env bash
set -euo pipefail
target=$4
printf 'started:%s\n' "$target" >> "$TRACE_FILE"
case "$target" in
  succeeds)
    echo "succeeds-complete"
    ;;
  fails_seven)
    echo "fails-seven-diagnostic"
    exit 7
    ;;
  fails_nine)
    echo "fails-nine-diagnostic"
    exit 9
    ;;
  hangs)
    echo "hang-diagnostic"
    printf '%s\n' "$$" > "$HUNG_PID_FILE"
    exec sleep 10
    ;;
  *)
    exit 99
    ;;
esac
"#,
    );
    let mut permissions = fs::metadata(&fake_cargo)
        .expect("fake cargo metadata")
        .permissions();
    permissions.set_mode(0o755);
    fs::set_permissions(&fake_cargo, permissions).expect("make fake cargo executable");

    let existing_path = std::env::var_os("PATH").unwrap_or_default();
    let mut paths = vec![fake_bin];
    paths.extend(std::env::split_paths(&existing_path));
    let path = std::env::join_paths(paths).expect("join fake cargo PATH");
    let started = Instant::now();
    let output = bash_command()
        .arg(&supervisor)
        .current_dir(fixture.path())
        .env("PATH", &path)
        .env("FUZZ_TARGETS", "succeeds fails_seven fails_nine hangs")
        .env("MAX_TOTAL_TIME", "1")
        .env("FUZZ_WATCHDOG_GRACE_SECONDS", "0")
        .env("RUNNER_TEMP", fixture.path())
        .env("TRACE_FILE", &trace)
        .env("HUNG_PID_FILE", &hung_pid)
        .output()
        .expect("execute fuzz supervisor with fake cargo");
    let elapsed = started.elapsed();
    let mut combined = String::from_utf8_lossy(&output.stdout).into_owned();
    combined.push_str(&String::from_utf8_lossy(&output.stderr));

    assert!(
        !output.status.success(),
        "multiple target failures and a timeout must fail the aggregate supervisor\n{combined}"
    );
    assert!(
        elapsed < Duration::from_secs(5),
        "the external watchdog must bound a stuck fuzz iteration; elapsed {elapsed:?}"
    );
    let started_targets: BTreeSet<String> = read_file(&trace).lines().map(str::to_string).collect();
    let expected_starts: BTreeSet<String> = [
        "started:succeeds",
        "started:fails_seven",
        "started:fails_nine",
        "started:hangs",
    ]
    .into_iter()
    .map(str::to_string)
    .collect();
    assert_eq!(
        started_targets, expected_starts,
        "all targets must launch before the supervisor aggregates results"
    );
    for diagnostic in [
        "succeeds-complete",
        "fails-seven-diagnostic",
        "fails-nine-diagnostic",
        "hang-diagnostic",
        "fails_seven:7",
        "fails_nine:9",
        "hangs:124",
    ] {
        assert!(
            combined.contains(diagnostic),
            "the aggregate output must retain `{diagnostic}` from every terminal result\n{combined}"
        );
    }
    for target in ["succeeds", "fails_seven", "fails_nine", "hangs"] {
        assert!(
            fixture
                .path()
                .join(format!("fuzz-logs/{target}.log"))
                .is_file(),
            "the supervisor must retain a log for {target}"
        );
    }
    let timed_out_pid = read_file(&hung_pid).trim().to_string();
    let lingering = Command::new("kill")
        .args(["-0", &timed_out_pid])
        .output()
        .expect("probe timed-out fake cargo PID");
    assert!(
        !lingering.status.success(),
        "the watchdog must reap the timed-out fuzz process {timed_out_pid}"
    );

    let success_temp = fixture.path().join("success-temp");
    fs::create_dir_all(&success_temp).expect("create successful supervisor temp directory");
    let success = bash_command()
        .arg(&supervisor)
        .current_dir(fixture.path())
        .env("PATH", &path)
        .env("FUZZ_TARGETS", "succeeds")
        .env("MAX_TOTAL_TIME", "1")
        .env("FUZZ_WATCHDOG_GRACE_SECONDS", "0")
        .env("RUNNER_TEMP", &success_temp)
        .env("TRACE_FILE", &trace)
        .env("HUNG_PID_FILE", &hung_pid)
        .output()
        .expect("execute successful fuzz supervisor case");
    assert!(
        success.status.success(),
        "an all-success target inventory must exit zero\nstdout:\n{}\nstderr:\n{}",
        String::from_utf8_lossy(&success.stdout),
        String::from_utf8_lossy(&success.stderr)
    );
    assert!(
        read_file(&success_temp.join("fuzz-logs/succeeds.log")).contains("succeeds-complete"),
        "the all-success case must retain the target's complete log"
    );

    let invalid = bash_command()
        .arg(&supervisor)
        .current_dir(fixture.path())
        .env("FUZZ_TARGETS", "succeeds")
        .env("MAX_TOTAL_TIME", "301")
        .env("RUNNER_TEMP", fixture.path())
        .output()
        .expect("execute fuzz supervisor with an excessive budget");
    assert_eq!(
        invalid.status.code(),
        Some(64),
        "dispatch budgets above the hosted-job-safe cap must fail before launching cargo"
    );
    let empty = bash_command()
        .arg(&supervisor)
        .current_dir(fixture.path())
        .env("FUZZ_TARGETS", "   ")
        .env("MAX_TOTAL_TIME", "1")
        .env("RUNNER_TEMP", fixture.path())
        .output()
        .expect("execute fuzz supervisor with an empty target inventory");
    assert_eq!(
        empty.status.code(),
        Some(64),
        "a whitespace-only target inventory must fail before claiming success"
    );
}

#[test]
fn test_dependabot_auto_merge_workflow_hardening() {
    let root = repo_root();
    let workflow_path = root.join(".github/workflows/dependabot-auto-merge.yml");
    let content = read_file(&workflow_path);
    let normalized_content = content.replace("\r\n", "\n");
    let on_block = extract_yaml_mapping_block(&normalized_content, "on", 0).unwrap_or_else(|| {
        panic!(
            "dependabot-auto-merge.yml must define top-level `on` trigger configuration as a block mapping.\n\
             File: {}",
            workflow_path.display()
        )
    });
    let on_child_indent = yaml_first_child_indent(&on_block).unwrap_or_else(|| {
        panic!(
            "dependabot-auto-merge.yml `on` block must contain at least one event trigger.\n\
             File: {}",
            workflow_path.display()
        )
    });
    let pull_request_block = extract_yaml_mapping_block(&on_block, "pull_request", on_child_indent)
        .unwrap_or_else(|| {
            panic!(
                "dependabot-auto-merge.yml must define `on.pull_request` as a block mapping for hardening checks.\n\
                 File: {}",
                workflow_path.display()
            )
        });

    assert!(
        extract_yaml_field_values(&pull_request_block, "branches")
            .iter()
            .any(|branch| branch == "main"),
        "dependabot-auto-merge.yml must scope pull_request trigger branches to main.\n\
         File: {}\n\
         Fix:\n\
           on:\n\
             pull_request:\n\
               branches: [main]",
        workflow_path.display()
    );
    let pull_request_types = extract_yaml_field_values(&pull_request_block, "types");
    assert!(
        ["opened", "synchronize", "reopened", "ready_for_review"]
            .iter()
            .all(|event| pull_request_types.iter().any(|actual| actual == event)),
        "dependabot-auto-merge.yml must scope pull_request trigger types to opened/synchronize/reopened/ready_for_review.\n\
         File: {}\n\
         Fix:\n\
           on:\n\
             pull_request:\n\
               types: [opened, synchronize, reopened, ready_for_review]",
        workflow_path.display()
    );

    let permissions_block = extract_yaml_mapping_block(&normalized_content, "permissions", 0)
        .unwrap_or_else(|| {
            panic!(
                "dependabot-auto-merge.yml must define top-level `permissions` as a block mapping.\n\
                 File: {}",
                workflow_path.display()
            )
        });
    assert!(
        permissions_block
            .lines()
            .any(|line| line.trim_start() == "contents: read"),
        "dependabot-auto-merge.yml must declare a minimal top-level workflow permissions baseline.\n\
         Keep elevated write permissions scoped only to the dependabot job.\n\
         File: {}\n\
         Fix:\n\
           permissions:\n\
             contents: read",
        workflow_path.display()
    );
    assert!(
        workflow_concurrency_settings(&normalized_content)
            == Some((Some(CANCELLABLE_CONCURRENCY_GROUP.to_string()), Some(true))),
        "dependabot-auto-merge.yml must declare workflow-level concurrency with cancellation.\n\
         File: {}\n\
         Fix:\n\
           concurrency:\n\
             group: {CANCELLABLE_CONCURRENCY_GROUP}\n\
             cancel-in-progress: true",
        workflow_path.display()
    );

    let jobs_content = extract_yaml_mapping_block(&normalized_content, "jobs", 0)
        .unwrap_or_else(|| {
            panic!(
                "dependabot-auto-merge.yml must contain top-level `jobs` as a block mapping for hardening checks.\n\
                 File: {}",
                workflow_path.display()
            )
        });
    let jobs_child_indent = yaml_first_child_indent(&jobs_content).unwrap_or_else(|| {
        panic!(
            "dependabot-auto-merge.yml `jobs` block must contain at least one job definition.\n\
             File: {}",
            workflow_path.display()
        )
    });
    let dependabot_job =
        extract_yaml_mapping_block(&jobs_content, "dependabot", jobs_child_indent).unwrap_or_else(
            || {
                panic!(
                    "dependabot-auto-merge.yml must define `jobs.dependabot` as a block mapping for hardening checks.\n\
                     File: {}",
                    workflow_path.display()
                )
            },
        );
    assert!(
        dependabot_job.contains("timeout-minutes: 60"),
        "dependabot-auto-merge.yml must define a timeout that gives CI time to finish before auto-merge is enabled.\n\
         File: {}\n\
         Fix: add 'timeout-minutes: 60' under jobs.dependabot.",
        workflow_path.display()
    );
    assert!(
        dependabot_job.contains("permissions:")
            && dependabot_job.contains("contents: write")
            && dependabot_job.contains("pull-requests: write")
            && dependabot_job.contains("actions: read"),
        "dependabot-auto-merge.yml dependabot job must explicitly scope write permissions.\n\
         File: {}\n\
         Fix:\n\
            jobs:\n\
              dependabot:\n\
                permissions:\n\
                  contents: write\n\
                  pull-requests: write\n\
                  actions: read",
        workflow_path.display()
    );
    assert!(
        dependabot_job.contains("github.event.pull_request.user.login == 'dependabot[bot]'")
            && dependabot_job.contains("github.event.sender.login == 'dependabot[bot]'"),
        "dependabot-auto-merge.yml must gate on both PR author and event sender as dependabot[bot].\n\
         File: {}\n\
         Fix: include both checks in jobs.dependabot.if.",
        workflow_path.display()
    );
    assert!(
        dependabot_job.contains("event=pull_request")
            && dependabot_job.contains("if [[ \"$state\" == \"failed\" ]]")
            && dependabot_job.contains("if [[ \"$state\" == \"ready\" ]]")
            && dependabot_job.contains("PR_HEAD_SHA: ${{ github.event.pull_request.head.sha }}")
            && dependabot_job.contains("gh pr merge --auto --squash --match-head-commit \"$PR_HEAD_SHA\" \"$PR_URL\"")
            && dependabot_job.contains("set +e")
            && dependabot_job.contains("merge_status=$?")
            && dependabot_job.contains("if (( merge_status == 0 ))")
            && dependabot_job.contains("is_retryable_merge_error()")
            && dependabot_job.contains("unstable status")
            && dependabot_job.contains("something went wrong while executing your query")
            && dependabot_job.contains("temporary failure")
            && dependabot_job.contains("service unavailable")
            && dependabot_job.contains("retryable_merge_error_count")
            && dependabot_job.contains("max_retryable_merge_errors=5")
            && dependabot_job.contains("if is_retryable_merge_error \"$merge_output\"; then")
            && dependabot_job.contains("Retryable GitHub merge API error detected")
            && dependabot_job.contains("Exceeded retryable GitHub merge API error limit")
            && dependabot_job.contains("is_automerge_unsupported_error()")
            && dependabot_job.contains("required protected branch rules")
            && dependabot_job.contains("enablepullrequestautomerge")
            && dependabot_job.contains("pull request auto merge is not allowed")
            && dependabot_job.contains("auto-merge is not enabled")
            && dependabot_job.contains("elif is_automerge_unsupported_error \"$merge_output\"; then")
            && dependabot_job
                .contains("Auto-merge unsupported by repo/branch policy; attempting immediate squash merge.")
            && dependabot_job.contains("gh pr merge --squash --match-head-commit \"$PR_HEAD_SHA\" \"$PR_URL\"")
            && dependabot_job.contains("fallback_status=$?")
            && dependabot_job.contains("if (( fallback_status == 0 ))")
            && dependabot_job.contains("echo \"$merge_output\" >&2")
            && dependabot_job.contains("echo \"$fallback_output\" >&2")
            && dependabot_job.contains("exit \"$fallback_status\"")
            && dependabot_job.contains("ready_streak=0")
            && dependabot_job.contains("exit \"$merge_status\"")
            && !dependabot_job.contains("gh pr merge --auto --merge \"$PR_URL\"")
            && !dependabot_job.contains("gh pr merge --auto --rebase \"$PR_URL\""),
        "dependabot-auto-merge.yml must wait for pull_request CI workflows to be complete/successful, retry transient GitHub merge API failures with a cap, and remain compatible with repositories that do not require protected-branch checks for auto-merge.\n\
         Repositories that allow only squash merges fail if --merge/--rebase is forced.\n\
         File: {}\n\
         Fix: poll pull_request workflow-run status, block on failed/pending checks, then run\n\
              `gh pr merge --auto --squash --match-head-commit \"$PR_HEAD_SHA\" \"$PR_URL\"`.\n\
              Retry transient `in unstable status` and `Something went wrong while executing your query`\n\
              GraphQL responses with a capped retry counter, and when GitHub returns\n\
              branch/repository policy rejections (for example\n\
              `Branch does not have required protected branch rules (enablePullRequestAutoMerge)`),\n\
              fallback to immediate `gh pr merge --squash --match-head-commit \"$PR_HEAD_SHA\" \"$PR_URL\"`.",
        workflow_path.display()
    );
}

#[test]
fn test_dependabot_auto_merge_retryable_merge_error_patterns_cover_observed_failures() {
    let root = repo_root();
    let workflow_path = root.join(".github/workflows/dependabot-auto-merge.yml");
    let content = read_file(&workflow_path);
    let retryable_function = content
        .split("is_retryable_merge_error() {")
        .nth(1)
        .and_then(|tail| tail.split("\n          }").next())
        .unwrap_or_else(|| {
            panic!(
                "dependabot-auto-merge.yml must define is_retryable_merge_error().\n\
                 File: {}",
                workflow_path.display()
            )
        });
    let retryable_pattern = retryable_function
        .lines()
        .map(str::trim)
        .find(|line| line.contains("something went wrong while executing your query"))
        .map(|line| line.trim_end_matches(" \\").trim_matches('\''))
        .unwrap_or_else(|| {
            panic!(
                "is_retryable_merge_error() must include the observed GitHub GraphQL transient failure.\n\
                 File: {}",
                workflow_path.display()
            )
        });

    let retryable_regex = Regex::new(retryable_pattern).unwrap_or_else(|e| {
        panic!(
            "Retryable merge error pattern must be valid regex: {e}\nPattern: {retryable_pattern}"
        )
    });
    let workflow_display = workflow_path.display();

    for sample in [
        "GraphQL: Pull request is in unstable status",
        "GraphQL: Something went wrong while executing your query on 2026-05-27T12:14:34Z.",
        "Error: service unavailable",
        "Error: gateway timeout",
    ] {
        let lowered_sample = sample.to_lowercase();

        assert!(
            retryable_regex.is_match(&lowered_sample),
            "Retryable merge error pattern should match sample `{sample}`.\n\
             Pattern: {retryable_pattern}\n\
             File: {workflow_display}",
        );
    }

    for sample in [
        "Branch does not have required protected branch rules (enablePullRequestAutoMerge)",
        "Pull request auto merge is not allowed",
        "Authentication failed",
    ] {
        let lowered_sample = sample.to_lowercase();

        assert!(
            !retryable_regex.is_match(&lowered_sample),
            "Retryable merge error pattern must not hide permanent merge errors by matching sample `{sample}`.\n\
             Pattern: {retryable_pattern}\n\
             File: {workflow_display}",
        );
    }
}

#[test]
fn test_release_workflow_handles_path_filtered_workflows() {
    // This test validates that the release workflow's preflight job handles
    // path-filtered workflows (like Documentation Validation) that may be
    // legitimately skipped when the commit does not touch relevant paths.
    //
    // Without this handling, releases would be blocked whenever the release
    // commit did not touch documentation paths, because the preflight job
    // would find no completed run for "Documentation Validation" and treat
    // that as an error.
    //
    // Checks:
    //   1. The release.yml contains a PATH_FILTERED_WORKFLOWS declaration
    //   2. The path-filtered workflow list references each workflow that has
    //      path filters in REQUIRED_WORKFLOW_NAMES
    //   3. The preflight logic checks changed files when no run is found

    let root = repo_root();
    let release_yml = root.join(".github/workflows/release.yml");

    if !release_yml.exists() {
        // Release workflow is optional
        return;
    }

    let content = read_live_file(&release_yml);

    // Must declare the PATH_FILTERED_WORKFLOWS associative array
    assert!(
        content.contains("PATH_FILTERED_WORKFLOWS"),
        "release.yml preflight job must declare PATH_FILTERED_WORKFLOWS to handle \
         workflows that use path filters and may be legitimately skipped.\n\
         File: {}",
        release_yml.display()
    );

    // The PATH_FILTERED_WORKFLOWS map must reference "Documentation Validation"
    // since doc-validation.yml uses path filters.
    assert!(
        content.contains("PATH_FILTERED_WORKFLOWS[\"Documentation Validation\"]"),
        "release.yml PATH_FILTERED_WORKFLOWS must include 'Documentation Validation' \
         because doc-validation.yml uses path filters.\n\
         File: {}",
        release_yml.display()
    );

    let release_line = content
        .lines()
        .find(|line| line.contains("PATH_FILTERED_WORKFLOWS[\"Documentation Validation\"]"))
        .unwrap_or_else(|| {
            panic!(
                "release.yml must define PATH_FILTERED_WORKFLOWS[\"Documentation Validation\"].\n\
                 File: {}",
                release_yml.display()
            )
        });
    let (_assignment, release_patterns_value) = release_line
        .split_once('=')
        .unwrap_or_else(|| panic!("release preflight path map assignment must contain '='"));
    let release_patterns: BTreeSet<String> = release_patterns_value
        .trim()
        .trim_matches('"')
        .split_whitespace()
        .map(ToString::to_string)
        .collect();

    let doc_validation_yml = root.join(".github/workflows/doc-validation.yml");
    let doc_validation_content = read_file(&doc_validation_yml);
    let push_paths: BTreeSet<String> =
        extract_workflow_event_paths(&doc_validation_content, "push")
            .into_iter()
            .collect();
    let pull_request_paths: BTreeSet<String> =
        extract_workflow_event_paths(&doc_validation_content, "pull_request")
            .into_iter()
            .collect();

    assert_eq!(
        push_paths,
        pull_request_paths,
        "doc-validation.yml push.paths and pull_request.paths must stay identical so release \
         preflight can use one Documentation Validation path map.\n\
         File: {}",
        doc_validation_yml.display()
    );

    let expected_release_patterns: BTreeSet<String> = push_paths
        .iter()
        .map(|path| release_preflight_pattern_for_doc_path(path))
        .collect();

    let missing_doc_preflight_patterns: Vec<String> = expected_release_patterns
        .difference(&release_patterns)
        .map(|pattern| format!("  - {pattern}"))
        .collect();
    let unexpected_doc_preflight_patterns: Vec<String> = release_patterns
        .difference(&expected_release_patterns)
        .map(|pattern| format!("  - {pattern}"))
        .collect();

    assert!(
        missing_doc_preflight_patterns.is_empty() && unexpected_doc_preflight_patterns.is_empty(),
        "release.yml Documentation Validation preflight path map drifted from doc-validation.yml.\n\n\
         Missing patterns:\n{}\n\nUnexpected patterns:\n{}\n\n\
         Keep PATH_FILTERED_WORKFLOWS[\"Documentation Validation\"] in sync with the \
         path filters in doc-validation.yml so release preflight fails closed when a \
         release commit touches files that should have triggered Documentation Validation.\n\
         File: {}",
        missing_doc_preflight_patterns.join("\n"),
        unexpected_doc_preflight_patterns.join("\n"),
        release_yml.display()
    );

    // Verify the preflight logic checks changed files for path-filtered workflows
    assert!(
        content.contains("commit did not touch relevant paths"),
        "release.yml preflight job must check whether the commit touched relevant \
         paths before treating a missing workflow run as an error.\n\
         File: {}",
        release_yml.display()
    );

    // Verify that path-filtered workflows with matching paths still error
    assert!(
        content.contains("should have triggered this workflow"),
        "release.yml preflight job must still error when a path-filtered workflow \
         has no run but the commit DID touch relevant paths.\n\
         File: {}",
        release_yml.display()
    );

    // Verify fail-closed behavior when CHANGED_FILES cannot be retrieved.
    // If the GitHub API fails to return changed files, the preflight must
    // fail (FAILED=1) rather than warn, to prevent releasing without CI
    // verification.
    assert!(
        content.contains("Failing closed"),
        "release.yml preflight job must fail closed when CHANGED_FILES is empty.\n\
         If the GitHub API fails to return changed files for the commit, the \
         preflight must set FAILED=1 rather than warning, to prevent releasing \
         without CI verification.\n\
         File: {}",
        release_yml.display()
    );

    // Cross-check: every workflow in REQUIRED_WORKFLOW_NAMES that has path
    // filters in its workflow file should appear in PATH_FILTERED_WORKFLOWS.
    for (workflow_file, workflow_name) in REQUIRED_WORKFLOW_NAMES {
        let workflow_path = root.join(".github/workflows").join(workflow_file);
        if !workflow_path.exists() {
            continue;
        }
        let workflow_content = read_file(&workflow_path);

        // Check if this workflow uses path filters (has a `paths:` key)
        let has_path_filters = workflow_content.lines().any(|line| {
            let trimmed = line.trim();
            trimmed == "paths:" || trimmed.starts_with("paths:")
        });

        if has_path_filters {
            let expected = format!("PATH_FILTERED_WORKFLOWS[\"{workflow_name}\"]");
            assert!(
                content.contains(&expected),
                "Workflow '{workflow_name}' ({workflow_file}) uses path filters but is not \
                 listed in PATH_FILTERED_WORKFLOWS in release.yml.\n\
                 Add: {expected}=\"<path patterns>\"\n\
                 File: {}",
                release_yml.display()
            );
        }
    }
}

#[test]
fn test_workflow_files_use_two_space_indentation() {
    // Validates that all workflow YAML files use 2-space indentation as required
    // by .yamllint.yml (indentation.spaces: 2). This catches files accidentally
    // written with 4-space indentation (common when copying from other projects
    // or when editors default to 4 spaces).
    //
    // Two checks are performed:
    //   1. Odd indentation: lines with an odd number of leading spaces (never valid
    //      in 2-space YAML)
    //   2. Minimum indent heuristic: if the smallest non-zero indent across all
    //      YAML-level lines in a file is 4+ spaces, the file is likely using 4-space
    //      (or larger) indentation throughout
    //
    // Only checks YAML structural lines — content inside multiline scalar blocks
    // (run: |, args: >-, etc.) is excluded because those are embedded scripts
    // with their own indentation rules.

    let root = repo_root();
    let workflows_dir = root.join(".github/workflows");

    let workflow_files = collect_workflow_files(&workflows_dir);

    assert!(
        !workflow_files.is_empty(),
        "No workflow files found in .github/workflows/"
    );

    let mut errors = Vec::new();

    for entry in &workflow_files {
        let path = entry.path();
        let content = read_file(&path);
        let filename = path.file_name().unwrap().to_string_lossy();

        let mut in_multiline_block = false;
        let mut block_indent = 0;
        let mut odd_indent_lines = Vec::new();
        let mut min_yaml_indent = usize::MAX;

        for (line_idx, line) in content.lines().enumerate() {
            let stripped = line.trim();
            let indent = line.len() - line.trim_start().len();

            // Skip empty lines and lines with no indentation
            if stripped.is_empty() || indent == 0 {
                // A non-empty line at indent 0 exits any multiline block
                if !stripped.is_empty() {
                    in_multiline_block = false;
                }
                continue;
            }

            // Detect start of YAML multiline scalar block
            if !in_multiline_block && (stripped.contains(": |") || stripped.contains(": >")) {
                let after_colon = stripped
                    .split_once(": ")
                    .map(|(_, rest)| rest.trim())
                    .unwrap_or("");
                if after_colon == "|"
                    || after_colon == "|-"
                    || after_colon == "|+"
                    || after_colon == ">"
                    || after_colon == ">-"
                    || after_colon == ">+"
                {
                    in_multiline_block = true;
                    block_indent = indent;
                    // Still check this line's own indentation (it's a YAML key)
                    if !indent.is_multiple_of(2) {
                        odd_indent_lines.push((line_idx + 1, indent, line.to_string()));
                    }
                    continue;
                }
            }

            // Detect end of multiline block
            if in_multiline_block && indent <= block_indent {
                in_multiline_block = false;
            }

            // Skip lines inside multiline scalar blocks
            if in_multiline_block {
                continue;
            }

            // Check YAML-level lines for 2-space indentation (even number of spaces)
            if !indent.is_multiple_of(2) {
                odd_indent_lines.push((line_idx + 1, indent, line.to_string()));
            }

            // Track minimum indentation for the 4-space heuristic
            if indent > 0 && indent < min_yaml_indent {
                min_yaml_indent = indent;
            }
        }

        if !odd_indent_lines.is_empty() {
            let examples: Vec<String> = odd_indent_lines
                .iter()
                .take(5)
                .map(|(line_num, spaces, content)| {
                    format!("  line {line_num}: {spaces} spaces: {content}")
                })
                .collect();
            let remaining = if odd_indent_lines.len() > 5 {
                format!("  ... and {} more lines", odd_indent_lines.len() - 5)
            } else {
                String::new()
            };
            errors.push(format!(
                "{filename}: {count} line(s) with odd indentation (not a multiple of 2 spaces):\n\
                 {examples}{remaining}",
                count = odd_indent_lines.len(),
                examples = examples.join("\n"),
            ));
        }

        // Heuristic: if the minimum YAML-level indent is 4+, the file likely
        // uses 4-space (or larger) indentation instead of 2-space.
        if min_yaml_indent != usize::MAX && min_yaml_indent >= 4 {
            errors.push(format!(
                "{filename}: minimum YAML indentation is {min_yaml_indent} spaces \
                 (expected 2).\n  \
                 This file likely uses {min_yaml_indent}-space indentation instead of 2-space.\n  \
                 Re-indent the entire file to use 2-space increments."
            ));
        }
    }

    if !errors.is_empty() {
        panic!(
            "Workflow files have indentation errors:\n\n{}\n\n\
             The project uses 2-space YAML indentation (.yamllint.yml: indentation.spaces: 2).\n\
             To fix:\n\
             1. Re-indent the file using 2-space increments\n\
             2. Run: yamllint -c .yamllint.yml .github/workflows/\n\
             3. Many editors can convert indentation: search for \"convert indentation to spaces\"\n\n\
             Common cause: copying workflow templates from projects that use 4-space indentation.",
            errors.join("\n\n")
        );
    }
}

// ============================================================================
// Advanced Safety Workflow (ci-safety.yml) Tests
// ============================================================================

/// Required jobs in ci-safety.yml: (job_key, display_name, description)
///
/// These jobs are not branch-protection required checks. Their workflow-level
/// failure policy is pinned separately below.
const SAFETY_JOBS: &[(&str, &str, &str)] = &[
    (
        "miri",
        "Miri",
        "Undefined behavior detection via Miri interpreter",
    ),
    (
        "asan",
        "AddressSanitizer",
        "Memory error detection via AddressSanitizer",
    ),
];

const SAFETY_JOB_CONTINUE_ON_ERROR: &[(&str, bool)] = &[("miri", false), ("asan", false)];

#[test]
fn test_ci_safety_workflow_has_required_jobs() {
    // Validates that the advanced safety workflow has all safety jobs
    // with correct job keys AND display names. Uses the shared helper
    // `validate_workflow_has_required_jobs` for consistency with ci.yml and
    // doc-validation.yml validation tests.

    let root = repo_root();
    let workflow_path = root.join(".github/workflows/ci-safety.yml");

    assert!(
        workflow_path.exists(),
        "ci-safety.yml must exist.\n\
         This workflow provides advanced safety analysis (Miri, AddressSanitizer).\n\
         See docs/ci-cd-testing.md#advanced-safety-workflow for details."
    );

    validate_workflow_has_required_jobs(&workflow_path, SAFETY_JOBS, "Advanced Safety");
}

#[test]
fn test_ci_safety_workflow_failure_policy_is_explicit() {
    // Both safety analyzers must propagate failures to the workflow.

    let root = repo_root();
    let workflow_path = root.join(".github/workflows/ci-safety.yml");
    let content = read_file(&workflow_path);
    let documents = Yaml::load_from_str(&content).expect("ci-safety.yml must parse as YAML");
    let jobs = documents
        .first()
        .and_then(|document| document.as_mapping_get("jobs"))
        .expect("ci-safety.yml must define a jobs mapping");

    for (job_key, expected_continue_on_error) in SAFETY_JOB_CONTINUE_ON_ERROR {
        let job = jobs
            .as_mapping_get(job_key)
            .unwrap_or_else(|| panic!("Job '{job_key}' not found in ci-safety.yml"));
        assert!(
            matches!(job, Yaml::Mapping(_)),
            "Job '{job_key}' must be a YAML mapping"
        );
        let configured = match job.as_mapping_get("continue-on-error") {
            Some(value) => value.as_bool().unwrap_or_else(|| {
                panic!("Job '{job_key}' continue-on-error must be a YAML boolean")
            }),
            None => false,
        };
        assert_eq!(
            configured, *expected_continue_on_error,
            "Job '{job_key}' continue-on-error policy drifted: expected \
             continue-on-error={expected_continue_on_error}"
        );
    }
}

#[test]
fn test_ci_safety_workflow_uses_pinned_nightly() {
    // Validates that ci-safety.yml uses a pinned nightly toolchain, not
    // rolling "nightly". Pinned nightlies ensure reproducible CI results.

    let root = repo_root();
    let workflow_path = root.join(".github/workflows/ci-safety.yml");
    // Live view: the header comment documents the nightly version too, so assert
    // the pin is on a real toolchain line, not merely named in a comment.
    let content = read_live_file(&workflow_path);

    // Must contain a pinned nightly version (e.g., "nightly-2026-01-15")
    let has_pinned_nightly = content.contains("nightly-20");
    assert!(
        has_pinned_nightly,
        "ci-safety.yml must use a pinned nightly toolchain (e.g., nightly-2026-01-15).\n\
         Rolling 'nightly' causes unpredictable CI breakage.\n\
         See the Nightly Toolchain Strategy section in the workflow header."
    );

    // Must NOT contain bare "toolchain: nightly" (without date pin)
    let has_bare_nightly = content.lines().any(|line| {
        let trimmed = line.trim();
        trimmed == "toolchain: nightly" || trimmed == "toolchain: \"nightly\""
    });
    assert!(
        !has_bare_nightly,
        "ci-safety.yml must NOT use bare 'toolchain: nightly'.\n\
         Use a date-pinned nightly instead (e.g., nightly-2026-01-15)."
    );
}

#[test]
fn test_ci_safety_workflow_has_required_triggers() {
    // Validates that ci-safety.yml has all required triggers:
    // push to main, pull_request to main, schedule, and workflow_dispatch.

    let root = repo_root();
    let workflow_path = root.join(".github/workflows/ci-safety.yml");
    let content = read_live_file(&workflow_path);

    let required_triggers = [
        ("push:", "push to main"),
        ("pull_request:", "pull requests to main"),
        ("schedule:", "weekly scheduled runs"),
        ("workflow_dispatch:", "manual trigger for diagnostics"),
    ];

    let mut missing = Vec::new();
    for (trigger, description) in &required_triggers {
        if !content.contains(trigger) {
            missing.push(format!("  - {trigger} ({description})"));
        }
    }

    if !missing.is_empty() {
        panic!(
            "ci-safety.yml is missing required triggers:\n\n{}\n\n\
             Advanced safety workflows need all four triggers:\n\
             - push/pull_request: run on code changes\n\
             - schedule: weekly heavy analysis\n\
             - workflow_dispatch: manual diagnostics",
            missing.join("\n")
        );
    }
}

