#[test]
fn test_analysis_nightly_version_consistency() {
    // The analysis workflows and devcontainer intentionally share one pin.
    // Inspect every live occurrence so a partially updated workflow cannot
    // pass merely because its first date still matches the baseline.

    let root = repo_root();
    let nightly_files = [
        ".github/workflows/ci-safety.yml",
        ".github/workflows/fuzz.yml",
        ".github/workflows/unused-deps.yml",
        ".devcontainer/Dockerfile",
    ];
    let nightly_pattern =
        Regex::new(r"nightly-[0-9]{4}-[0-9]{2}-[0-9]{2}").expect("valid nightly regex");

    let mut nightly_versions: Vec<(String, String)> = Vec::new();
    for relative_path in nightly_files {
        let path = root.join(relative_path);
        let content = strip_comment_lines(&read_file(&path));
        let versions: BTreeSet<String> = nightly_pattern
            .find_iter(&content)
            .map(|found| found.as_str().to_string())
            .collect();
        assert_eq!(
            versions.len(),
            1,
            "{relative_path} must contain exactly one operational date-pinned nightly, \
             repeated consistently at every install/command site.\nObserved: {versions:?}"
        );
        let version = versions
            .into_iter()
            .next()
            .expect("one pinned nightly was asserted");
        for operational_line in content.lines().filter(|line| {
            line.contains("toolchain: nightly")
                || line.contains("cargo +nightly")
                || line.contains("ARG RUST_NIGHTLY=")
                || line.contains("rustup toolchain install")
        }) {
            if relative_path == ".devcontainer/Dockerfile"
                && operational_line.contains("rustup toolchain install")
            {
                assert!(
                    operational_line.contains("\"$RUST_NIGHTLY\""),
                    "{relative_path} must install the date-pinned $RUST_NIGHTLY argument, not a \
                     rolling or duplicated literal: {operational_line}"
                );
            } else {
                assert!(
                    operational_line.contains(&version),
                    "{relative_path} has an unpinned or partially updated nightly operation: \
                     {operational_line}\nExpected pin: {version}"
                );
            }
        }
        if relative_path == ".devcontainer/Dockerfile" {
            assert!(
                content.lines().any(|line| {
                    line.contains("rustup toolchain install") && line.contains("\"$RUST_NIGHTLY\"")
                }),
                ".devcontainer/Dockerfile must install its date-pinned RUST_NIGHTLY argument"
            );
        }
        nightly_versions.push((relative_path.to_string(), version));
    }

    // All extracted versions should be the same
    if nightly_versions.len() > 1 {
        let first_version = &nightly_versions[0].1;
        let mut mismatches = Vec::new();

        for (file, version) in &nightly_versions[1..] {
            if version != first_version {
                mismatches.push(format!("  - {file}: {version} (expected {first_version})"));
            }
        }

        if !mismatches.is_empty() {
            panic!(
                "Nightly toolchain versions are inconsistent across workflows:\n\n\
                 Baseline: {} uses {first_version}\n{}\n\n\
                 All analysis workflows and the devcontainer must use the same version.\n\
                 To fix: update every operational pin together.\n\
                 The separate Fortress WASM toolchain is compatibility-pinned and excluded.",
                nightly_versions[0].0,
                mismatches.join("\n")
            );
        }
    }

    let unused_deps = read_live_file(&root.join(".github/workflows/unused-deps.yml"));
    for required in [
        "uses: taiki-e/install-action@v2.85.10",
        "tool: cargo-machete@0.7.0,cargo-udeps@0.1.61",
        "fallback: none",
        "cargo machete --version | grep -Fxq '0.7.0'",
        "cargo +nightly-2026-08-01 udeps --version | grep -Fxq 'cargo-udeps 0.1.61'",
        "cargo +nightly-2026-08-01 udeps --locked --all-targets --all-features",
    ] {
        assert!(
            unused_deps.contains(required),
            "unused-deps.yml must install exact checksum-verified analyzer binaries and \
             verify them with the analysis nightly; \
             missing '{required}'"
        );
    }
    assert!(
        !unused_deps.contains("cargo install cargo-machete")
            && !unused_deps.contains("install cargo-udeps")
            && !unused_deps.contains("Cache cargo-machete binary")
            && !unused_deps.contains("Cache cargo-udeps binary"),
        "unused-deps.yml must not rebuild or separately cache analyzers that have verified release binaries"
    );
}

#[test]
fn test_unused_deps_workflow_uses_one_shared_analyzer_job() {
    let root = repo_root();
    let workflow = read_live_file(&root.join(".github/workflows/unused-deps.yml"));
    let documents = Yaml::load_from_str(&workflow).expect("unused-deps workflow must parse");
    let document = documents.first().expect("unused-deps workflow document");
    let jobs = document
        .as_mapping_get("jobs")
        .expect("unused-deps workflow jobs");
    assert_eq!(
        jobs.as_mapping().map(|mapping| mapping.len()),
        Some(1),
        "unused-deps.yml must use one hosted job; adding a status-only compatibility job wastes a runner allocation"
    );
    assert!(
        jobs.as_mapping_get("unused-features-status").is_none(),
        "the audited, non-required Check Unused Features compatibility status must not return"
    );
    let analyzer = jobs
        .as_mapping_get("unused-deps")
        .expect("consolidated analyzer job");
    let analyzer_steps = analyzer
        .as_mapping_get("steps")
        .and_then(Yaml::as_sequence)
        .expect("consolidated analyzer steps");

    for (needle, expected) in [
        ("uses: actions/checkout@", 1),
        ("uses: dtolnay/rust-toolchain@", 1),
        ("uses: Swatinem/rust-cache@", 1),
        ("run: cargo machete", 1),
        (
            "run: cargo +nightly-2026-08-01 udeps --locked --all-targets --all-features",
            1,
        ),
    ] {
        assert_eq!(
            workflow.matches(needle).count(),
            expected,
            "unused-deps.yml must contain exactly {expected} occurrence(s) of {needle:?} so both \
             analyzers share one checkout/toolchain/cache setup"
        );
    }

    assert_eq!(
        analyzer.as_mapping_get("name").and_then(Yaml::as_str),
        Some("Check Unused Dependencies")
    );
    assert_eq!(
        analyzer
            .as_mapping_get("timeout-minutes")
            .and_then(Yaml::as_integer),
        Some(30),
        "the sequential analyzer job needs explicit cold-cache headroom"
    );

    let step_named = |name: &str| {
        analyzer_steps
            .iter()
            .find(|step| step.as_mapping_get("name").and_then(Yaml::as_str) == Some(name))
            .unwrap_or_else(|| panic!("missing analyzer step {name:?}"))
    };
    let machete_position = analyzer_steps
        .iter()
        .position(|step| {
            step.as_mapping_get("name").and_then(Yaml::as_str)
                == Some("Check for unused dependencies")
        })
        .expect("cargo-machete step");
    assert_ne!(
        step_named("Check for unused dependencies")
            .as_mapping_get("continue-on-error")
            .and_then(Yaml::as_bool),
        Some(true),
        "cargo-machete must remain the gating analyzer"
    );
    let udeps = step_named("Check for unused dependencies (udeps)");
    let udeps_position = analyzer_steps
        .iter()
        .position(|candidate| std::ptr::eq(candidate, udeps))
        .expect("cargo-udeps step position");
    assert!(
        udeps_position > machete_position,
        "cargo-udeps must follow cargo-machete"
    );
    assert_eq!(
        udeps.as_mapping_get("if").and_then(Yaml::as_str),
        Some("${{ !cancelled() }}"),
        "cargo-udeps must still run after a cargo-machete failure while respecting cancellation"
    );
    assert_eq!(
        step_named("Check for unused dependencies (udeps)")
            .as_mapping_get("continue-on-error")
            .and_then(Yaml::as_bool),
        Some(true),
        "cargo-udeps remains informational because it can report false positives"
    );
}

