#[test]
fn test_powershell_native_process_helpers_are_shared_and_deadlock_safe() {
    let root = repo_root();
    let helper_path = root.join("scripts/hooks/native-process.ps1");
    let helper = read_live_file(&helper_path);
    let invoke_native_re = Regex::new(r"(?m)^function Invoke-Native\s*\{").unwrap();

    assert!(
        invoke_native_re.find_iter(&helper).count() == 1
            && helper.contains("function Invoke-NativeWithInput")
            && helper.contains("function Invoke-NativeBytesWithInput")
            && helper.contains("function Invoke-Git"),
        "scripts/hooks/native-process.ps1 must be the single shared native process helper."
    );
    assert!(
        helper.contains("ReadToEndAsync()") && helper.contains("CopyToAsync($stdoutStream)"),
        "PowerShell native process helpers must read stdout/stderr concurrently to avoid pipe deadlocks."
    );

    for script in [
        "scripts/hooks/pre-commit.ps1",
        "scripts/hooks/pre-push.ps1",
        "scripts/check-hook-readiness.ps1",
    ] {
        let content = read_file(&root.join(script));
        let content_live = strip_comment_lines(&content);
        assert!(
            content_live.contains("native-process.ps1"),
            "{script} must dot-source scripts/hooks/native-process.ps1 instead of duplicating helpers."
        );
        assert!(
            !invoke_native_re.is_match(&content)
                && !content.contains("function Invoke-NativeWithInput")
                && !content.contains("function Invoke-NativeBytesWithInput")
                && !content.contains("function Invoke-Git"),
            "{script} must not duplicate native process helper implementations."
        );
    }
}

#[test]
fn test_powershell_native_process_helpers_do_not_pollute_pipeline() {
    let root = repo_root();
    let helper = read_file(&root.join("scripts/hooks/native-process.ps1"));
    let helper_live = strip_comment_lines(&helper);
    let bare_task_result_re =
        Regex::new(r"(?m)^\s*\$[A-Za-z0-9_]+Task\.GetAwaiter\(\)\.GetResult\(\)\s*$").unwrap();

    assert!(
        helper_live.contains("[void]$stdoutTask.GetAwaiter().GetResult()"),
        "Invoke-NativeBytesWithInput must explicitly discard CopyToAsync task completion output.\n\
         Leaving a task GetResult() on the PowerShell pipeline makes callers receive \
         Object[] instead of a single result object with ExitCode/StdoutBytes."
    );
    assert!(
        !bare_task_result_re.is_match(&helper),
        "PowerShell native process helpers must not leave async task completion \
         results on the output pipeline; assign or [void]-discard them so callers \
         always receive exactly one result object."
    );
}

#[test]
#[serial_test::serial]
fn test_powershell_native_bytes_helper_returns_single_result_object_when_pwsh_available() {
    let root = repo_root();
    let output = Command::new("pwsh")
        .args([
            "-NoLogo",
            "-NoProfile",
            "-NonInteractive",
            "-Command",
            r#"
                . ./scripts/hooks/native-process.ps1
                function Assert-SingleResult($name, $result, [string[]]$properties) {
                    if ($result -is [array]) {
                        throw "$name returned an array with $($result.Count) items"
                    }
                    foreach ($property in $properties) {
                        if ($null -eq $result.PSObject.Properties[$property]) {
                            throw "$name result is missing $property"
                        }
                    }
                    if ($result.ExitCode -ne 0) {
                        throw "$name failed: $($result.Output)"
                    }
                }

                $native = Invoke-Native -FileName "git" -Arguments @("--version")
                Assert-SingleResult "Invoke-Native" $native @("ExitCode", "Stdout", "Stderr", "Output")
                if (-not $native.Stdout.Contains("git version")) {
                    throw "Invoke-Native did not capture stdout"
                }

                $withInput = Invoke-NativeWithInput -FileName "git" -Arguments @("hash-object", "--stdin") -InputText "contract"
                Assert-SingleResult "Invoke-NativeWithInput" $withInput @("ExitCode", "Stdout", "Stderr", "Output")
                if ([string]::IsNullOrWhiteSpace($withInput.Stdout)) {
                    throw "Invoke-NativeWithInput did not capture stdout"
                }

                $objectId = (git rev-parse :AGENTS.md).Trim()
                $bytes = Invoke-NativeBytesWithInput -FileName "git" -Arguments @("cat-file", "--batch") -InputText "$objectId`n"
                Assert-SingleResult "Invoke-NativeBytesWithInput" $bytes @("ExitCode", "StdoutBytes", "Stderr", "Output")
                if ($bytes.StdoutBytes.Length -le 0) {
                    throw "Invoke-NativeBytesWithInput returned no stdout bytes"
                }
            "#,
        ])
        .current_dir(&root)
        .output();

    let Ok(output) = output else {
        eprintln!("Skipping PowerShell runtime contract test because pwsh is unavailable.");
        return;
    };

    assert!(
        output.status.success(),
        "Invoke-NativeBytesWithInput must return one object with ExitCode and StdoutBytes.\n\
         stdout: {}\nstderr: {}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
}

#[test]
#[serial_test::serial]
fn test_pre_commit_doc_version_sync_logic_when_pwsh_available() {
    let root = repo_root();
    let output = Command::new("pwsh")
        .args([
            "-NoLogo",
            "-NoProfile",
            "-NonInteractive",
            "-Command",
            r##"
                . ./scripts/hooks/pre-commit.ps1 -SourceOnly
                function Assert($condition, $message) {
                    if (-not $condition) { throw $message }
                }

                # 1) Version is read from the [package] table only.
                $toml = "[package]`nname = `"x`"`nversion = `"1.2.3`"`n`n[dependencies]`nversion = `"9.9.9`"`n"
                Assert ((Read-CargoPackageVersion -CargoTomlText $toml) -eq "1.2.3") "version must be parsed from the [package] table, not other tables"
                Assert ($null -eq (Read-CargoPackageVersion -CargoTomlText "")) "empty Cargo.toml text must yield a null version"

                # 2) library-usage: both dependency forms rewritten; <version>
                #    placeholder skipped; CRLF preserved verbatim.
                $lib = "signal-fish-server = `"0.2.0`"`r`nsignal-fish-server = { version = `"0.2.0`", features = [`"tls`"] }`r`nsignal-fish-server = `"<version>`"`r`n"
                $libOut = Get-DocVersionSyncedContent -Path "docs/library-usage.md" -Content $lib -Version "0.3.0"
                Assert ($libOut.Contains("signal-fish-server = `"0.3.0`"")) "plain dependency form must be synced"
                Assert ($libOut.Contains("version = `"0.3.0`", features")) "table dependency form must be synced"
                Assert ($libOut.Contains("signal-fish-server = `"<version>`"")) "the <version> placeholder must be left untouched"
                Assert (-not $libOut.Contains("0.2.0")) "no stale version must remain"
                Assert ($libOut.Contains("`r`n")) "CRLF line endings must be preserved"

                # 3) context.md metadata line rewritten exactly; CRLF preserved
                #    (this branch uses a different regex than library-usage).
                $ctx = "# Title`r`n- **Version:** 0.2.0`r`n- **Code name:** Signal Fish`r`n"
                $ctxOut = Get-DocVersionSyncedContent -Path ".llm/context.md" -Content $ctx -Version "0.3.0"
                Assert ($ctxOut.Contains("- **Version:** 0.3.0")) "context.md version line must be synced"
                Assert (-not $ctxOut.Contains("0.2.0")) "no stale context.md version must remain"
                Assert ($ctxOut.Contains("- **Version:** 0.3.0`r`n")) "context.md CRLF line endings must be preserved"

                # 4) Idempotent: re-syncing already-correct content is a no-op.
                $again = Get-DocVersionSyncedContent -Path "docs/library-usage.md" -Content $libOut -Version "0.3.0"
                Assert ($again -ceq $libOut) "version sync must be idempotent"

                # 5) Non-site files are returned byte-for-byte unchanged, AND the
                #    library-usage regex is anchored on `signal-fish-server` so a
                #    bare JSON `"version": "0.2.0"` line is never rewritten. This
                #    is why .vscode/launch.json (schema version) and
                #    spec/*.asyncapi.yaml (protocol version) can never be corrupted.
                $jsonVersion = "  `"version`": `"0.2.0`","
                Assert ((Get-DocVersionSyncedContent -Path ".vscode/launch.json" -Content $jsonVersion -Version "0.3.0") -ceq $jsonVersion) "non-site files must be left untouched"
                Assert ((Get-DocVersionSyncedContent -Path "docs/library-usage.md" -Content $jsonVersion -Version "0.3.0") -ceq $jsonVersion) "a bare JSON version line must not match the signal-fish-server-anchored regex"

                # 6) Honesty guard: never report compliant on a state the checker
                #    still rejects (path/git dep with no version key; a context.md
                #    whose required version line was deleted).
                Assert ($null -ne (Get-DocVersionResidualProblem -Path "docs/library-usage.md" -Content "signal-fish-server = { path = `"../..`" }" -Version "0.3.0")) "a version-less signal-fish-server dependency must be flagged unfixable"
                Assert ($null -ne (Get-DocVersionResidualProblem -Path "docs/library-usage.md" -Content "signal-fish-server = { git = `"https://x`", tag = `"0.3.0`" }" -Version "0.3.0")) "a version-less dep that merely mentions the crate version elsewhere (git tag) must still be flagged"
                Assert ($null -eq (Get-DocVersionResidualProblem -Path "docs/library-usage.md" -Content $libOut -Version "0.3.0")) "fully-synced library-usage content must have no residual problem"
                Assert ($null -ne (Get-DocVersionResidualProblem -Path ".llm/context.md" -Content "# Title`nno version line here`n" -Version "0.3.0")) "a missing context.md version line must be flagged unfixable"
                Assert ($null -eq (Get-DocVersionResidualProblem -Path ".llm/context.md" -Content $ctxOut -Version "0.3.0")) "synced context.md content must have no residual problem"
            "##,
        ])
        .current_dir(&root)
        .output();

    let Ok(output) = output else {
        eprintln!("Skipping doc version sync logic test because pwsh is unavailable.");
        return;
    };

    assert!(
        output.status.success(),
        "pre-commit.ps1 doc version sync helpers must satisfy the version-sync contract.\nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
}

#[test]
#[serial_test::serial]
fn test_pre_commit_doc_version_sync_restages_corrected_docs_end_to_end_when_pwsh_available() {
    let root = repo_root();
    let hook = root.join("scripts/hooks/pre-commit.ps1");

    // Throwaway repo so we exercise the REAL index re-staging path
    // (Set-IndexText / git update-index), proving fixer output satisfies the
    // checker's contract, without mutating this repository.
    let temp = unique_temp_dir("docver-e2e");
    let dir = temp.path();

    let git = |args: &[&str]| -> std::io::Result<std::process::Output> {
        Command::new("git").args(args).current_dir(dir).output()
    };

    let Ok(init) = git(&["init", "-q"]) else {
        eprintln!("Skipping doc version sync e2e test because git is unavailable.");
        return;
    };
    if !init.status.success() {
        eprintln!("Skipping doc version sync e2e test because git init failed.");
        return;
    }
    let _ = git(&["config", "user.email", "test@example.com"]);
    let _ = git(&["config", "user.name", "Test"]);
    let _ = git(&["config", "commit.gpgsign", "false"]);

    // Seed a repo whose docs match the original crate version, then commit.
    write_file(
        &dir.join("Cargo.toml"),
        "[package]\nname = \"x\"\nversion = \"0.2.0\"\n",
    );
    write_file(
        &dir.join("docs/library-usage.md"),
        "signal-fish-server = \"0.2.0\"\nsignal-fish-server = { version = \"0.2.0\", features = [\"tls\"] }\n",
    );
    write_file(&dir.join(".llm/context.md"), "- **Version:** 0.2.0\n");
    assert!(git(&["add", "-A"]).unwrap().status.success());
    assert!(git(&["commit", "-q", "-m", "init", "--no-verify"])
        .unwrap()
        .status
        .success());

    // Bump ONLY the manifest and stage it, exactly like a real version bump
    // that forgets the docs — the scenario that broke CI.
    write_file(
        &dir.join("Cargo.toml"),
        "[package]\nname = \"x\"\nversion = \"0.9.9\"\n",
    );
    assert!(git(&["add", "Cargo.toml"]).unwrap().status.success());

    let output = Command::new("pwsh")
        .args(["-NoLogo", "-NoProfile", "-NonInteractive", "-File"])
        .arg(&hook)
        .current_dir(dir)
        .output();
    let Ok(output) = output else {
        eprintln!("Skipping doc version sync e2e test because pwsh is unavailable.");
        return;
    };
    assert!(
        output.status.success(),
        "pre-commit hook must succeed and auto-sync docs from the bumped Cargo.toml.\nstdout: {}\nstderr: {}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );

    // The STAGED (index) docs must now carry the bumped version, so the commit
    // that lands is internally consistent and the checker would pass.
    let staged = |path: &str| -> String {
        let out = git(&["show", &format!(":{path}")]).expect("git show staged blob");
        String::from_utf8_lossy(&out.stdout).to_string()
    };
    let lib = staged("docs/library-usage.md");
    assert!(
        lib.contains("signal-fish-server = \"0.9.9\""),
        "plain dependency form must be re-staged at 0.9.9, got:\n{lib}"
    );
    assert!(
        lib.contains("version = \"0.9.9\""),
        "table dependency form must be re-staged at 0.9.9, got:\n{lib}"
    );
    assert!(
        !lib.contains("0.2.0"),
        "no stale version may remain in the staged docs, got:\n{lib}"
    );
    let ctx = staged(".llm/context.md");
    assert!(
        ctx.contains("- **Version:** 0.9.9"),
        "context.md version line must be re-staged at 0.9.9, got:\n{ctx}"
    );
}

#[test]
#[serial_test::serial]
fn test_pre_push_workflow_direct_script_detector_matches_assignment_edge_cases_when_pwsh_available()
{
    let root = repo_root();
    let output = Command::new("pwsh")
        .args([
            "-NoLogo",
            "-NoProfile",
            "-NonInteractive",
            "-Command",
            r##"
                . ./scripts/hooks/pre-push.ps1 -SourceOnly
                function Assert($condition, $message) {
                    if (-not $condition) { throw $message }
                }
                function Get-Violations([string]$content) {
                    $violations = [System.Collections.Generic.List[string]]::new()
                    Test-WorkflowContentForDirectScripts -File "fixture.yml" -Content $content -Violations $violations
                    return @($violations)
                }

                $assignmentOnly = @'
jobs:
  preflight:
    steps:
      - run: |
          PATH_FILTERED_WORKFLOWS["Documentation Validation"]="*.md *.rs scripts/check-internal-links.sh .github/workflows/doc-validation.yml"
'@
                Assert (@(Get-Violations $assignmentOnly).Count -eq 0) "assignment-only workflow lines are data and must not be treated as direct script invocations"

                $directScript = @'
jobs:
  test:
    steps:
      - run: scripts/check-internal-links.sh --all
'@
                Assert (@(Get-Violations $directScript).Count -eq 1) "direct local script execution should be rejected"

                $interpreterScript = @'
jobs:
  test:
    steps:
      - run: bash scripts/check-internal-links.sh --all
'@
                Assert (@(Get-Violations $interpreterScript).Count -eq 0) "interpreter-invoked local scripts should be accepted"

                $commandStringScript = @'
jobs:
  test:
    steps:
      - run: bash -c './scripts/check-internal-links.sh --all'
'@
                Assert (@(Get-Violations $commandStringScript).Count -eq 1) "bash -c still relies on the script executable bit and should be rejected"
            "##,
        ])
        .current_dir(&root)
        .output();

    let Ok(output) = output else {
        eprintln!("Skipping PowerShell pre-push detector test because pwsh is unavailable.");
        return;
    };

    assert!(
        output.status.success(),
        "PowerShell pre-push workflow detector should match Rust detector edge cases.\n\
         stdout: {}\nstderr: {}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
}

#[test]
#[serial_test::serial]
fn test_pre_commit_rust_panic_classifier_handles_test_contexts_when_pwsh_available() {
    let root = repo_root();
    let output = Command::new("pwsh")
        .args([
            "-NoLogo",
            "-NoProfile",
            "-NonInteractive",
            "-Command",
            r##"
                . ./scripts/hooks/pre-commit.ps1 -SourceOnly
                function Assert($condition, $message) {
                    if (-not $condition) { throw $message }
                }
                function Find-Line([string]$content, [string]$needle) {
                    $lines = [string[]]($content -split "`r?`n")
                    for ($index = 0; $index -lt $lines.Count; $index++) {
                        if ($lines[$index].Contains($needle)) { return $index + 1 }
                    }
                    throw "Missing line containing: $needle"
                }
                function Find-Line([string[]]$lines, [string]$needle) {
                    for ($index = 0; $index -lt $lines.Count; $index++) {
                        if ($lines[$index].Contains($needle)) { return $index + 1 }
                    }
                    throw "Missing line containing: $needle"
                }

                $content = @'
fn production() {
    panic!("prod");
}

#[cfg(test)]
fn helper() {
    let _ = "}";
    let _ = result.expect("test helper");
}

#[cfg(all(test, feature = "x"))] impl Foo {
    fn helper(&self) {
        let _ = r#"{"#;
        panic!("test impl");
    }
}

#[cfg(not(test))]
fn cfg_not_test() {
    panic!("prod cfg not");
}

#[cfg(any(test, feature = "x"))]
fn any_test_or_feature() {
    panic!("any test or feature prod");
}

#[cfg(not(any(test, feature = "x")))]
fn not_any_test_or_feature() {
    panic!("not any test or feature prod");
}

// #[cfg(test)] appears in documentation, not as an attribute.
fn commented_attribute_is_production() {
    panic!("commented attr prod");
}

#[cfg(test)]
fn lifetime_helper<'a>(input: &'a str) -> &'a str {
    let _ = result.expect("test lifetime");
    input
}

fn after_lifetime_helper() {
    panic!("after lifetime prod");
}
'@
                $lines = [string[]]($content -split "`r?`n")
                $testLines = Get-RustTestLineSet -Content $content -MaxLine $lines.Count

                Assert ($testLines.Contains((Find-Line $lines 'expect("test helper")'))) "cfg(test) fn body should be test code"
                Assert ($testLines.Contains((Find-Line $lines 'panic!("test impl")'))) "cfg(all(test,...)) impl body should be test code"
                Assert ($testLines.Contains((Find-Line $lines 'expect("test lifetime")'))) "cfg(test) lifetime helper body should be test code"
                Assert (-not $testLines.Contains((Find-Line $lines 'panic!("prod");'))) "plain production panic should not be test code"
                Assert (-not $testLines.Contains((Find-Line $lines 'panic!("prod cfg not")'))) "cfg(not(test)) should not be test code"
                Assert (-not $testLines.Contains((Find-Line $lines 'panic!("any test or feature prod")'))) "cfg(any(test, feature)) can compile in production and should not be test-only"
                Assert (-not $testLines.Contains((Find-Line $lines 'panic!("not any test or feature prod")'))) "cfg(not(any(test, feature))) can compile in production and should not be test-only"
                Assert (Test-RustCfgExpressionRequiresTest -Expression 'any(test, test)') "cfg(any(test, test)) should be test-only"
                Assert (Test-RustCfgExpressionRequiresTest -Expression 'any(all(test, feature = "x"), all(test, feature = "y"))') "nested any/all expressions that all require test should be test-only"
                Assert (-not $testLines.Contains((Find-Line $lines 'panic!("commented attr prod")'))) "commented cfg(test) text should not mark production as test code"
                Assert (-not $testLines.Contains((Find-Line $lines 'panic!("after lifetime prod")'))) "lifetimes in cfg(test) items should not leak test range to following production items"

                Assert (Test-ProductionRustSourcePath -Path "src/lib.rs") "src/lib.rs should be production"
                Assert (-not (Test-ProductionRustSourcePath -Path "src/foo/tests.rs")) "src/foo/tests.rs should be test-only"
                Assert (-not (Test-ProductionRustSourcePath -Path "src/foo_test.rs")) "src/foo_test.rs should be test-only"
                Assert (-not (Test-ProductionRustSourcePath -Path "tests/integration.rs")) "tests/ should be test-only"
            "##,
        ])
        .current_dir(&root)
        .output();

    let Ok(output) = output else {
        eprintln!("Skipping PowerShell rust classifier test because pwsh is unavailable.");
        return;
    };

    assert!(
        output.status.success(),
        "PowerShell rust panic classifier should handle cfg(test), cfg(all(test,...)), \
         cfg(not(test)), string/raw-string braces, and test file paths.\n\
         stdout: {}\nstderr: {}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
}

