#[test]
#[cfg(unix)]
fn test_check_no_panics_script_patterns_scrubs_nested_cargo_env() {
    use std::fs::Permissions;
    use std::os::unix::fs::PermissionsExt;

    let root = repo_root();
    let script = root.join("scripts/check-no-panics.sh");
    let temp = common::unique_temp_dir("fake-cargo-no-panics");
    let fake_bin = temp.path().join("bin");
    let fake_cargo = fake_bin.join("cargo");
    let fake_cargo_log = temp.path().join("fake-cargo-env.txt");
    let nested_target = temp.path().join("nested-target");

    fs::create_dir_all(&fake_bin)
        .unwrap_or_else(|e| panic!("Failed to create {}: {e}", fake_bin.display()));
    common::write_file(
        &fake_cargo,
        r#"#!/usr/bin/env bash
set -euo pipefail
{
    printf 'args=%s\n' "$*"
    for var in \
        RUSTFLAGS \
        CARGO_ENCODED_RUSTFLAGS \
        RUSTDOCFLAGS \
        ASAN_OPTIONS \
        LSAN_OPTIONS \
        UBSAN_OPTIONS \
        TSAN_OPTIONS \
        MIRIFLAGS
    do
        if [ -n "${!var+x}" ]; then
            printf '%s=%s\n' "$var" "${!var}"
        else
            printf '%s=<unset>\n' "$var"
        fi
    done
    printf 'CARGO_TARGET_DIR=%s\n' "${CARGO_TARGET_DIR:-<unset>}"
} > "$FAKE_CARGO_LOG"
"#,
    );
    fs::set_permissions(&fake_cargo, Permissions::from_mode(0o755))
        .unwrap_or_else(|e| panic!("Failed to chmod {}: {e}", fake_cargo.display()));

    let original_path = std::env::var_os("PATH").expect("PATH must be set for script tests");
    let mut path = std::ffi::OsString::from(fake_bin.as_os_str());
    path.push(":");
    path.push(original_path);

    let output = bash_command()
        .arg(&script)
        .arg("patterns")
        .current_dir(&root)
        .env("PATH", path)
        .env("FAKE_CARGO_LOG", &fake_cargo_log)
        .env("NESTED_CARGO_TARGET_DIR", &nested_target)
        .env("RUSTFLAGS", "--cfg")
        .env("CARGO_ENCODED_RUSTFLAGS", "--cfg")
        .env("RUSTDOCFLAGS", "--cfg")
        .env(
            "CARGO_TARGET_DIR",
            root.join("target").join("poisoned-parent-target"),
        )
        .env("ASAN_OPTIONS", "detect_odr_violation=0")
        .env("LSAN_OPTIONS", "detect_leaks=1")
        .env("UBSAN_OPTIONS", "print_stacktrace=1")
        .env("TSAN_OPTIONS", "halt_on_error=1")
        .env("MIRIFLAGS", "-Zmiri-poisoned-parent")
        .output()
        .unwrap_or_else(|e| panic!("Failed to run {}: {e}", script.display()));

    let stdout = String::from_utf8_lossy(&output.stdout);
    let stderr = String::from_utf8_lossy(&output.stderr);
    assert!(
        output.status.success(),
        "check-no-panics.sh patterns should pass with a fake cargo command.\n\
         This regression runs with poisoned inherited Cargo instrumentation \
         variables so the script must scrub them before invoking nested Cargo.\n\
         stdout: {stdout}\nstderr: {stderr}",
    );
    assert!(
        stdout.contains("Scrubbing inherited Cargo instrumentation env"),
        "check-no-panics.sh should report when it scrubs inherited Cargo \
         instrumentation variables.\nstdout: {stdout}\nstderr: {stderr}"
    );
    assert!(
        stdout.contains("Nested Cargo target dir:"),
        "check-no-panics.sh should print the isolated nested Cargo target dir \
         for diagnostics.\nstdout: {stdout}\nstderr: {stderr}"
    );
    assert!(
        stdout.contains(
            "Nested Cargo command: cargo test --locked --test no_panic_policy_scan --quiet"
        ),
        "check-no-panics.sh should print the delegated nested Cargo command \
         for diagnostics.\nstdout: {stdout}\nstderr: {stderr}"
    );

    let fake_cargo_output = read_file(&fake_cargo_log);
    assert!(
        fake_cargo_output.contains("args=test --locked --test no_panic_policy_scan --quiet"),
        "check-no-panics.sh patterns must invoke the syn-backed scanner test \
         through nested Cargo.\nFake cargo output:\n{fake_cargo_output}"
    );
    assert!(
        fake_cargo_output.contains(&format!("CARGO_TARGET_DIR={}", nested_target.display())),
        "check-no-panics.sh must route nested Cargo artifacts into the isolated \
         target directory.\nFake cargo output:\n{fake_cargo_output}"
    );

    let inherited_vars = [
        "RUSTFLAGS",
        "CARGO_ENCODED_RUSTFLAGS",
        "RUSTDOCFLAGS",
        "ASAN_OPTIONS",
        "LSAN_OPTIONS",
        "UBSAN_OPTIONS",
        "TSAN_OPTIONS",
        "MIRIFLAGS",
    ];
    let leaked_vars = inherited_vars
        .iter()
        .filter(|var| !fake_cargo_output.contains(&format!("{var}=<unset>")))
        .copied()
        .collect::<Vec<_>>();

    assert!(
        leaked_vars.is_empty(),
        "check-no-panics.sh must scrub inherited Cargo/sanitizer/Miri \
         instrumentation before invoking nested Cargo.\n\
         Leaked variables: {leaked_vars:?}\nFake cargo output:\n{fake_cargo_output}"
    );
}

#[test]
fn test_pinned_nightly_staleness_warning() {
    let root = repo_root();
    let workflow_path = root.join(".github/workflows/ci-safety.yml");

    if !workflow_path.exists() {
        return; // ci-safety.yml is optional
    }

    let content = strip_comment_lines(&read_file(&workflow_path));
    let nightly_pattern =
        Regex::new(r"nightly-[0-9]{4}-[0-9]{2}-[0-9]{2}").expect("valid nightly regex");
    let operational_versions: BTreeSet<String> = nightly_pattern
        .find_iter(&content)
        .map(|found| found.as_str().to_string())
        .collect();
    assert_eq!(
        operational_versions.len(),
        1,
        "ci-safety.yml must use exactly one operational date-pinned nightly; comments do not \
         satisfy the freshness policy. Observed: {operational_versions:?}"
    );
    let nightly_version = operational_versions
        .into_iter()
        .next()
        .expect("one operational nightly was asserted");

    // Compare the actual date to UTC today. The former frozen reference month
    // let this test remain green while the workflow-hygiene gate correctly
    // reported the same pin as 182 days old.
    let date_part = nightly_version
        .strip_prefix("nightly-")
        .expect("nightly version must start with 'nightly-'");
    let nightly_date = chrono::NaiveDate::parse_from_str(date_part, "%Y-%m-%d")
        .unwrap_or_else(|error| panic!("Invalid nightly date '{date_part}': {error}"));
    let today = chrono::Utc::now().date_naive();
    let age_days = today.signed_duration_since(nightly_date).num_days();
    assert!(
        age_days >= 0,
        "Pinned nightly '{nightly_version}' is {age_days} days in the future relative to {today}."
    );
    assert!(
        age_days <= 180,
        "Pinned nightly '{nightly_version}' is {age_days} days old.\n\
         Test a current date-pinned nightly and update every analysis-tool pin.\n\
         See ci-safety.yml header for update criteria."
    );
}

#[test]
#[cfg(unix)]
fn test_scripts_pass_basic_syntax_check() {
    let root = repo_root();
    let script_dirs = [root.join("scripts"), root.join(".github/scripts")];
    let mut entries = Vec::new();

    for scripts_dir in &script_dirs {
        if !scripts_dir.exists() {
            continue;
        }

        entries.extend(
            std::fs::read_dir(scripts_dir)
                .unwrap_or_else(|error| panic!("Failed to read {}: {error}", scripts_dir.display()))
                .filter_map(|e| e.ok())
                .filter(|e| e.path().extension().is_some_and(|ext| ext == "sh")),
        );
    }

    assert!(
        !entries.is_empty(),
        "Expected at least one repository shell script in scripts/ or .github/scripts/"
    );
    assert!(
        entries
            .iter()
            .any(|entry| entry.path()
                == root.join(".github/scripts/validate-rust-markdown-blocks.sh")),
        "Shell syntax test must include the Rust markdown validator used by doc-validation.yml"
    );

    let mut failures = Vec::new();

    for entry in &entries {
        let path = entry.path();
        // Use bash -n for syntax check (always available, unlike shellcheck)
        let output = bash_command()
            .arg("-n")
            .arg(&path)
            .output()
            .unwrap_or_else(|e| panic!("Failed to syntax-check {}: {e}", path.display()));

        if !output.status.success() {
            failures.push(format!(
                "{}: {}",
                path.file_name().unwrap().to_string_lossy(),
                String::from_utf8_lossy(&output.stderr).trim()
            ));
        }
    }

    assert!(
        failures.is_empty(),
        "Shell scripts have syntax errors:\n{}",
        failures.join("\n")
    );
}

