#[test]
fn test_dtolnay_rust_toolchain_v1_has_explicit_toolchain_input() {
    let root = repo_root();
    let workflows_dir = root.join(".github/workflows");
    let workflow_files = collect_workflow_files(&workflows_dir);

    assert!(
        !workflow_files.is_empty(),
        "No workflow files found in .github/workflows/\n\
         Workflows directory: {}",
        workflows_dir.display()
    );

    let mut violations = Vec::new();

    for entry in &workflow_files {
        let path = entry.path();
        let content = read_file(&path);
        let filename = path.file_name().unwrap().to_string_lossy();
        let lines: Vec<&str> = content.lines().collect();

        for (i, line) in lines.iter().enumerate() {
            let trimmed = line.trim();
            if !trimmed.contains("dtolnay/rust-toolchain@v") {
                continue;
            }

            // Look at the next 5 lines for a `toolchain:` field
            let mut found_toolchain = false;
            let lookahead_end = (i + 6).min(lines.len());
            for next_line in lines.iter().take(lookahead_end).skip(i + 1) {
                let next_trimmed = next_line.trim();

                // Stop early if we hit another step marker
                if next_trimmed.starts_with("- name:") || next_trimmed.starts_with("- uses:") {
                    break;
                }

                if next_trimmed.starts_with("toolchain:") {
                    found_toolchain = true;
                    break;
                }
            }

            if !found_toolchain {
                violations.push(format!(
                    "{filename}:{}: uses: dtolnay/rust-toolchain@v1\n  \
                     Missing explicit `toolchain:` input in the `with:` block.\n  \
                     Every dtolnay/rust-toolchain@v1 invocation must specify a \
                     pinned toolchain version.",
                    i + 1
                ));
            }
        }
    }

    assert!(
        violations.is_empty(),
        "dtolnay/rust-toolchain@v1 invocations missing explicit toolchain input:\n\n{}",
        violations.join("\n")
    );
}

#[test]
fn test_same_action_uses_consistent_ref_across_workflows() {
    // Every action should resolve to a single reference value across workflows
    // to prevent version drift (e.g., one file uses @v2 while another uses @v1).

    let root = repo_root();
    let workflows_dir = root.join(".github/workflows");

    let workflow_files = collect_workflow_files(&workflows_dir);

    // A guard that silently passes when it inspects nothing is worse than no
    // guard at all: a broken glob, renamed directory, or parser regression
    // would turn this drift check permanently green without anyone noticing.
    // Assert we actually discovered workflows (matching every sibling pinning
    // test) and, below, that we parsed at least one remote action from them.
    assert!(
        !workflow_files.is_empty(),
        "No workflow files found in .github/workflows/\n\
         Workflows directory: {}",
        workflows_dir.display()
    );

    // Map of action name -> Vec<(reference, filename, line_num)>
    let mut action_refs: std::collections::HashMap<String, Vec<(String, String, usize)>> =
        std::collections::HashMap::new();

    for entry in &workflow_files {
        let path = entry.path();
        let content = read_file(&path);
        let filename = path.file_name().unwrap().to_string_lossy().to_string();

        for (line_num, line) in content.lines().enumerate() {
            let line_num = line_num + 1; // 1-indexed for human readability
            let trimmed = line.trim();

            let Some(uses_value) = extract_uses_value(trimmed) else {
                continue;
            };
            let Some((action_name, action_ref)) = parse_remote_action_reference(uses_value) else {
                continue;
            };

            action_refs
                .entry(action_name.to_string())
                .or_default()
                .push((action_ref.to_string(), filename.clone(), line_num));
        }
    }

    // The repository pins many remote actions (checkout, rust-toolchain,
    // rust-cache, install-action, ...). Parsing zero of them means the
    // `uses:` extractor or action-reference parser silently broke, which
    // would mask real drift — fail loudly instead of vacuously passing.
    assert!(
        !action_refs.is_empty(),
        "Parsed zero remote `uses:` action references from {} workflow file(s).\n\
         The repository is known to pin remote actions, so this indicates the\n\
         `uses:` extractor or action-reference parser regressed.",
        workflow_files.len()
    );

    let mut inconsistencies = Vec::new();

    for (action_name, refs) in &action_refs {
        let unique_refs: std::collections::HashSet<&str> = refs
            .iter()
            .map(|(action_ref, _, _)| action_ref.as_str())
            .collect();

        if unique_refs.len() > 1 {
            let mut details = format!(
                "Action '{}' uses {} different refs across workflow files:",
                action_name,
                unique_refs.len()
            );
            for (action_ref, filename, line_num) in refs {
                details.push_str(&format!("\n    {filename}:{line_num}: {action_ref}"));
            }
            details.push_str(&format!(
                "\n  Fix: Update all references to '{action_name}' to use the same ref.\n  \
                 Pick the most recent version and apply it to every workflow file.\n  \
                 Search with: grep -rn '{action_name}' .github/workflows/"
            ));
            inconsistencies.push(details);
        }
    }

    if !inconsistencies.is_empty() {
        let total_actions = action_refs.len();
        let consistent_actions = total_actions - inconsistencies.len();
        panic!(
            "GitHub Action refs must be consistent across all workflow files:\n\n\
             {}\n\n\
             Diagnostic Information:\n\
             - Unique actions found: {}\n\
             - Actions with consistent refs: {}\n\
             - Actions with inconsistent refs: {}\n\n\
             Why this matters:\n\
             - Different refs for the same action mean different code versions are running\n\
             - Version drift can cause subtle behavior differences across workflows\n\n\
             How to fix:\n\
             1. Identify the desired ref for each action (e.g., @v2.7.5)\n\
             2. Update ALL workflow files to use that same ref\n\
             3. Verify with: grep -rn 'action-name@' .github/workflows/",
            inconsistencies.join("\n\n"),
            total_actions,
            consistent_actions,
            inconsistencies.len()
        );
    }
}

#[test]
fn test_dockerfile_suppresses_false_positive_security_warnings() {
    // Validates that the Dockerfile includes a BuildKit check directive to
    // suppress false-positive security warnings when ENV variables have
    // security-adjacent names (like SECURITY, AUTH, TOKEN, KEY) but are
    // assigned non-sensitive values (like "false", "true", "0", "1").
    //
    // A previous CI failure occurred because Docker Scout / BuildKit flagged
    // ENV variables like SIGNAL_FISH__SECURITY__REQUIRE_METRICS_AUTH=false as
    // potential secret leaks (SecretsUsedInArgOrEnv). The fix is to add a
    // `# check=skip=SecretsUsedInArgOrEnv` directive at the top of the
    // Dockerfile to suppress these false positives.

    let root = repo_root();
    let dockerfile = root.join("Dockerfile");

    if !dockerfile.exists() {
        return;
    }

    let content = read_file(&dockerfile);

    // Patterns that Docker Scout / BuildKit flag as potential secrets in ENV names
    let security_patterns = ["SECURITY", "SECRET", "PASSWORD", "TOKEN", "KEY", "AUTH"];

    // Values that are clearly non-sensitive (boolean/numeric flags)
    let safe_values = ["false", "true", "0", "1"];

    // Find ENV variables with security-adjacent names assigned non-sensitive values
    let mut flagged_env_vars = Vec::new();

    for (line_num, line) in content.lines().enumerate() {
        let line_num = line_num + 1; // 1-indexed for human readability
        let trimmed = line.trim();

        // Match ENV directives (ENV KEY=value or ENV KEY value)
        if let Some(rest) = trimmed.strip_prefix("ENV ") {
            let rest = rest.trim();

            // Extract the variable name and value
            let (var_name, var_value) = if let Some(eq_pos) = rest.find('=') {
                let name = rest[..eq_pos].trim();
                let value = rest[eq_pos + 1..].trim().trim_matches('"');
                (name, value)
            } else {
                // ENV KEY value (space-separated form)
                let mut parts = rest.splitn(2, char::is_whitespace);
                let name = parts.next().unwrap_or("");
                let value = parts.next().unwrap_or("").trim().trim_matches('"');
                (name, value)
            };

            let name_upper = var_name.to_uppercase();
            let has_security_pattern = security_patterns
                .iter()
                .any(|pattern| name_upper.contains(pattern));
            let has_safe_value = safe_values.contains(&var_value);

            if has_security_pattern && has_safe_value {
                flagged_env_vars.push(format!("  line {line_num}: ENV {var_name}={var_value}"));
            }
        }
    }

    if flagged_env_vars.is_empty() {
        // No security-adjacent ENV vars with safe values, no directive needed
        return;
    }

    // Check that the Dockerfile starts with the suppression directive
    let first_line = content.lines().next().unwrap_or("");
    let has_check_directive =
        first_line.contains("# check=") && first_line.contains("skip=SecretsUsedInArgOrEnv");

    assert!(
        has_check_directive,
        "Dockerfile contains ENV variables with security-adjacent names assigned \
         non-sensitive values, but is missing the BuildKit check directive to \
         suppress false-positive security warnings.\n\n\
         Flagged ENV variables:\n{}\n\n\
         These variables have names matching security patterns ({}) but are \
         assigned safe values ({}). Docker Scout / BuildKit will flag these as \
         potential secret leaks (SecretsUsedInArgOrEnv).\n\n\
         Fix: Add this directive as the FIRST line of the Dockerfile:\n\
         # check=skip=SecretsUsedInArgOrEnv\n\n\
         Why this matters:\n\
         - Docker BuildKit's SecretsUsedInArgOrEnv check flags any ENV with \
         security-related names\n\
         - These are false positives because the values are non-sensitive boolean flags\n\
         - Without the suppression directive, CI builds will emit warnings or fail\n\n\
         File: {}",
        flagged_env_vars.join("\n"),
        security_patterns.join(", "),
        safe_values.join(", "),
        dockerfile.display()
    );
}

#[test]
fn test_audit_job_installs_and_verifies_pinned_cargo_audit() {
    // Keep the advisory scanner reproducible and fail closed if the installer
    // ever provides a different binary than the requested release.

    let root = repo_root();
    let ci_content = read_file(&root.join(".github/workflows/ci.yml"));

    let audit_section = extract_audit_section(&strip_comment_lines(&ci_content));

    for required in [
        "tool: cargo-audit@0.22.2",
        "fallback: none",
        "run: cargo-audit --version | grep -Fxq 'cargo-audit 0.22.2'",
    ] {
        assert!(
            audit_section.contains(required),
            "Audit job must install and verify the exact cargo-audit release; missing `{required}`"
        );
    }
}

#[test]
fn test_audit_job_covers_every_tracked_cargo_graph() {
    // Exact-release compatibility fixtures intentionally opt out of automatic
    // updates, but they still need the scheduled cargo-audit second opinion.

    let root = repo_root();
    let ci_content = read_file(&root.join(".github/workflows/ci.yml"));

    let audit_section = extract_audit_section(&ci_content);
    let audit_section_live = extract_audit_section(&strip_comment_lines(&ci_content));
    let audit_commands = audit_section_live
        .lines()
        .filter_map(|line| line.trim().strip_prefix("run: "))
        .collect::<BTreeSet<_>>();

    for lockfile in tracked_cargo_lockfiles(&root) {
        let expected_command = if lockfile == "Cargo.lock" {
            "cargo audit".to_owned()
        } else {
            format!("cargo audit --file {lockfile}")
        };
        assert!(
            audit_commands.contains(expected_command.as_str()),
            "The scheduled cargo-audit job must scan every tracked Cargo graph.\n\
             Missing command: {expected_command}\n\
             Uncovered lockfile: {lockfile}"
        );
    }

    assert!(
        !audit_section.contains("cargo audit --locked"),
        "cargo-audit reads Cargo.lock directly and does not support --locked.\n\
         Fix: use `cargo audit` without --locked in .github/workflows/ci.yml."
    );
}

#[test]
fn test_deny_job_covers_every_tracked_cargo_graph() {
    let root = repo_root();
    let ci_content = read_live_file(&root.join(".github/workflows/ci.yml"));
    let documents = Yaml::load_from_str(&ci_content).expect("ci.yml must parse as YAML");
    let steps = documents
        .first()
        .and_then(|document| document.as_mapping_get("jobs"))
        .and_then(|jobs| jobs.as_mapping_get("deny"))
        .and_then(|job| job.as_mapping_get("steps"))
        .and_then(Yaml::as_sequence)
        .unwrap_or_else(|| panic!("ci.yml must define jobs.deny.steps"));
    let configured = steps
        .iter()
        .filter(|step| {
            step.as_mapping_get("uses")
                .and_then(Yaml::as_str)
                .is_some_and(|uses| uses.starts_with("EmbarkStudios/cargo-deny-action@"))
        })
        .map(|step| {
            step.as_mapping_get("with")
                .and_then(|with| with.as_mapping_get("manifest-path"))
                .and_then(Yaml::as_str)
                .unwrap_or("Cargo.toml")
                .to_owned()
        })
        .collect::<BTreeSet<_>>();
    let expected = tracked_cargo_lockfiles(&root)
        .into_iter()
        .map(|lockfile| lockfile.replace("Cargo.lock", "Cargo.toml"))
        .collect::<BTreeSet<_>>();

    assert_eq!(
        configured, expected,
        "the push/PR/daily cargo-deny job must enforce every tracked Cargo graph"
    );

    let direct_cargo_deny = Regex::new(r"(?m)\bcargo(?:\s+\+\S+)?\s+deny\b|\bcargo-deny\b")
        .expect("cargo-deny invocation regex must compile");
    let mut dispatch_audits = BTreeSet::new();
    for entry in collect_workflow_files(&root.join(".github/workflows")) {
        if entry.file_name().to_str() == Some("ci.yml") {
            continue;
        }
        let path = entry.path();
        let content = read_live_file(&path);
        let documents = Yaml::load_from_str(&content)
            .unwrap_or_else(|error| panic!("{} must parse: {error}", path.display()));
        let jobs = documents
            .first()
            .and_then(|document| document.as_mapping_get("jobs"))
            .and_then(Yaml::as_mapping)
            .unwrap_or_else(|| panic!("{} must define jobs", path.display()));
        for (job_key, job) in jobs {
            let invokes_cargo_deny = job
                .as_mapping_get("steps")
                .and_then(Yaml::as_sequence)
                .is_some_and(|steps| {
                    steps.iter().any(|step| {
                        step.as_mapping_get("uses")
                            .and_then(Yaml::as_str)
                            .is_some_and(|uses| {
                                uses.starts_with("EmbarkStudios/cargo-deny-action@")
                            })
                            || step
                                .as_mapping_get("run")
                                .and_then(Yaml::as_str)
                                .is_some_and(|run| direct_cargo_deny.is_match(run))
                    })
                });
            if !invokes_cargo_deny {
                continue;
            }
            assert_eq!(
                job.as_mapping_get("if").and_then(Yaml::as_str),
                Some("github.event_name == 'workflow_dispatch'"),
                "cargo-deny outside central CI must be dispatch-only: {} / {}",
                path.display(),
                job_key.as_str().unwrap_or("<job>")
            );
            dispatch_audits.insert(format!(
                "{}:{}",
                entry.file_name().to_string_lossy(),
                job_key.as_str().unwrap_or("<job>")
            ));
        }
    }
    let expected_dispatch_audits = BTreeSet::from([
        "fortress-interop.yml:client-deny".to_owned(),
        "fortress-wasm-interop.yml:dependency-audit".to_owned(),
        "webrtc-interop.yml:client-deny".to_owned(),
    ]);
    assert_eq!(
        dispatch_audits, expected_dispatch_audits,
        "manual interop runs must retain dependency audits without duplicating push/PR runners"
    );
}

#[test]
fn test_audit_job_covers_every_dependabot_managed_npm_graph() {
    let root = repo_root();
    let path = root.join(".github/workflows/ci.yml");
    let content = read_live_file(&path);
    let documents = Yaml::load_from_str(&content).expect("ci.yml must parse as YAML");
    let steps = documents
        .first()
        .and_then(|document| document.as_mapping_get("jobs"))
        .and_then(|jobs| jobs.as_mapping_get("audit"))
        .and_then(|job| job.as_mapping_get("steps"))
        .and_then(Yaml::as_sequence)
        .unwrap_or_else(|| panic!("ci.yml must define jobs.audit.steps"));

    let setup_node = steps.iter().any(|step| {
        step.as_mapping_get("uses")
            .and_then(Yaml::as_str)
            .is_some_and(|uses| uses.starts_with("actions/setup-node@"))
            && step
                .as_mapping_get("with")
                .and_then(|with| with.as_mapping_get("node-version"))
                .and_then(Yaml::as_str)
                == Some("22")
    });
    assert!(
        setup_node,
        "ci.yml jobs.audit must install Node 22 before scanning npm lockfiles.\n\
         Fix: add a pinned actions/setup-node step with node-version: \"22\"."
    );

    let audited_directories = steps
        .iter()
        .filter(|step| {
            step.as_mapping_get("run")
                .and_then(Yaml::as_str)
                .is_some_and(|run| run.lines().any(|line| line.trim() == "npm audit"))
        })
        .map(|step| {
            step.as_mapping_get("working-directory")
                .and_then(Yaml::as_str)
                .unwrap_or(".")
        })
        .map(|directory| {
            if directory == "." {
                "/".to_owned()
            } else {
                format!("/{}", directory.trim_matches('/'))
            }
        })
        .collect::<BTreeSet<_>>();
    let expected = dependabot_npm_directories();
    assert_eq!(
        audited_directories, expected,
        "The scheduled audit job must run `npm audit` for every Dependabot-managed npm graph.\n\
         Expected directories: {expected:?}\n\
         Audited directories: {audited_directories:?}\n\
         Fix: add one npm audit step with the matching working-directory for every npm entry."
    );
}

#[test]
fn test_markdownlint_workflow_uses_supported_node_runtime() {
    let root = repo_root();
    let path = root.join(".github/workflows/markdownlint.yml");
    let content = read_live_file(&path);
    let documents = Yaml::load_from_str(&content).expect("markdownlint.yml must parse as YAML");
    let steps = documents
        .first()
        .and_then(|document| document.as_mapping_get("jobs"))
        .and_then(|jobs| jobs.as_mapping_get("markdownlint"))
        .and_then(|job| job.as_mapping_get("steps"))
        .and_then(Yaml::as_sequence)
        .unwrap_or_else(|| panic!("markdownlint.yml must define jobs.markdownlint.steps"));
    let setup_node_index = steps.iter().position(|step| {
        step.as_mapping_get("uses")
            .and_then(Yaml::as_str)
            .is_some_and(|uses| uses.starts_with("actions/setup-node@"))
            && step
                .as_mapping_get("with")
                .and_then(|with| with.as_mapping_get("node-version"))
                .and_then(Yaml::as_str)
                == Some("22")
    });
    let npm_ci_index = steps.iter().position(|step| {
        step.as_mapping_get("run")
            .and_then(Yaml::as_str)
            .is_some_and(|run| run.contains("npm ci"))
    });

    assert!(
        setup_node_index.is_some_and(|setup| npm_ci_index.is_some_and(|install| setup < install)),
        "markdownlint.yml must install Node 22 before `npm ci`; the pinned markdownlint-cli2 \
         requires that runtime.\nFix: add a pinned actions/setup-node step with node-version: \"22\" \
         before the dependency-install step."
    );
}

