#[test]
#[ignore = "expensive nested Cargo compile matrix; CI runs scripts/check-feature-matrix.sh once instead"]
fn test_optional_feature_compile_matrix() {
    // Data-driven checks for optional features that are expected to compile in
    // isolation. This prevents regressions from dependency migrations and
    // feature-gating drift.
    let mut failures = Vec::new();

    for &(label, feature) in OPTIONAL_FEATURE_MATRIX_CASES {
        let (success, output) = run_isolated_feature_check(feature);
        if !success {
            failures.push(format!(
                "{label} (feature `{feature}`) failed to compile:\n{output}"
            ));
        }
    }

    assert!(
        failures.is_empty(),
        "One or more optional feature compile checks failed.\n\
         These checks run in an isolated target directory with sanitizer env
         scrubbed to avoid false positives in ASan/Miri contexts.\n\n{}",
        failures.join("\n\n---\n\n"),
    );
}

#[test]
fn test_optional_feature_matrix_runs_once_in_ci_lint_job() {
    let root = repo_root();
    let ci_content = read_live_file(&root.join(".github/workflows/ci.yml"));
    let script_path = root.join("scripts/check-feature-matrix.sh");

    assert!(
        script_path.exists(),
        "scripts/check-feature-matrix.sh must exist.\n\
         Optional feature compile validation should live in a standalone script \
         so it can run once in CI instead of as a nested Cargo build inside every \
         test runner."
    );

    let script_content = read_file(&script_path);

    assert!(
        ci_content.contains("run: bash scripts/check-feature-matrix.sh"),
        "ci.yml must run scripts/check-feature-matrix.sh.\n\
         Keeping the feature compile matrix in CI preserves feature-gating coverage \
         while avoiding repeated nested Cargo builds in nextest, coverage, MSRV, \
         Miri, and sanitizer jobs. The workflow must invoke it through bash so \
         CI does not depend on checkout executable-bit metadata."
    );

    assert!(
        ci_content.contains("if: matrix.os == 'ubuntu-latest'"),
        "ci.yml should run the optional feature matrix once on ubuntu-latest.\n\
         Running it across every OS lane duplicates compile work without adding \
         meaningful feature-gating coverage."
    );

    let feature_cases_start = script_content
        .find("FEATURE_CASES=(")
        .expect("scripts/check-feature-matrix.sh should define FEATURE_CASES array");
    let feature_cases_rest = &script_content[feature_cases_start..];
    let feature_cases_end = feature_cases_rest
        .find("\n)")
        .expect("scripts/check-feature-matrix.sh FEATURE_CASES array should close with `)`");
    let feature_cases_block = &feature_cases_rest[..feature_cases_end];

    let case_regex =
        Regex::new(r#"(?m)^\s*"([^"|]+)\|([^"]+)"\s*$"#).expect("valid feature case regex");
    let actual_cases: Vec<(String, String)> = case_regex
        .captures_iter(feature_cases_block)
        .map(|captures| (captures[1].to_string(), captures[2].to_string()))
        .collect();
    let expected_cases: Vec<(String, String)> = OPTIONAL_FEATURE_MATRIX_CASES
        .iter()
        .map(|(label, feature)| ((*label).to_string(), (*feature).to_string()))
        .collect();

    assert_eq!(
        actual_cases, expected_cases,
        "scripts/check-feature-matrix.sh must keep the same data-driven \
         optional feature coverage as test_optional_feature_compile_matrix. \
         Update OPTIONAL_FEATURE_MATRIX_CASES and the script together when \
         adding or removing feature combinations."
    );
}

// ---------------------------------------------------------------------------
// Dependency Health Hardening Tests
//
// Data-driven tests validating that deny.toml maintains a comprehensive
// proactive ban list and that supply-chain policy settings remain strict.
// These tests prevent regression of dependency health invariants.
// ---------------------------------------------------------------------------

/// Crates that must appear in deny.toml [[bans.deny]] entries.
/// Each entry is (crate_name, reason_substring) — the reason substring is
/// checked to ensure the ban has a meaningful justification, not just a name.
const REQUIRED_DENY_BANS: &[(&str, &str)] = &[
    // Original bans (pre-existing)
    ("atty", "std::io::IsTerminal"),
    ("instant", "std::time::Instant"),
    // Security/TLS policy
    ("rustls-pemfile", "RUSTSEC-2025-0134"),
    ("openssl", "rustls"),
    ("openssl-sys", "rustls"),
    ("native-tls", "rustls"),
    // Build system policy
    ("gcc", "cc"),
    // Unmaintained/deprecated
    ("failure", "thiserror"),
    ("failure_derive", "thiserror"),
    ("tempdir", "tempfile"),
    ("term", "crossterm"),
    ("net2", "std::net"),
    ("rustc-serialize", "serde"),
];

fn deny_bans(content: &str) -> BTreeMap<String, String> {
    let mut bans = BTreeMap::new();
    let mut current_name = None;
    let mut in_ban = false;

    for line in content.lines().map(str::trim) {
        if line == "[[bans.deny]]" {
            if let Some(name) = current_name.take() {
                panic!("deny entry for `{name}` must define a reason before the next entry");
            }
            in_ban = true;
            continue;
        }
        if in_ban && line.starts_with('[') {
            if let Some(name) = current_name.take() {
                panic!("deny entry for `{name}` must define a reason before the next section");
            }
            in_ban = false;
        }
        if !in_ban {
            continue;
        }
        if let Some(name) = line
            .strip_prefix("name = \"")
            .and_then(|value| value.strip_suffix('"'))
        {
            current_name = Some(name.to_owned());
        } else if let Some(reason) = line
            .strip_prefix("reason = \"")
            .and_then(|value| value.strip_suffix('"'))
        {
            let name = current_name
                .take()
                .expect("every deny reason must follow a crate name");
            assert!(
                bans.insert(name.clone(), reason.to_owned()).is_none(),
                "deny policy must not contain duplicate entries for `{name}`"
            );
            in_ban = false;
        }
    }

    if let Some(name) = current_name {
        panic!("deny entry for `{name}` must define a reason");
    }
    bans
}

fn allowed_licenses(content: &str) -> BTreeSet<String> {
    let licenses = content
        .split_once("[licenses]")
        .map(|(_, rest)| rest)
        .and_then(|rest| rest.split_once("\n[").map(|(section, _)| section))
        .expect("deny policy must define a [licenses] section");
    let allow = licenses
        .split_once("allow = [")
        .map(|(_, rest)| rest)
        .and_then(|rest| rest.split_once(']').map(|(array, _)| array))
        .expect("deny policy [licenses] section must define an allow array");
    let quoted =
        Regex::new(r#""([^"]+)""#).expect("license allowlist extraction regex must compile");
    quoted
        .captures_iter(allow)
        .map(|capture| capture[1].to_owned())
        .collect()
}

#[test]
fn test_native_deny_policy_matches_root_security_baseline_with_narrow_exceptions() {
    let root = repo_root();
    let root_policy = read_live_file(&root.join("deny.toml"));
    let native_policy = read_live_file(&root.join("clients/native/deny.toml"));

    assert_eq!(
        deny_bans(&native_policy),
        deny_bans(&root_policy),
        "clients/native/deny.toml must retain the root policy's exact banned-crate names and \
         reasons. Update both policies together."
    );

    for setting in [
        "version = 2",
        "yanked = \"deny\"",
        "wildcards = \"deny\"",
        "unknown-registry = \"deny\"",
        "unknown-git = \"deny\"",
        "allow-registry = [\"https://github.com/rust-lang/crates.io-index\"]",
        "allow-git = []",
    ] {
        assert!(
            root_policy.contains(setting) && native_policy.contains(setting),
            "Root and native cargo-deny policies must both retain strict setting `{setting}`"
        );
    }

    let root_licenses = allowed_licenses(&root_policy);
    let native_licenses = allowed_licenses(&native_policy);
    let widened = native_licenses
        .difference(&root_licenses)
        .cloned()
        .collect::<Vec<_>>();
    assert!(
        widened.is_empty(),
        "The native license allowlist may be a graph-specific strict subset of root policy, \
         but must not widen it. Unexpected allowances: {widened:?}"
    );
    assert!(
        !native_licenses.contains("OpenSSL") && !native_policy.contains("[[licenses.clarify]]"),
        "The native graph's ring release declares Apache-2.0 AND ISC directly. Do not copy the \
         root graph's unmatched OpenSSL allowance or legacy ring clarification."
    );

    assert!(
        native_policy.contains("allow-wildcard-paths = true")
            && read_live_file(&root.join("clients/native/Cargo.toml"))
                .contains("signal-fish-server = { path = \"../..\" }"),
        "The native policy's sole intentional relaxation permits its private path dependency \
         on the root server crate; keep the exception and its live justification together."
    );
}

#[test]
fn test_deny_toml_bans_known_problematic_crates() {
    let root = repo_root();
    let content = read_live_file(&root.join("deny.toml"));

    let mut missing = Vec::new();
    let mut bad_reason = Vec::new();

    for &(crate_name, reason_substr) in REQUIRED_DENY_BANS {
        if !content.contains(&format!("name = \"{crate_name}\"")) {
            missing.push(crate_name);
        } else if !content.contains(reason_substr) {
            bad_reason.push((crate_name, reason_substr));
        }
    }

    assert!(
        missing.is_empty(),
        "deny.toml is missing [[bans.deny]] entries for known-problematic crates:\n\
         {}\n\n\
         Add [[bans.deny]] entries with name and reason fields for each.\n\
         See .llm/skills/supply-chain-security/SKILL.md for the proactive ban list policy.",
        missing
            .iter()
            .map(|c| format!("  - {c}"))
            .collect::<Vec<_>>()
            .join("\n")
    );

    assert!(
        bad_reason.is_empty(),
        "deny.toml ban entries have missing or incorrect reasons:\n\
         {}\n\n\
         Each ban must include a reason that mentions the recommended replacement.",
        bad_reason
            .iter()
            .map(|(c, r)| format!("  - {c}: reason must mention \"{r}\""))
            .collect::<Vec<_>>()
            .join("\n")
    );
}

