/// Verify that check-outdated.sh is intentionally excluded from run-local-ci.sh.
///
/// check-outdated.sh is an informational developer tool that reports which
/// dependencies have newer versions available. It always exits 0 and does not
/// gate on any condition. Informational tools do not belong in CI gate scripts
/// because they add noise without enforcing any quality bar. The advisory check
/// (check-advisories.sh) IS included because it enforces a security policy.
#[test]
fn test_run_local_ci_excludes_check_outdated() {
    let root = repo_root();
    let script = read_file(&root.join("scripts/run-local-ci.sh"));

    assert!(
        !script.contains("check-outdated.sh"),
        "scripts/run-local-ci.sh must NOT include check-outdated.sh.\n\
         check-outdated.sh is an informational tool (always exits 0) and does not \
         enforce any policy. Informational tools do not belong in CI gate scripts — \
         they add noise without enforcing a quality bar.\n\
         Developers can run it manually: ./scripts/check-outdated.sh"
    );
}

fn cargo_lock_package<'a>(lockfile: &'a str, name: &str, version: &str) -> &'a str {
    let marker = format!("name = \"{name}\"\nversion = \"{version}\"");
    let start = lockfile
        .find(&marker)
        .unwrap_or_else(|| panic!("Cargo.lock is missing `{marker}`"));
    &lockfile[start
        ..lockfile[start..]
            .find("\n\n")
            .map_or(lockfile.len(), |offset| start + offset)]
}

#[test]
fn test_fortress_interop_gate_is_pinned_and_runs_current_server() {
    let root = repo_root();
    let root_manifest = read_file(&root.join("Cargo.toml"));
    let manifest = read_live_file(&root.join("clients/fortress/Cargo.toml"));
    let lockfile = read_file(&root.join("clients/fortress/Cargo.lock"));
    let deny = read_file(&root.join("clients/fortress/deny.toml"));
    let workflow = read_live_file(&root.join(".github/workflows/fortress-interop.yml"));
    let runner = read_file(&root.join("scripts/run-fortress-interop.sh"));

    for dependency in [
        "fortress-rollback = \"=0.12.0\"",
        "signal-fish-client = { version = \"=0.8.0\"",
    ] {
        assert!(
            manifest.contains(dependency),
            "clients/fortress must exact-pin its production interoperability dependency: {dependency}"
        );
    }

    let fortress_package = cargo_lock_package(&lockfile, "fortress-rollback", "0.12.0");
    let codec_package = cargo_lock_package(&lockfile, "bincode-next", "2.1.0");
    let fixture_package = cargo_lock_package(&lockfile, "signal-fish-fortress-interop", "0.1.0");
    for package in [fortress_package, codec_package] {
        assert!(
            package.contains("source = \"registry+https://github.com/rust-lang/crates.io-index\""),
            "the native Fortress graph must resolve exact releases from crates.io: {package}"
        );
    }
    assert!(
        fixture_package.contains(" \"fortress-rollback\","),
        "the native fixture must directly lock Fortress Rollback: {fixture_package}"
    );
    assert_eq!(
        lockfile.matches("name = \"fortress-rollback\"\n").count(),
        1,
        "the native fixture must resolve exactly one Fortress Rollback release"
    );
    assert!(
        fortress_package.contains(" \"bincode-next\","),
        "Fortress 0.12.0 must directly use the maintained codec: {fortress_package}"
    );
    assert!(
        !lockfile.contains("name = \"bincode\"\n"),
        "the native Fortress graph must not restore unmaintained bincode"
    );
    assert!(
        !deny.contains("RUSTSEC-2025-0141"),
        "the native Fortress policy must not restore the obsolete bincode advisory exception"
    );

    assert_eq!(
        extract_toml_version(&manifest, "rust-version"),
        extract_toml_version(&root_manifest, "rust-version"),
        "the standalone Fortress fixture must track the server MSRV"
    );

    assert_workflow_triggers_on_paths(
        &workflow,
        "fortress-interop.yml",
        &[
            "src/**",
            "Cargo.toml",
            "Cargo.lock",
            "rust-toolchain.toml",
            "clients/fortress/**",
            "scripts/run-fortress-interop.sh",
            "scripts/read-toml-string.sh",
            ".github/workflows/fortress-interop.yml",
        ],
    );

    for required in [
        "cargo build --locked --bin signal-fish-server",
        "SERVER_BIN=\"${REPO_ROOT}/target/${PROFILE_DIR}/signal-fish-server\"",
        "SIGNAL_FISH_SERVER_BIN=\"${SERVER_BIN}\" cargo test --locked --all-features",
        "cargo clippy --locked --all-targets --all-features -- -D warnings",
    ] {
        assert!(
            runner.contains(required),
            "Fortress runner must retain current-checkout and warning-free gate: `{required}`"
        );
    }
}

#[test]
fn test_turn_interop_gate_is_local_pinned_and_fail_closed() {
    let root = repo_root();
    let workflow = read_live_file(&root.join(".github/workflows/turn-interop.yml"));
    let runner = read_file(&root.join("scripts/run-turn-interop.sh"));
    let test = read_file(&root.join("clients/native/tests/turn_interop_e2e.rs"));

    assert_workflow_triggers_on_paths(
        &workflow,
        "turn-interop.yml",
        &[
            "src/**",
            "Cargo.toml",
            "Cargo.lock",
            "rust-toolchain.toml",
            "clients/native/**",
            "scripts/run-turn-interop.sh",
            "scripts/read-toml-string.sh",
            ".github/workflows/turn-interop.yml",
        ],
    );

    for required in [
        "permissions:\n  contents: read",
        "timeout-minutes: 25",
        "timeout-minutes: 4",
        "timeout --signal=TERM --kill-after=30s 15m bash scripts/run-turn-interop.sh",
        "if: ${{ always() && !success() }}",
        "actions/upload-artifact@v7.0.1",
        "retention-days: 14",
        "if-no-files-found: error",
    ] {
        assert!(
            workflow.contains(required),
            "TURN workflow is missing required bounded diagnostic contract `{required}`"
        );
    }

    for required in [
        "coturn/coturn:4.12.0-alpine@sha256:faca4aa57efc436916c31546f3867bd1a3fb1077723291bcfba0bf814bcaf48a",
        "network_create_args=(--internal)",
        "--pull=never",
        "BIND_HOST=\"${SF_TURN_INTEROP_BIND_HOST:-127.0.0.1}\"",
        "USE_PRIVATE_NETWORK_ADDRESS=true",
        "NETWORK_SUBNET=\"10.254.${NETWORK_OCTET}.0/24\"",
        "docker_run_args+=(--ip \"${TURN_HOST}\")",
        "--publish \"${BIND_HOST}:${LISTEN_PORT}:${LISTEN_PORT}/udp\"",
        "--publish \"${BIND_HOST}:${RELAY_MIN_PORT}-${RELAY_MAX_PORT}",
        "--use-auth-secret",
        "--allow-loopback-peers",
        "SIGNAL_FISH_TURN_INTEROP_URL=\"${TURN_URL}\"",
        "SIGNAL_FISH_INTEROP_ARTIFACT_DIR=\"${ARTIFACT_DIR}\"",
        "cargo test --locked --offline --test turn_interop_e2e",
        "sanitize_file",
        "redaction-probe",
        "has_unredacted_credentials",
        // The lane must measure its own environment before blaming the client:
        // an unanswered STUN Binding request from the host is the one fact
        // every issue #276 failure was missing, and the host's routing state is
        // unrecoverable from a client log afterwards.
        "capture_host_routing",
        "wait_for_turn_udp_reachable",
        "host-routing.log",
        "diagnostics.manifest",
        "server-*.log",
        "client-*.jsonl",
        "--log-file=stdout",
        "COTURN_RUNNER_PID=$!",
        "docker rm --force \"${COTURN_CONTAINER}\"",
        "docker network rm \"${COTURN_NETWORK}\"",
    ] {
        assert!(
            runner.contains(required),
            "TURN runner is missing required local/pinned/cleanup contract `{required}`"
        );
    }

    for required in [
        "--ice-transport-policy",
        "selected_candidate_pair",
        "local_candidate_type\"), \"relay",
        "remote_candidate_type\"), \"relay",
        "[\"channel_message_sent\", \"channel_message\"]",
        "events_named(events, event_name)",
        "str_field(&payload, \"from\")",
        "str_field(&payload, \"channel\")",
        "payload.get(\"seq\")",
        "--p2p-release-file",
        "std::fs::write(&release_path",
        "p2p_gate_released",
        "pending_pairs",
        "events_named(&client.events, \"p2p_pair_connected\").is_empty()",
        "Allocate error response (error 401:",
        "negative control must not pass through a network outage",
        "game_data_received",
        "mismatched_turn_secret_fails_p2p_and_uses_websocket_fallback",
        "fallback_engaged",
    ] {
        assert!(
            test.contains(required),
            "TURN E2E proof is missing acceptance marker `{required}`"
        );
    }
    assert!(
        runner.contains("TURN_URL=\"turn:${TURN_HOST}:${LISTEN_PORT}?transport=udp\"")
            && !runner.contains("stun:"),
        "TURN proof must use only its loopback/local Docker endpoint, never public STUN/TURN"
    );
    assert!(
        !runner
            .lines()
            .any(|line| line.trim_start().starts_with("docker pull")),
        "TURN execution phase must never contact the image registry"
    );
}

