#[test]
fn test_sequenced_relay_trace_refinement_has_gating_and_production_replays() {
    let root = repo_root();
    let formal = read_live_file(&root.join(".github/workflows/formal-verification.yml"));
    let formal_documents =
        Yaml::load_from_str(&formal).expect("formal verification workflow must parse");
    let formal_steps = formal_documents[0]
        .as_mapping_get("jobs")
        .and_then(|jobs| jobs.as_mapping_get("tlc"))
        .and_then(|job| job.as_mapping_get("steps"))
        .and_then(Yaml::as_sequence)
        .expect("formal TLC steps");
    let gating_run = formal_steps
        .iter()
        .find(|step| {
            step.as_mapping_get("name").and_then(Yaml::as_str)
                == Some("Replay sequenced-relay refinement and seeded divergences")
        })
        .and_then(|step| step.as_mapping_get("run"))
        .and_then(Yaml::as_str)
        .expect("gating sequenced-relay replay command");
    for required in [
        "scripts/run-sequenced-relay-trace-validation.sh",
        "formal/traces/sequenced-relay-replay.jsonl",
    ] {
        assert!(
            gating_run.contains(required),
            "gating sequenced-relay replay lost `{required}`"
        );
    }

    let nightly = read_live_file(&root.join(".github/workflows/verification-nightly.yml"));
    let nightly_documents =
        Yaml::load_from_str(&nightly).expect("verification nightly workflow must parse");
    let trace_job = nightly_documents[0]
        .as_mapping_get("jobs")
        .and_then(|jobs| jobs.as_mapping_get("trace-validation"))
        .expect("nightly trace-validation job");
    let steps = trace_job
        .as_mapping_get("steps")
        .and_then(Yaml::as_sequence)
        .expect("nightly trace-validation steps");
    let named_run = |name: &str| {
        steps
            .iter()
            .find(|step| step.as_mapping_get("name").and_then(Yaml::as_str) == Some(name))
            .and_then(|step| step.as_mapping_get("run"))
            .and_then(Yaml::as_str)
            .unwrap_or_else(|| panic!("missing trace-validation step `{name}`"))
    };
    let classified = named_run("Capture and replay classified sequenced-relay observations");
    for required in [
        "v3_game_data_sequencing_e2e",
        "latest_coalescing_reports_exact_gap_before_successor",
        "generate-sequenced-relay-trace.py",
        "run-tla-model-check.sh",
    ] {
        assert!(
            classified.contains(required),
            "classified production replay lost `{required}`"
        );
    }
    let reconnect = named_run("Capture and replay reconnect sequenced-relay observations");
    for required in [
        "scenario_realworld_e2e",
        "reconnect_under_fire",
        "run-sequenced-relay-trace-validation.sh",
    ] {
        assert!(
            reconnect.contains(required),
            "reconnect production replay lost `{required}`"
        );
    }

    let upload_paths = steps
        .iter()
        .find(|step| {
            step.as_mapping_get("name").and_then(Yaml::as_str)
                == Some("Upload trace-validation evidence")
        })
        .and_then(|step| step.as_mapping_get("with"))
        .and_then(|settings| settings.as_mapping_get("path"))
        .and_then(Yaml::as_str)
        .expect("trace-validation artifact paths");
    for required in [
        "sequenced-classified.jsonl",
        "sequenced-classified-replay",
        "sequenced-reconnect.jsonl",
        "sequenced-reconnect-replay",
    ] {
        assert!(
            upload_paths.contains(required),
            "trace-validation artifacts lost `{required}`"
        );
    }
}

/// Assert both the `push` and `pull_request` events trigger on exactly
/// `required_paths`.
///
/// Parsed, not counted: a substring count of `- "<path>"` cannot tell which key
/// the list sits under, so renaming `paths:` to `paths-ignore:` — which INVERTS
/// the filter and stops the workflow running on precisely the changes it exists
/// to cover — passes a counting check untouched.
fn assert_workflow_triggers_on_paths(workflow: &str, name: &str, required_paths: &[&str]) {
    let documents = Yaml::load_from_str(workflow)
        .unwrap_or_else(|error| panic!("{name} must parse as YAML: {error}"));
    let document = documents.first().expect("a workflow has one document");
    // `on` is a YAML 1.1 boolean keyword; saphyr keeps it a string key here,
    // but accept the boolean spelling too rather than depend on that.
    let triggers = document
        .as_mapping_get("on")
        .or_else(|| document.as_mapping_get("true"))
        .unwrap_or_else(|| panic!("{name} must define workflow triggers"));
    let expected: BTreeSet<&str> = required_paths.iter().copied().collect();
    for event in ["push", "pull_request"] {
        let block = triggers
            .as_mapping_get(event)
            .unwrap_or_else(|| panic!("{name} must define an `{event}` trigger"));
        assert!(
            block.as_mapping_get("paths-ignore").is_none(),
            "{name}: `{event}.paths-ignore` inverts the filter; the gate would stop \
             running on exactly the changes it covers"
        );
        // A branch or event-type filter disables the gate exactly as
        // completely as deleting a path, and just as quietly.
        assert!(
            block.as_mapping_get("branches-ignore").is_none(),
            "{name}: `{event}.branches-ignore` inverts the branch filter"
        );
        let branches: Vec<&str> = block
            .as_mapping_get("branches")
            .and_then(|branches| branches.as_sequence())
            .unwrap_or_else(|| panic!("{name}: `{event}` must scope to a branch"))
            .iter()
            .map(|value| value.as_str().expect("each branch is a string"))
            .collect();
        assert_eq!(
            branches,
            vec!["main"],
            "{name}: `{event}.branches` drifted; narrowing it disables this gate \
             as completely as deleting it"
        );
        if event == "pull_request" {
            assert!(
                block.as_mapping_get("types").is_none(),
                "{name}: a `types:` filter can drop this gate off the default \
                 opened/synchronize/reopened events without touching a path"
            );
        }
        let configured: BTreeSet<&str> = block
            .as_mapping_get("paths")
            .and_then(|paths| paths.as_sequence())
            .unwrap_or_else(|| panic!("{name}: `{event}` must filter on paths"))
            .iter()
            .map(|value| value.as_str().expect("each trigger path is a string"))
            .collect();
        assert_eq!(
            configured, expected,
            "{name}: `{event}.paths` drifted; dropping one path silently disables \
             this gate for changes that only touch it"
        );
    }
}

/// Records whether a syntax subtree calls a function whose path ends in
/// `name`. Walking the tree means comments and strings cannot match.
struct CallFinder<'a> {
    name: &'a str,
    found: bool,
}

impl<'ast> Visit<'ast> for CallFinder<'_> {
    fn visit_expr_call(&mut self, call: &'ast syn::ExprCall) {
        if let syn::Expr::Path(path) = call.func.as_ref() {
            if path
                .path
                .segments
                .last()
                .is_some_and(|segment| segment.ident == self.name)
            {
                self.found = true;
            }
        }
        syn::visit::visit_expr_call(self, call);
    }
}

/// Statement index of the first statement whose subtree calls `name`.
fn position_of(body: &syn::Block, name: &str) -> Option<usize> {
    body.stmts.iter().position(|statement| {
        let mut finder = CallFinder { name, found: false };
        finder.visit_stmt(statement);
        finder.found
    })
}

/// Like [`position_of`], but only accepts a statement of the exact shape
/// `<expr containing the call>?;` — an expression statement whose value is a
/// `?` propagation. `let _ = call();` (a `Stmt::Local`) and
/// `if cond { call()?; }` (a `Stmt::Expr(Expr::If, _)`) are rejected, because
/// both keep the call in place while discarding or skipping its failure.
fn position_of_propagating(body: &syn::Block, name: &str) -> Option<usize> {
    body.stmts.iter().position(|statement| {
        let syn::Stmt::Expr(syn::Expr::Try(propagated), Some(_semicolon)) = statement else {
            return false;
        };
        let mut finder = CallFinder { name, found: false };
        finder.visit_expr(&propagated.expr);
        finder.found
    })
}

/// The client must resolve an explicitly requested address family BEFORE it
/// opens its WebSocket; otherwise the process creates or joins a room it could
/// never have used, and the per-pair failure it would hit instead is non-fatal
/// (issue #271 review).
///
/// This walks the syntax tree rather than comparing source offsets: a textual
/// check is satisfied by a helper function *defined* above `run_inner` and
/// *called* after the handshake, which is exactly the defect it exists to
/// forbid.
fn assert_ip_family_preflight_precedes_the_socket(root: &Path) {
    let source = read_file(&root.join("clients/native/src/client.rs"));
    let file = syn::parse_file(&source).expect("client.rs must parse as Rust");

    let run_inner = file
        .items
        .iter()
        .find_map(|item| match item {
            syn::Item::Fn(function) if function.sig.ident == "run_inner" => Some(function),
            _ => None,
        })
        .expect("client.rs must define run_inner");

    // Position alone is not the property. `let _ = preflight(..);` and
    // `if flag { preflight(..)?; }` both keep the call at statement 0 while
    // discarding or skipping it, and clippy accepts both. Require the
    // statement to BE `<expr>?;` at the top level of `run_inner`, so the
    // failure necessarily propagates out of the function.
    let preflight = position_of_propagating(&run_inner.block, "preflight_ip_family").expect(
        "run_inner must call engine::preflight_ip_family as a top-level `?` \
         statement, so an unservable --ip-family aborts the run",
    );
    let connect = position_of(&run_inner.block, "connect")
        .expect("run_inner must open the WebSocket with wire::connect");
    assert!(
        preflight < connect,
        "preflight_ip_family must run before wire::connect, so an unservable \
         --ip-family fails without creating or joining a room"
    );

    // One call site: the check cannot be satisfied by a second, later call
    // while the effective path skips it.
    let call_sites = source.matches("preflight_ip_family(").count();
    assert_eq!(
        call_sites, 1,
        "client.rs must call the pre-flight exactly once; found {call_sites}"
    );

    // ...applying the engine's real bind selection. The pre-flight takes its
    // resolver as an argument precisely so the unit-tested function IS the
    // production one; what remains to pin is that this call site passes the
    // real rule. It must be the EXACT qualified path: a closure such as
    // `|s| Ok(engine::local_udp_addrs(s).unwrap_or_default())` mentions the
    // rule while swallowing its failure, and a bare `local_udp_addrs` can be a
    // local stand-in shadowing it — both compile clean under
    // `clippy -D warnings`.
    let arguments = preflight_arguments(&run_inner.block.stmts[preflight])
        .expect("the pre-flight call must pass its arguments");

    // The settings argument carries the requested family. A constant such as
    // `EngineSettings::default()` is `IpFamily::Any`, for which the pre-flight
    // returns before it ever consults the resolver — a permanent no-op that no
    // live cell can catch, since the failure needs a family the host lacks.
    let settings = arguments
        .first()
        .expect("the pre-flight takes the invocation's settings");
    let syn::Expr::MethodCall(settings) = settings else {
        panic!(
            "the pre-flight must be handed THIS invocation's settings \
             (`cli.engine_settings()`), not a constant"
        );
    };
    assert_eq!(
        settings.method, "engine_settings",
        "the pre-flight must resolve the family this invocation asked for"
    );

    // The resolver must be the engine's own rule, spelled from the crate root
    // so that neither a local definition nor a re-imported `engine` alias can
    // stand in for it.
    let resolver = arguments
        .get(1)
        .expect("the pre-flight takes a resolver argument");
    let syn::Expr::Path(path) = resolver else {
        panic!(
            "the pre-flight's resolver must be the path \
             `crate::engine::local_udp_addrs`, not a closure or adapter that \
             can swallow its failure"
        );
    };
    let segments: Vec<String> = path
        .path
        .segments
        .iter()
        .map(|segment| segment.ident.to_string())
        .collect();
    assert_eq!(
        segments,
        vec![
            "crate".to_string(),
            "engine".to_string(),
            "local_udp_addrs".to_string()
        ],
        "the pre-flight must use the engine's own bind selection, spelled from \
         the crate root so no alias or local definition can shadow it"
    );
}

/// The arguments of the `preflight_ip_family` call inside `statement`.
fn preflight_arguments(statement: &syn::Stmt) -> Option<Vec<&syn::Expr>> {
    struct Finder<'ast> {
        arguments: Option<Vec<&'ast syn::Expr>>,
    }

    impl<'ast> Visit<'ast> for Finder<'ast> {
        fn visit_expr_call(&mut self, call: &'ast syn::ExprCall) {
            if let syn::Expr::Path(path) = call.func.as_ref() {
                if path
                    .path
                    .segments
                    .last()
                    .is_some_and(|segment| segment.ident == "preflight_ip_family")
                {
                    self.arguments = Some(call.args.iter().collect());
                }
            }
            syn::visit::visit_expr_call(self, call);
        }
    }

    let mut finder = Finder { arguments: None };
    finder.visit_stmt(statement);
    finder.arguments
}

/// A job or step must propagate its failure: `continue-on-error` is either
/// absent or the literal boolean `false`. A string (`"true"`) or an expression
/// (`${{ true }}`) is truthy to GitHub but not to `as_bool`, so treating a
/// non-boolean as "false" would let a swallowed failure through.
fn assert_failure_is_not_swallowed(node: &Yaml, what: &str) {
    let Some(value) = node.as_mapping_get("continue-on-error") else {
        return;
    };
    assert_eq!(
        value.as_bool(),
        Some(false),
        "{what} must fail its workflow, not report success; `continue-on-error` \
         must be absent or literally false"
    );
}

/// The native reference client is a standalone crate that no other lane
/// compiles: the root CI matrix builds only the root package, and the interop
/// cells historically ran only on Linux. Issues #271 and #275 added proofs that
/// must not silently disappear — a Windows/macOS compile + unit matrix, a live
/// two-peer data-channel smoke on every desktop platform, and one live IPv6
/// cell that fails loudly instead of skipping when the runner cannot serve IPv6.
///
/// Both source files are read with `read_live_file`, so a marker satisfied only
/// by a comment or a commented-out line does not count as coverage.
#[test]
fn test_native_client_platform_matrix_live_smoke_and_ipv6_proof_are_pinned() {
    let root = repo_root();
    let workflow = read_live_file(&root.join(".github/workflows/webrtc-interop.yml"));
    let interop = read_live_file(&root.join("clients/native/tests/interop_e2e.rs"));
    let cli = read_live_file(&root.join("clients/native/src/cli.rs"));

    assert_workflow_triggers_on_paths(
        &workflow,
        "webrtc-interop.yml",
        &[
            "src/**",
            "Cargo.toml",
            "Cargo.lock",
            "rust-toolchain.toml",
            "clients/native/**",
            "scripts/run-webrtc-interop.sh",
            "scripts/read-toml-string.sh",
            ".github/workflows/webrtc-interop.yml",
        ],
    );

    // Parse the jobs rather than substring-match them: `contains` cannot see an
    // `if: false` that disables a whole job, a `continue-on-error: true` that
    // swallows its result, or a `|| true` appended to a pinned command.
    let documents = Yaml::load_from_str(&workflow).expect("webrtc-interop.yml must parse as YAML");

    // The job that RUNS the live proofs (including the IPv6 cell) needs the
    // same treatment as the matrix: an `if: false` on it deletes every
    // live-transport proof this test pins, with every command untouched.
    let interop_job = documents
        .first()
        .and_then(|document| document.as_mapping_get("jobs"))
        .and_then(|jobs| jobs.as_mapping_get("interop"))
        .expect("webrtc-interop.yml must define the interop job");
    assert!(
        interop_job.as_mapping_get("if").is_none(),
        "the interop job must not be conditional; the IPv6 cell and every other \
         live-transport cell run only there"
    );
    assert!(
        interop_job.as_mapping_get("needs").is_none(),
        "the interop job must not depend on another job: a skipped dependency \
         skips it, and a workflow whose jobs all skip still concludes success"
    );
    assert_eq!(
        interop_job.as_mapping_get("runs-on").and_then(Yaml::as_str),
        Some("ubuntu-latest"),
        "the live-transport proof runs on Linux; the README platform table and \
         the CHANGELOG both say so"
    );
    assert_failure_is_not_swallowed(interop_job, "the interop job");
    let interop_steps: Vec<&Yaml> = interop_job
        .as_mapping_get("steps")
        .and_then(|steps| steps.as_sequence())
        .expect("the interop job must define steps")
        .iter()
        .collect();
    for step in &interop_steps {
        assert_failure_is_not_swallowed(step, "every interop step");
        assert!(
            step.as_mapping_get("if").is_none(),
            "no step in the interop job may be conditional"
        );
    }
    assert!(
        interop_steps.iter().any(|step| {
            step.as_mapping_get("run")
                .and_then(Yaml::as_str)
                .is_some_and(|run| run.trim() == "bash scripts/run-webrtc-interop.sh")
        }),
        "the interop job must still run the suite via scripts/run-webrtc-interop.sh"
    );
    // ...and that script must still run the WHOLE suite. A token blocklist is
    // not enough — `--test=interop_e2e`, `-- --skip ipv6_only`, `-p`, and an
    // added earlier `cargo test` line all narrow it past such a list — so pin
    // the invocation exactly, and pin that there is only one of them.
    let runner = read_live_file(&root.join("scripts/run-webrtc-interop.sh"));
    let suite_commands: Vec<&str> = runner
        .lines()
        .map(str::trim)
        .filter(|line| line.contains("cargo test"))
        .collect();
    assert_eq!(
        suite_commands,
        vec![
            r#"SIGNAL_FISH_SERVER_BIN="${SERVER_BIN}" cargo test --locked "${CARGO_PROFILE_ARGS[@]+"${CARGO_PROFILE_ARGS[@]}"}""#
        ],
        "the interop runner must run the WHOLE client suite as exactly one \
         unnarrowed `cargo test`; any narrowing silently drops the \
         multi-process cells, including the IPv6 proof"
    );
    // That pinned line expands an array, so pin the array too: `(--lib)` on an
    // existing assignment is the cheapest way to narrow the suite while the
    // command itself stays byte-identical.
    let profile_assignments: Vec<&str> = runner
        .lines()
        .map(str::trim)
        .filter(|line| line.starts_with("CARGO_PROFILE_ARGS"))
        .collect();
    assert_eq!(
        profile_assignments,
        vec!["CARGO_PROFILE_ARGS=()", "CARGO_PROFILE_ARGS=(--release)"],
        "the interop runner's profile arguments must select a profile and \
         nothing else"
    );

    let job = documents
        .first()
        .and_then(|document| document.as_mapping_get("jobs"))
        .and_then(|jobs| jobs.as_mapping_get("native-platforms"))
        .expect("webrtc-interop.yml must define the native-platforms job (issue #271)");
    assert!(
        job.as_mapping_get("if").is_none(),
        "the native platform matrix must not be conditional; an `if:` can disable \
         every non-Linux proof without touching a single command"
    );
    assert!(
        job.as_mapping_get("needs").is_none(),
        "the platform proof must not be gated on another job's result: `needs:` \
         skips this matrix whenever that job fails, which is the same outcome \
         `fail-fast: false` exists to prevent"
    );
    // `runs-on` is the whole point: pointing it at ubuntu-latest keeps every
    // command and both matrix legs while deleting the non-Linux proof entirely.
    assert_eq!(
        job.as_mapping_get("runs-on").and_then(Yaml::as_str),
        Some(MATRIX_OS_PLACEHOLDER),
        "each matrix leg must run on its own platform"
    );
    // Absent, or the literal boolean false. A string "true" or an expression
    // is truthy to GitHub but not to `as_bool`, so anything else is rejected.
    assert_failure_is_not_swallowed(job, "the native-platforms job");
    let strategy = job
        .as_mapping_get("strategy")
        .expect("the native platform job must define a strategy");
    assert_eq!(
        strategy.as_mapping_get("fail-fast").and_then(Yaml::as_bool),
        Some(false),
        "one red platform must not cancel the other platform's evidence"
    );
    let matrix = strategy
        .as_mapping_get("matrix")
        .expect("the native platform job must define a strategy matrix");
    for filter in ["include", "exclude"] {
        assert!(
            matrix.as_mapping_get(filter).is_none(),
            "`strategy.matrix.{filter}` can silently remove every leg while the \
             `os` list still reads as complete"
        );
    }
    let platforms: Vec<&str> = matrix
        .as_mapping_get("os")
        .and_then(|os| os.as_sequence())
        .expect("the native platform job must define strategy.matrix.os")
        .iter()
        .map(|value| value.as_str().expect("each matrix os is a string"))
        .collect();
    assert_eq!(
        platforms,
        vec!["windows-latest", "macos-latest"],
        "the platforms clients/native is proved on must not shrink; Linux is the \
         separate `interop` job, which runs the full live suite"
    );

    // Exact `run` values: a trailing `|| true` (or any other suffix) would keep
    // a `contains` check green while discarding the command's exit status.
    let steps: Vec<&Yaml> = job
        .as_mapping_get("steps")
        .and_then(|steps| steps.as_sequence())
        .expect("the native platform job must define steps")
        .iter()
        .collect();
    // Every pinned command must run unconditionally, against the standalone
    // crate, with its failure propagated. Checking these per step closes the
    // gap a whole-file `contains` leaves: a step that keeps its command but
    // loses `working-directory` silently checks the ROOT package instead.
    for step in &steps {
        assert_failure_is_not_swallowed(step, "every native-platforms step");
        assert!(
            step.as_mapping_get("if").is_none(),
            "no step in the native platform matrix may be conditional"
        );
    }
    let crate_commands: Vec<&str> = steps
        .iter()
        .filter(|step| {
            step.as_mapping_get("working-directory")
                .and_then(Yaml::as_str)
                == Some("clients/native")
        })
        .filter_map(|step| step.as_mapping_get("run").and_then(Yaml::as_str))
        .map(str::trim)
        .collect();
    for required in [
        "cargo metadata --locked --format-version 1 > /dev/null",
        "cargo fmt --check",
        "cargo clippy --locked --all-targets -- -D warnings",
        // Clippy never links the integration cells; this is what proves they
        // build on the platform.
        "cargo test --locked --all-targets --no-run",
        "cargo test --locked --lib --bins",
    ] {
        assert!(
            crate_commands.contains(&required),
            "the native platform matrix lost the exact command `{required}` \
             running in clients/native; commands present: {crate_commands:?} \
             (issue #271)"
        );
    }

    let server_build = steps
        .iter()
        .find(|step| {
            step.as_mapping_get("name").and_then(Yaml::as_str)
                == Some("Build the signaling server for live transport")
        })
        .expect("the non-Linux matrix must build the real signaling server");
    assert!(
        server_build.as_mapping_get("working-directory").is_none(),
        "the signaling server must be built from the root package"
    );
    assert_eq!(
        server_build.as_mapping_get("run").and_then(Yaml::as_str),
        Some("cargo build --locked --bin signal-fish-server"),
        "the live smoke must build the exact locked server binary"
    );

    let live_smoke = steps
        .iter()
        .find(|step| {
            step.as_mapping_get("name").and_then(Yaml::as_str)
                == Some("Run two-peer live WebRTC transport")
        })
        .expect("the Windows/macOS matrix must run a live WebRTC cell (issue #275)");
    assert_eq!(
        live_smoke
            .as_mapping_get("working-directory")
            .and_then(Yaml::as_str),
        Some("clients/native"),
        "the live smoke selector belongs to the standalone native-client crate"
    );
    assert_eq!(
        live_smoke.as_mapping_get("shell").and_then(Yaml::as_str),
        Some("bash"),
        "the Windows/macOS live smoke uses Bash syntax and must explicitly run in Bash"
    );
    assert_failure_is_not_swallowed(live_smoke, "the native-platforms live smoke step");
    let live_run = live_smoke
        .as_mapping_get("run")
        .and_then(Yaml::as_str)
        .expect("the live smoke step must contain a command");
    assert_eq!(
        live_run.trim_end(),
        r#"SERVER_SUFFIX=""
if [ "$RUNNER_OS" = "Windows" ]; then
  SERVER_SUFFIX=".exe"
fi
SIGNAL_FISH_SERVER_BIN="$GITHUB_WORKSPACE/target/debug/signal-fish-server${SERVER_SUFFIX}" \
  cargo test --locked --test interop_e2e \
    two_peer_mesh_exchanges_over_live_webrtc -- --exact --nocapture"#,
        "the non-Linux live smoke must keep the exact Windows suffix handling, \
         server handoff, selector, and failure-propagating command; extra flags \
         can silently select zero tests"
    );
    assert!(
        workflow.contains("name: Native Client Build + Live WebRTC (${{ matrix.os }})"),
        "the per-platform check name is what a reader (and any future branch \
         protection rule) identifies this proof by"
    );

    for required in [
        "async fn two_peer_mesh_exchanges_over_live_webrtc()",
        r#"let run = run_two_peer_mesh("interop-cross-platform-smoke", &[]).await;"#,
        "let failure_context = run.selected_pair_failure_context(index);",
        "assert_baseline_direct_path(",
        "run.window(1 - index)",
        r#"matches!(remote_type, "host" | "prflx")"#,
        r#"[("local", events), ("peer", peer_events)]"#,
        "assert_exchange_sent_to(&run.logs[index], who, &peers);",
        "assert_exchange_received_from(&run.logs[index], who, &peers);",
        "assert_transport_status_true(&run.logs[index], who);",
    ] {
        assert!(
            interop.contains(required),
            "the cross-platform live WebRTC proof lost acceptance marker `{required}`"
        );
    }

    assert_ip_family_preflight_precedes_the_socket(&root);

    // Structural facts, not loose tokens: each of these is a line the proof
    // cannot lose while still proving anything.
    for required in [
        // The clients really run IPv6-only, and the args really reach them.
        r#"const IPV6_ARGS: [&str; 2] = ["--ip-family", "ipv6"];"#,
        r#"run_two_peer_mesh("interop-ipv6", &IPV6_ARGS).await"#,
        // The precondition applies the client's own rule and never skips.
        "fn require_ipv6_ice_interface()",
        "require_ipv6_ice_interface();",
        "local_udp_addrs(settings).unwrap_or_else",
        "The lane must not be skipped silently.",
        // The path is asserted to be direct IPv6 toward the planned peer.
        "fn assert_ipv6_host_path(",
        "assert_ipv6_host_path(window, who, peer_id, &failure_context);",
        "fn selected_ip_address(event: &Value, field: &str, who: &str, failure_context: &str) -> IpAddr {",
        "let IpAddr::V6(address) = address else {",
        "selected_pair_is_exact_host_host(selected)",
        r#"selected_ip_address(selected, "local_candidate_address", who, failure_context)"#,
        // ...carrying a real session on both labels, not the relay floor.
        "assert_exchange_sent_to(&run.logs[index], who, &peers);",
        "assert_exchange_received_from(&run.logs[index], who, &peers);",
        "assert_pair_connected_exactly(window, who, &peers);",
        r#"events_named(&run.logs[index][..live_end], "fallback_engaged").is_empty(),"#,
    ] {
        assert!(
            interop.contains(required),
            "the IPv6 interop proof lost acceptance marker `{required}`"
        );
    }
    // Absence checks must NOT read the stripped view: `read_live_file` drops
    // every line starting with `#`, which includes Rust attributes, so
    // `!live.contains("#[ignore]")` would pass even with every cell ignored.
    // Read the raw file and match only a real attribute line, so a commented
    // `// #[ignore]` cannot false-positive either.
    let interop_raw = read_file(&root.join("clients/native/tests/interop_e2e.rs"));
    assert!(
        !interop_raw
            .lines()
            .any(|line| line.trim_start().starts_with("#[ignore")),
        "the interop cells must never become opt-in; that would silently drop \
         every live-transport proof in this file"
    );
    assert!(
        cli.contains("pub ip_family: IpFamily"),
        "the client must keep the --ip-family selector the IPv6 proof drives"
    );
}

/// The engine's per-pair bind set must be the routing-aware union, applied to
/// this session's real ICE servers (issue #276).
///
/// Every part of this is defeatable by an edit that keeps the call in place.
/// `session_udp_addrs(self.settings, local_udp_addrs, Vec::new())` compiles,
/// passes `clippy -D warnings`, and passes every live cell on a host whose
/// interface table already contains the route — which is most of them, and
/// exactly why the original defect was intermittent. So the arguments, not the
/// call, are what this pins.
fn assert_ice_bind_set_is_routing_aware(root: &Path) {
    let source = read_file(&root.join("clients/native/src/engine.rs"));
    let file = syn::parse_file(&source).expect("engine.rs must parse as Rust");

    // Exactly one production call site. A second one cannot satisfy this while
    // the effective path skips it, and the unit tests below `mod tests` call
    // the same function with fixtures, so counting the raw text would not see
    // the difference.
    let mut call_sites = production_call_arguments(&file, "session_udp_addrs");
    assert_eq!(
        call_sites.len(),
        1,
        "exactly one production call site must build the bind set through \
         engine::session_udp_addrs; found {}",
        call_sites.len()
    );
    let arguments = call_sites.remove(0);
    assert_eq!(
        arguments.len(),
        3,
        "the bind set takes the settings, the interface rule and the routing answers"
    );

    // The settings must be this engine's own, not a constant: `--cripple-ice`
    // and `--ip-family` both read from them, and `EngineSettings::default()`
    // would quietly re-enable both.
    let syn::Expr::Field(settings) = arguments[0] else {
        panic!("the bind set must be built from `self.settings`, not a constant")
    };
    let syn::Member::Named(field) = &settings.member else {
        panic!("the bind set must be built from `self.settings`")
    };
    assert_eq!(
        field, "settings",
        "the bind set reads this engine's settings"
    );

    // The interface rule must be the engine's own function, passed by path. A
    // closure could swallow its failure or substitute a fixture.
    let syn::Expr::Path(enumerate) = arguments[1] else {
        panic!(
            "the interface rule must be the path `local_udp_addrs`, not a \
             closure or adapter that can swallow its failure"
        )
    };
    assert!(
        enumerate.path.is_ident("local_udp_addrs"),
        "the interface rule must be `local_udp_addrs`, got {:?}",
        enumerate.path.segments.last().map(|s| s.ident.to_string())
    );

    // The routing answers must come from THIS pairing's servers. An empty
    // literal restores the pre-#276 behaviour with the call still in place.
    let syn::Expr::Await(awaited) = arguments[2] else {
        panic!(
            "the routing answers must be `self.ice_route_sources(..).await`; a \
             literal or a constant makes the union a permanent no-op"
        )
    };
    let syn::Expr::MethodCall(probe) = awaited.base.as_ref() else {
        panic!("the routing answers must come from `self.ice_route_sources(..)`")
    };
    assert_eq!(
        probe.method, "ice_route_sources",
        "the routing answers must come from `self.ice_route_sources(..)`"
    );
    let probe_argument = probe
        .args
        .first()
        .expect("the probe takes the session's ICE servers");
    let syn::Expr::Path(servers) = probe_argument else {
        panic!(
            "the probe must be handed `ice_servers` — this pairing's real \
             servers — not a literal or a constructed list"
        )
    };
    assert!(
        servers.path.is_ident("ice_servers"),
        "the probe must be handed this pairing's `ice_servers`"
    );

    // ...and that memo must be a memo of the real probe. Returning a cached
    // constant, or dropping the probe entirely, is invisible to every live cell
    // on a host whose interface table already contains the route.
    let memo = production_call_arguments(&file, "ice_server_source_addrs");
    assert_eq!(
        memo.len(),
        1,
        "`ice_route_sources` must resolve through exactly one call to \
         `ice_server_source_addrs`; found {}",
        memo.len()
    );
    assert!(
        source.contains("let endpoints = ice_server_endpoints(ice_servers);"),
        "the memo must key on the endpoints of THIS pairing's servers, so a \
         replan that changes servers re-probes"
    );
}

/// Arguments of every call to `name` in `file`'s production items — that is,
/// excluding the `mod tests` unit-test module, whose fixture calls would
/// otherwise be indistinguishable from the shipped one.
fn production_call_arguments<'ast>(file: &'ast syn::File, name: &str) -> Vec<Vec<&'ast syn::Expr>> {
    struct Finder<'ast, 'a> {
        name: &'a str,
        calls: Vec<Vec<&'ast syn::Expr>>,
    }

    impl<'ast> Visit<'ast> for Finder<'ast, '_> {
        fn visit_expr_call(&mut self, call: &'ast syn::ExprCall) {
            if let syn::Expr::Path(path) = call.func.as_ref() {
                if path
                    .path
                    .segments
                    .last()
                    .is_some_and(|segment| segment.ident == self.name)
                {
                    self.calls.push(call.args.iter().collect());
                }
            }
            syn::visit::visit_expr_call(self, call);
        }
    }

    let mut finder = Finder {
        name,
        calls: Vec::new(),
    };
    for item in &file.items {
        let is_test_module = matches!(item, syn::Item::Mod(module) if module.ident == "tests");
        if !is_test_module {
            finder.visit_item(item);
        }
    }
    finder.calls
}

/// The routing-aware ICE bind set and the advertised-candidate oracles that
/// make a failed gathering self-describing (issues #275, #276).
#[test]
fn test_ice_bind_set_and_advertised_candidate_oracles_are_pinned() {
    let root = repo_root();
    assert_ice_bind_set_is_routing_aware(&root);

    // Each of these is a line the proof cannot lose while still proving
    // anything.
    let turn = read_live_file(&root.join("clients/native/tests/turn_interop_e2e.rs"));
    for required in [
        "fn assert_only_relay_candidates_advertised(events: &[Value], who: &str) {",
        "assert_only_relay_candidates_advertised(events, who);",
        r#"advertised.iter().all(|entry| entry.starts_with("relay ")),"#,
        // The negative control's complement: a rejected allocation advertises
        // nothing, so "no pair" cannot be reported while a path existed.
        "advertised_candidates(events).is_empty(),",
    ] {
        assert!(
            turn.contains(required),
            "the TURN relay-candidate oracle lost marker `{required}` (issue #276)"
        );
    }

    let interop = read_live_file(&root.join("clients/native/tests/interop_e2e.rs"));
    for required in [
        "fn assert_no_ipv4_candidate_advertised(events: &[Value], who: &str) {",
        "assert_no_ipv4_candidate_advertised(window, who);",
        "advertised_candidate_addresses(events, who);",
    ] {
        assert!(
            interop.contains(required),
            "the IPv6 advertised-candidate oracle lost marker `{required}` (issue #275)"
        );
    }

    // The event those oracles read must still be emitted, and emitted only
    // after the candidate was actually relayed to the peer.
    let client = read_live_file(&root.join("clients/native/src/client.rs"));
    let relay = client
        .find("json!({ \"IceCandidate\": candidate_json }),")
        .expect("client.rs must relay gathered candidates as IceCandidate signals");
    let emit = client
        .find("emit(&Event::LocalCandidate {")
        .expect("client.rs must report every advertised candidate on the event stream");
    assert!(
        relay < emit,
        "`local_candidate` must be emitted after the relay succeeds; reporting a \
         candidate the peer never received would make the oracles read a set \
         that does not exist"
    );
}

#[test]
fn test_fortress_wasm_interop_gate_is_exact_single_threaded_and_fail_closed() {
    let root = repo_root();
    let manifest = read_live_file(&root.join("clients/fortress-wasm/Cargo.toml"));
    let lockfile = read_file(&root.join("clients/fortress-wasm/Cargo.lock"));
    let source = read_file(&root.join("clients/fortress-wasm/src/lib.rs"));
    let harness = read_file(&root.join("clients/fortress-wasm/harness.mjs"));
    let project = read_file(&root.join("clients/fortress-wasm/project/export_presets.cfg"));
    let bridge = read_file(&root.join("clients/fortress-wasm/project/main.gd"));
    let runner = read_file(&root.join("scripts/run-fortress-wasm-interop.sh"));
    let deny = read_file(&root.join("clients/fortress-wasm/deny.toml"));
    let workflow = read_live_file(&root.join(".github/workflows/fortress-wasm-interop.yml"));

    for dependency in [
        "fortress-rollback = \"=0.12.0\"",
        "signal-fish-client = { version = \"=0.9.0\", default-features = false, features = [\"polling-client\"] }",
        "signal-fish-client-godot = \"=0.9.0\"",
        "godot = { version = \"=0.4.5\", features = [\"api-custom\", \"experimental-wasm\", \"experimental-wasm-nothreads\", \"lazy-function-tables\"] }",
    ] {
        assert!(
            manifest.contains(dependency),
            "Fortress WASM fixture must retain exact released/no-thread dependency `{dependency}`"
        );
    }
    assert_eq!(
        extract_toml_version(&manifest, "rust-version"),
        Some("1.94.0".to_owned())
    );
    for (name, version) in [
        ("fortress-rollback", "0.12.0"),
        ("bincode-next", "2.1.0"),
        ("signal-fish-client", "0.9.0"),
        ("signal-fish-client-godot", "0.9.0"),
        ("godot", "0.4.5"),
    ] {
        let package = cargo_lock_package(&lockfile, name, version);
        assert!(
            package.contains("source = \"registry+https://github.com/rust-lang/crates.io-index\""),
            "P13 production dependencies must resolve from crates.io without path/Git overrides: {package}"
        );
    }
    assert_eq!(
        lockfile.matches("name = \"godot\"\n").count(),
        1,
        "the WASM fixture must resolve exactly one godot-rust release so the adapter and fixture cannot link incompatible engine bindings"
    );
    let fortress_package = cargo_lock_package(&lockfile, "fortress-rollback", "0.12.0");
    let fixture_package =
        cargo_lock_package(&lockfile, "signal-fish-fortress-wasm-interop", "0.1.0");
    assert!(
        fixture_package.contains(" \"fortress-rollback\","),
        "the WASM fixture must directly lock Fortress Rollback: {fixture_package}"
    );
    assert_eq!(
        lockfile.matches("name = \"fortress-rollback\"\n").count(),
        1,
        "the WASM fixture must resolve exactly one Fortress Rollback release"
    );
    assert!(
        fortress_package.contains(" \"bincode-next\","),
        "Fortress 0.12.0 must directly use the maintained codec: {fortress_package}"
    );
    assert!(
        !lockfile.contains("name = \"bincode\"\n"),
        "the Fortress WASM graph must not restore unmaintained bincode"
    );
    assert!(
        !deny.contains("RUSTSEC-2025-0141"),
        "the Fortress WASM policy must not restore the obsolete bincode advisory exception"
    );

    assert!(project.contains("variant/thread_support=false"));
    assert!(project.contains("variant/extensions_support=true"));
    assert!(!source.contains("transport-websocket-emscripten"));
    for required in [
        "impl INode for FortressWasmPeer",
        "fn process(&mut self, _delta: f64)",
        "let events = self.client.poll();",
        "self.poll_count = self.poll_count.saturating_add(1)",
        "#[path = \"../../fortress/src/relay.rs\"]",
        "#[path = \"../../fortress/src/workload.rs\"]",
        "RunMode::NegativeOneAdmissionPerCallback => 1",
        "const RUNTIME_DEADLINE: Duration = Duration::from_secs(90);",
        "const NEGATIVE_ACTIVE_CALLBACK_BUDGET: u64 = MIN_ACTIVE_CALLBACKS;",
        "self.active_callback_count >= NEGATIVE_ACTIVE_CALLBACK_BUDGET",
        "self.completed || self.report_json.is_some()",
        "self.running_finished_at.get_or_insert_with(Instant::now);",
        "config.godot_runtime.string != \"4.5-stable (official)\"",
        "godot_runtime: self.config.godot_runtime.clone()",
        "configure_identity",
        "enqueue_target_reached",
        "enqueue_completion",
        "enqueue_creator_final",
        "enqueue_joiner_ack",
        "relay_sent_sequence_hash",
        "relay_received_sequence_hash",
        "use signal_fish_client_godot::GodotWebSocketTransport;",
        "const SIGNAL_FISH_CLIENT_GODOT_VERSION: &str = \"0.9.0\";",
        "const FORTRESS_ROLLBACK_VERSION: &str = \"0.12.0\";",
        "signal_fish_client_godot_version: SIGNAL_FISH_CLIENT_GODOT_VERSION",
        "const REPORT_SCHEMA_VERSION: u32 = 3;",
        "const MAX_STALL_COUNT: u64 = 1;",
        "max_stall_count: MAX_STALL_COUNT,",
    ] {
        assert!(
            source.contains(required),
            "P13 Rust gate is missing `{required}`"
        );
    }
    assert!(
        !bridge.contains(".poll(") && !bridge.contains("advance_frame"),
        "GDScript must remain a report/config bridge and never advance networking or Fortress"
    );
    for required in [
        "Engine.get_version_info()",
        "RenderingServer.set_render_loop_enabled(false)",
        "Engine.max_fps = 60",
        "\"schema_version\": 3,",
        "config[\"schema_version\"] = int(",
        "config[\"browser_process_id\"] = int(",
        "config[\"godot_runtime\"]",
        "peer.configure(JSON.stringify(config))",
    ] {
        assert!(
            bridge.contains(required),
            "P13 GDScript bridge is missing runtime identity injection `{required}`"
        );
    }

    for required in [
        "browserType.launchServer",
        "\"--disable-frame-rate-limit\"",
        "\"--disable-gpu-vsync\"",
        "creatorReport.browser_process_id !== joinerReport.browser_process_id",
        "crossOriginIsolated === false",
        "sharedArrayBufferType === \"undefined\"",
        "workerConstructions === 0",
        "report.callback_count === report.poll_count",
        "room.schema_version === 3",
        "schema_version: 3,",
        "report.schema_version === 3",
        "report.signal_fish_client_godot_version === \"0.9.0\"",
        "report.fortress_rollback_version === \"0.12.0\"",
        "report.godot_runtime.string === \"4.5-stable (official)\"",
        "assertExactKeys(report, reportKeys",
        "report.relay_send_retries <= 8",
        "report.client_game_data_sent_during_run * 1_000",
        "await persistPeerArtifacts(joiner, joinerReport)",
        "pageSnapshot = await Promise.race([snapshotPromise, snapshotTimeout])",
        "page snapshot timed out`)),\n          1_000",
        "-browser-errors.log",
        "-partial-report.json",
        "relay_sent_sequence_hash === joinerReport.relay_received_sequence_hash",
        "joinerReport.relay_sent_first_sequence === creatorReport.relay_received_first_sequence",
        "joinerReport.relay_sent_last_sequence === creatorReport.relay_received_last_sequence",
        "const healthyViolations = peerHealth.flatMap",
        "max_stall_count: 1,",
        "stallCountWithinThreshold(report)",
        "runHealthGateSelfTests();",
        "BUSTED fortress-wasm expected negative control",
        "HEALTHY fortress-wasm released-client interoperability",
    ] {
        assert!(
            harness.contains(required),
            "P13 browser harness is missing `{required}`"
        );
    }
    let released_start = harness
        .find("if (mode === \"released\") {")
        .expect("P13 harness must define released characterization");
    let negative_start = harness[released_start..]
        .find("  } else {")
        .map(|offset| released_start + offset)
        .expect("P13 harness must define negative characterization");
    let negative_end = harness[negative_start..]
        .find("\n  }\n} catch (error)")
        .map(|offset| negative_start + offset)
        .expect("P13 harness must bound negative characterization");
    let released_classification = &harness[released_start..negative_start];
    let negative_classification = &harness[negative_start..negative_end];
    for required in [
        "report.max_admissions_per_callback > 1",
        "report.callback_intervals.mean_us >= 8_000",
        "violations.length === 0",
        "released graph failed P13 healthy gates",
    ] {
        assert!(
            released_classification.contains(required),
            "P13 released classifier is missing `{required}`"
        );
    }
    assert!(
        !released_classification.contains("violations.every")
            && !released_classification.contains("completion bottleneck"),
        "P13 released classifier must require health instead of accepting the old bottleneck"
    );
    let forbidden_start = harness
        .find("const forbidden = [")
        .expect("P13 harness must define exact-zero failure counters");
    let forbidden_end = harness[forbidden_start..]
        .find("];\n")
        .map(|offset| forbidden_start + offset)
        .expect("P13 exact-zero failure counter list must be bounded");
    assert!(
        !harness[forbidden_start..forbidden_end].contains("\"stall_count\""),
        "P13 must apply the evidence-backed one-stall threshold separately from exact-zero counters"
    );
    for required in [
        "report.active_callback_count >= 600",
        "report.max_admissions_per_callback === 1",
        "report.callback_intervals.mean_us >= 8_000",
        "report.relay_frames_enqueued_during_run >= 600",
        "report.client_game_data_sent_during_run >= 600",
        "report.checksums_matched === report.checksums_compared",
        "report.client_game_data_sent_during_run <= report.active_callback_count * 2",
        "report.client_game_data_sent_during_run * 1_000 < report.running_elapsed_ms * 120",
        "\"current_frame=|confirmed_frame=|insufficient Fortress advancement|\" +",
        "\"fewer than 1200|non-nominal callback mean|oldest queue age|\" +",
        "\"stall_count|wait_recommendations|checksum agreement gate failed|\" +",
        "\"confirmation lag exceeded|rollback depth=|active wall time|\" +",
        "\"completed rate|sends per callback\",",
        "negative control developed an unrelated healthy-gate failure",
    ] {
        assert!(
            negative_classification.contains(required),
            "P13 negative classifier is missing `{required}`"
        );
    }
    assert_eq!(
        negative_classification.matches("violations.every").count(),
        1,
        "P13 negative classifier must reject every unrelated healthy-gate violation"
    );
    assert!(
        !harness.contains("/confirmed_frame|completed rate|sends per callback/"),
        "P13 negative control must not accept shortened confirmed-frame progress as expected BUSTED evidence"
    );
    assert!(
        runner.contains("node \"${FIXTURE_ROOT}/harness.mjs\" self-test"),
        "P13 runner must execute the data-driven health-threshold regression before the expensive build"
    );
    let persist_before_close = harness
        .find("await persistPeerArtifacts(joiner, joinerReport)")
        .expect("P13 must persist joiner artifacts");
    let close_after_persist = harness
        .find("await closePeer(joiner)")
        .expect("P13 must close the joiner");
    assert!(
        persist_before_close < close_after_persist,
        "P13 must persist page diagnostics before closing browser peers"
    );
    let persistence = &harness[harness
        .find("async function persistPeerArtifacts")
        .expect("P13 must define browser artifact persistence")..];
    let log_before_snapshot = persistence
        .find("safeWriteArtifact(`${peer.role}-browser.log`")
        .expect("P13 must persist collected browser logs");
    let errors_before_snapshot = persistence
        .find("safeWriteArtifact(`${peer.role}-browser-errors.log`")
        .expect("P13 must persist collected browser errors");
    let page_evaluate = persistence
        .find("const snapshotPromise = peer.page.evaluate")
        .expect("P13 must request the renderer snapshot");
    let bounded_snapshot = persistence
        .find("pageSnapshot = await Promise.race")
        .expect("P13 must bound the renderer snapshot");
    assert!(
        log_before_snapshot < page_evaluate && errors_before_snapshot < page_evaluate,
        "P13 must synchronously persist collected logs and errors before asking the renderer for a snapshot"
    );
    assert!(
        page_evaluate < bounded_snapshot,
        "P13 must race the renderer snapshot against its timeout"
    );

    for required in [
        "cargo build --manifest-path \"${REPO_ROOT}/Cargo.toml\" --locked --bin signal-fish-server",
        "wasm32-unknown-emscripten",
        "nightly-2026-03-01",
        "3.1.74",
        "released \"${EXPORT_DIR}\"",
        "negative \"${EXPORT_DIR}\"",
        "timeout --foreground 180s",
        "timeout --foreground",
        "signal-fish-client v0.9.0",
        "signal-fish-client-godot v0.9.0",
        "fortress-rollback v0.12.0",
        "HEALTHY: released Signal Fish client 0.9.0",
    ] {
        assert!(
            runner.contains(required),
            "P13 runner is missing `{required}`"
        );
    }
    assert_eq!(
        runner.matches("timeout --foreground 180s").count(),
        2,
        "P13 runner must preserve diagnostics for both released and negative browser cells"
    );
    for required in [
        "waitForGlobal(creator, \"__FORTRESS_RESULT\", 105_000)",
        "waitForGlobal(joiner, \"__FORTRESS_RESULT\", 105_000)",
    ] {
        assert!(
            harness.contains(required),
            "P13 harness is missing the bounded report wait `{required}`"
        );
    }

    assert_workflow_triggers_on_paths(
        &workflow,
        "fortress-wasm-interop.yml",
        &[
            "src/**",
            "Cargo.toml",
            "Cargo.lock",
            "rust-toolchain.toml",
            "clients/fortress/src/relay.rs",
            "clients/fortress/src/workload.rs",
            "clients/fortress-wasm/**",
            "clients/browser/package.json",
            "clients/browser/package-lock.json",
            "scripts/run-fortress-wasm-interop.sh",
            ".github/workflows/fortress-wasm-interop.yml",
        ],
    );
    for required in [
        "GODOT_EDITOR_SHA512:",
        "GODOT_TEMPLATES_SHA512:",
        "sha512sum --check",
        "cargo +\"$RUST_NIGHTLY\" clippy",
        "actions/upload-artifact@v7.0.1",
        "if: failure()",
        "rust-version: 1.94.0",
        "schedule:",
        "browser: ${{ fromJSON((github.event_name == 'schedule' || github.event_name == 'workflow_dispatch') && '[\"firefox\"]' || '[\"chromium\"]') }}",
        "FORTRESS_WASM_BROWSER: ${{ matrix.browser }}",
    ] {
        assert!(
            workflow.contains(required),
            "P13 workflow is missing `{required}`"
        );
    }
    assert!(
        !workflow.contains("node_modules\n") && !workflow.contains("playwright-browsers"),
        "P13 must not cache mutable/unverified browser installations"
    );
    for required in [
        "process.env.FORTRESS_WASM_BROWSER ?? \"chromium\"",
        "new Set([\"chromium\", \"firefox\"])",
        "browserType.launchServer",
        "browserType.connect",
        "browser.browserName === browserName",
        "\"peers share browser process\"",
    ] {
        assert!(
            harness.contains(required),
            "P13 harness must retain selectable Chromium/Firefox execution: `{required}`"
        );
    }
    // A headless runner has no GPU, so Firefox's blocklist refuses a software
    // WebGL context and the Godot web export aborts at boot on missing WebGL2.
    // Chromium gets `--enable-webgl --ignore-gpu-blocklist`; Firefox needs the
    // pref below or the scheduled cell fails before the game ever starts.
    for required in [
        "firefoxUserPrefs",
        "\"webgl.force-enabled\": true",
        "LIBGL_ALWAYS_SOFTWARE",
        "assertWebGl2Available",
    ] {
        assert!(
            harness.contains(required),
            "P13 headless Firefox must force a software WebGL2 context: `{required}`"
        );
    }
    // Firefox has no software WebGL fallback of its own and resolves Mesa's
    // llvmpipe through an X display even when headless; without one it reports
    // FEATURE_FAILURE_WEBGL_EXHAUSTED_DRIVERS and the Godot export aborts at
    // boot. Reproduced locally with `env -u DISPLAY`. The display is the
    // operative fix — a CI bisection showed the GL packages alone did not help —
    // but both are pinned so the cell cannot regress on either axis.
    for required in ["libgl1-mesa-dri", "xvfb"] {
        assert!(
            workflow.contains(required),
            "P13 Firefox cell must install `{required}`; without it the Godot export \
             aborts at boot on missing WebGL2 even with the prefs set"
        );
    }
    assert!(
        runner.contains("xvfb-run"),
        "P13 must run the Firefox harness under an X display; headless Firefox still \
         needs one to resolve a software GL driver"
    );
    for required in [
        "browser_name=\"${FORTRESS_WASM_BROWSER:-chromium}\"",
        "install --with-deps \"${browser_name}\"",
        "install \"${browser_name}\"",
    ] {
        assert!(
            runner.contains(required),
            "P13 runner must install the selected exact Playwright browser: `{required}`"
        );
    }
}

fn extract_ci_dep_detect_step(ci_content: &str) -> String {
    let step_start = ci_content
        .find("      - name: Detect dependency-only changes")
        .expect("doc-consistency dep-detect step header not found in .github/workflows/ci.yml");
    let after_start = &ci_content[step_start..];
    let step_end = after_start
        .find("\n      - name: Run documentation/changelog consistency checks")
        .expect("dep-detect step terminator not found in .github/workflows/ci.yml");
    after_start[..step_end].to_string()
}

#[test]
fn test_ci_dep_detect_skips_dependency_only_package_changes_without_commit_message_gate() {
    let root = repo_root();
    let ci_content = read_file(&root.join(".github/workflows/ci.yml"));
    let dep_detect_step = extract_ci_dep_detect_step(&ci_content);
    let dep_detect_step_live = strip_comment_lines(&dep_detect_step);

    assert!(
        dep_detect_step_live.contains("HAS_DEPENDENCY_CHANGE=\"false\"")
            && dep_detect_step_live.contains(
                "Cargo.toml|Cargo.lock|clients/native/Cargo.toml|clients/native/Cargo.lock) HAS_DEPENDENCY_CHANGE=\"true\" ;;"
            )
            && dep_detect_step_live.contains(
                "fuzz/Cargo.toml|fuzz/Cargo.lock) HAS_DEPENDENCY_CHANGE=\"true\" ;;"
            )
            && dep_detect_step_live.contains(
                "clients/fortress/Cargo.toml|clients/fortress/Cargo.lock) HAS_DEPENDENCY_CHANGE=\"true\" ;;"
            )
            && dep_detect_step_live.contains(
                "clients/fortress-wasm/Cargo.toml|clients/fortress-wasm/Cargo.lock) HAS_DEPENDENCY_CHANGE=\"true\" ;;"
            )
            && dep_detect_step_live.contains(
                "package.json|package-lock.json|clients/browser/package.json|clients/browser/package-lock.json) HAS_DEPENDENCY_CHANGE=\"true\" ;;"
            )
            && dep_detect_step_live
                .contains("if [ \"$NON_INTERNAL\" = \"false\" ] && [ \"$HAS_DEPENDENCY_CHANGE\" = \"true\" ]; then"),
        "dep-detect must skip changelog for dependency-only Cargo and npm changes using file classification, \
         not commit message heuristics.\n\
         Required logic:\n\
         1. Track whether a root/native/fuzz/Fortress/browser manifest or lock changed (HAS_DEPENDENCY_CHANGE)\n\
         2. Set skip_changelog=true when HAS_DEPENDENCY_CHANGE=true and NON_INTERNAL=false.\n\
         This prevents merge commit messages from accidentally forcing the changelog gate."
    );

    assert!(
        !dep_detect_step.contains("COMMIT_MSG=")
            && !dep_detect_step.contains("git log -1 --format")
            && !dep_detect_step.contains("grep -qiE"),
        "dep-detect must not rely on commit message pattern matching for dependency-only changelog skips.\n\
         Commit messages vary across squash/merge/rebase flows and are not a stable policy input."
    );
}

#[test]
fn test_ci_dep_detect_is_actor_agnostic_for_dependency_only_skips() {
    let root = repo_root();
    let ci_content = read_file(&root.join(".github/workflows/ci.yml"));
    let dep_detect_step = extract_ci_dep_detect_step(&ci_content);

    assert!(
        !dep_detect_step.contains("${{ github.actor }}")
            && !dep_detect_step.contains("dependabot[bot]"),
        "dep-detect dependency-only changelog skip logic must be actor-agnostic.\n\
         Skipping should depend on changed files, not actor identity, so merges by humans \
         and bots behave consistently."
    );
}

#[test]
fn test_agent_github_access_policy_is_extension_first() {
    let root = repo_root();
    let policy_files = [
        "AGENTS.md",
        "CLAUDE.md",
        ".github/copilot-instructions.md",
        ".llm/context.md",
        ".llm/skills/mandatory-workflow/SKILL.md",
    ];

    for relative_path in policy_files {
        let policy = read_file(&root.join(relative_path));
        let normalized = policy.split_whitespace().collect::<Vec<_>>().join(" ");
        assert!(
            normalized.contains("local `git`"),
            "{relative_path} must reserve branches, commits, and pushes for local git"
        );
        assert!(
            normalized.contains("VS Code GitHub") && normalized.contains("GitHub app"),
            "{relative_path} must make the connected VS Code GitHub extension/app primary"
        );
        assert!(
            normalized.contains("fallback") || normalized.contains("Fall back"),
            "{relative_path} must describe gh as a fallback"
        );
        assert!(
            normalized.contains("authenticated"),
            "{relative_path} must allow gh fallback only through an authenticated session"
        );
        let capability_limited = normalized.contains("only when")
            && (normalized.contains("cannot")
                || normalized.contains("does not expose")
                || normalized.contains("lacks"));
        assert!(
            capability_limited,
            "{relative_path} must limit gh fallback to capabilities the extension/app cannot perform"
        );
    }
}

// ---------------------------------------------------------------------------
// Internal Path Classification Tests
//
// Data-driven tests ensuring that the is_internal_path() function in
// check-doc-consistency.sh and the dep-detect case statement in ci.yml
// stay in sync, and that path classification is correct for known paths.
// These tests prevent regression of the docs/ci-cd-* misclassification bug.
// ---------------------------------------------------------------------------

/// Glob-style patterns that MUST appear in BOTH scripts/check-doc-consistency.sh
/// (is_internal_path function) and .github/workflows/ci.yml (dep-detect case).
/// The CI workflow additionally has Cargo.toml and CHANGELOG.md for dependency
/// bump detection (Cargo.lock is shared but grouped differently in ci.yml).
/// See also .github/test-fixtures/test-doc-consistency.sh which tests these
/// patterns via shell-level integration tests.
