/// Simple shell-glob matcher supporting `*` (matches any chars including `/`)
/// and literal characters. This covers all patterns used in is_internal_path().
fn glob_matches(pattern: &str, path: &str) -> bool {
    glob_matches_inner(pattern.as_bytes(), path.as_bytes())
}

fn glob_matches_inner(pattern: &[u8], path: &[u8]) -> bool {
    let mut p = 0;
    let mut s = 0;
    let mut star_p = None;
    let mut star_s = None;

    while s < path.len() {
        if p < pattern.len() && pattern[p] == b'*' {
            star_p = Some(p);
            star_s = Some(s);
            p += 1;
        } else if p < pattern.len() && pattern[p] == path[s] {
            p += 1;
            s += 1;
        } else if let (Some(sp), Some(ss)) = (star_p, star_s) {
            let new_ss = ss + 1;
            p = sp + 1;
            s = new_ss;
            star_s = Some(new_ss);
        } else {
            return false;
        }
    }

    while p < pattern.len() && pattern[p] == b'*' {
        p += 1;
    }

    p == pattern.len()
}

#[test]
fn test_internal_path_classification_data_driven() {
    let root = repo_root();
    let script_content = read_live_file(&root.join("scripts/check-doc-consistency.sh"));

    // Extract the case patterns from is_internal_path().
    // Find the block between "case \"$path\" in" and the closing "esac".
    let case_start = script_content
        .find("case \"$path\" in")
        .expect("is_internal_path() case statement not found in check-doc-consistency.sh");
    let case_block = &script_content[case_start..];
    let esac_offset = case_block
        .find("\n    esac")
        .or_else(|| case_block.find("\nesac"))
        .expect("esac not found after case \"$path\" in");
    let case_body = &case_block[..esac_offset];

    // Parse individual glob patterns from lines like:
    //   pattern1|pattern2|pattern3)
    // Skip the *) catch-all line.
    let mut patterns: Vec<&str> = Vec::new();
    for line in case_body.lines() {
        let trimmed = line.trim();
        // Skip non-pattern lines (comments, return, case header, empty)
        if !trimmed.ends_with(')') {
            continue;
        }
        // Skip the catch-all wildcard
        if trimmed == "*)" {
            continue;
        }
        // Strip trailing )
        let pat_str = trimmed.trim_end_matches(')');
        for pat in pat_str.split('|') {
            let pat = pat.trim();
            if !pat.is_empty() {
                patterns.push(pat);
            }
        }
    }

    assert!(
        !patterns.is_empty(),
        "Failed to extract any patterns from is_internal_path() in check-doc-consistency.sh"
    );

    let mut failures = Vec::new();

    for &(path, should_be_internal, reason) in INTERNAL_PATH_CLASSIFICATION_CASES {
        let matched = patterns.iter().any(|pat| glob_matches(pat, path));
        if matched != should_be_internal {
            let direction = if should_be_internal {
                "expected INTERNAL but classified as non-internal"
            } else {
                "expected NON-INTERNAL but classified as internal"
            };
            failures.push(format!("  - {path}: {direction} ({reason})"));
        }
    }

    assert!(
        failures.is_empty(),
        "Internal path classification mismatches in is_internal_path():\n\
         {}\n\n\
         Update is_internal_path() in scripts/check-doc-consistency.sh or fix the \
         test cases if the expected classification has changed.",
        failures.join("\n")
    );
}

#[test]
fn test_doc_validation_tool_versions_match_devcontainer_args() {
    let root = repo_root();
    let workflow_content = read_live_file(&root.join(".github/workflows/doc-validation.yml"));
    let dockerfile_content = read_live_file(&root.join(".devcontainer/Dockerfile"));

    let workflow_yq = extract_yaml_version(&workflow_content, "YQ_VERSION")
        .expect("doc-validation.yml must define env.YQ_VERSION");
    let dockerfile_yq = extract_toml_version(&dockerfile_content, "ARG YQ_VERSION")
        .expect(".devcontainer/Dockerfile must define ARG YQ_VERSION");

    assert_eq!(
        dockerfile_yq, workflow_yq,
        "YQ version drift detected between doc-validation workflow and devcontainer.\n\
         Keep .github/workflows/doc-validation.yml env.YQ_VERSION and\n\
         .devcontainer/Dockerfile ARG YQ_VERSION synchronized."
    );

    let workflow_taplo = extract_yaml_version(&workflow_content, "TAPLO_CLI_VERSION")
        .expect("doc-validation.yml must define env.TAPLO_CLI_VERSION");
    let dockerfile_taplo = extract_toml_version(&dockerfile_content, "ARG TAPLO_CLI_VERSION")
        .expect(".devcontainer/Dockerfile must define ARG TAPLO_CLI_VERSION");

    assert_eq!(
        dockerfile_taplo, workflow_taplo,
        "Taplo version drift detected between doc-validation workflow and devcontainer.\n\
         Keep .github/workflows/doc-validation.yml env.TAPLO_CLI_VERSION and\n\
         .devcontainer/Dockerfile ARG TAPLO_CLI_VERSION synchronized."
    );
}

#[test]
fn test_devcontainer_installs_required_modern_ci_tools() {
    let root = repo_root();
    let dockerfile_content = read_live_file(&root.join(".devcontainer/Dockerfile"));
    let devcontainer_json = read_live_file(&root.join(".devcontainer/devcontainer.json"));

    let required_fragments = [
        (
            "fd-find",
            "devcontainer must install fd-find so fd-style modern file search is available",
        ),
        (
            "ln -sf /usr/bin/fdfind /usr/local/bin/fd",
            "devcontainer must expose fd command via fdfind symlink",
        ),
        (
            "yq_linux_${yq_arch}",
            "devcontainer must install architecture-specific yq binary",
        ),
        (
            "install -m 0755 \"$yq_binary\" /usr/local/bin/yq",
            "devcontainer must install yq into PATH",
        ),
        (
            "cargo install --locked taplo-cli --version \"$TAPLO_CLI_VERSION\"",
            "devcontainer must install pinned taplo-cli",
        ),
        (
            "fd --version;",
            "devcontainer smoke checks should verify fd availability",
        ),
        (
            "yq --version;",
            "devcontainer smoke checks should verify yq availability",
        ),
        (
            "taplo --version",
            "devcontainer build should verify taplo availability",
        ),
    ];

    for (fragment, description) in required_fragments {
        assert!(
            dockerfile_content.contains(fragment),
            "Missing required devcontainer tooling fragment: {fragment}\n\
             Why this matters: {description}\n\
             File: .devcontainer/Dockerfile"
        );
    }

    assert!(
        devcontainer_json.contains("ghcr.io/devcontainers/features/docker-outside-of-docker:1"),
        ".devcontainer/devcontainer.json must include the docker-outside-of-docker feature\n\
         so Docker CLI workflows can run from VS Code devcontainers."
    );
}

#[test]
fn test_devcontainer_uses_portable_release_binary_and_fast_workspace_volumes() {
    let root = repo_root();
    let dockerfile_content = read_live_file(&root.join(".devcontainer/Dockerfile"));
    let devcontainer_json = read_live_file(&root.join(".devcontainer/devcontainer.json"));
    let post_create_content = read_live_file(&root.join(".devcontainer/post-create.sh"));

    for target in [
        r#"lychee_target="x86_64-unknown-linux-musl""#,
        r#"lychee_target="aarch64-unknown-linux-musl""#,
        r#"cargo_binstall_target="x86_64-unknown-linux-musl""#,
        r#"cargo_binstall_target="aarch64-unknown-linux-musl""#,
    ] {
        assert!(
            dockerfile_content.contains(target),
            ".devcontainer/Dockerfile must install the portable lychee artifact: {target}"
        );
    }
    for target in [
        r#"lychee_target="x86_64-unknown-linux-gnu""#,
        r#"lychee_target="aarch64-unknown-linux-gnu""#,
    ] {
        assert!(
            !dockerfile_content.contains(target),
            ".devcontainer/Dockerfile must not install glibc-sensitive lychee artifact: {target}"
        );
    }

    for cache_id in [
        "signal-fish-cargo-registry",
        "signal-fish-cargo-git",
        "signal-fish-cargo-install-target",
    ] {
        assert!(
            dockerfile_content.contains(cache_id),
            ".devcontainer/Dockerfile must retain the BuildKit cache: {cache_id}"
        );
    }
    assert!(
        dockerfile_content.contains("USER vscode"),
        ".devcontainer/Dockerfile must install Rust tooling as the non-root runtime user"
    );
    assert!(
        !dockerfile_content.contains("chown -R vscode:vscode /usr/local/cargo /usr/local/rustup"),
        ".devcontainer/Dockerfile must not duplicate toolchains in a recursive chown layer"
    );

    for mount in [
        "source=${devcontainerId}-cargo-target,target=${containerWorkspaceFolder}/target,type=volume",
        "source=${devcontainerId}-root-node-modules,target=${containerWorkspaceFolder}/node_modules,type=volume",
        "source=${devcontainerId}-browser-node-modules,target=${containerWorkspaceFolder}/clients/browser/node_modules,type=volume",
    ] {
        assert!(
            devcontainer_json.contains(mount),
            ".devcontainer/devcontainer.json must use the fast named volume: {mount}"
        );
    }

    for fragment in [
        "prepare_worktree_cache_dirs",
        "sudo install -d -m 0755",
        "clients/browser/node_modules",
        "configure_git_safe_directory",
        "safe.directory",
    ] {
        assert!(
            post_create_content.contains(fragment),
            ".devcontainer/post-create.sh must initialize named-volume ownership: {fragment}"
        );
    }
}

#[test]
fn test_tooling_parity_is_enforced_in_local_and_ci_paths() {
    let root = repo_root();
    let parity_script_path = root.join("scripts/check-tooling-parity.sh");

    assert!(
        parity_script_path.exists(),
        "scripts/check-tooling-parity.sh must exist to enforce CI/devcontainer tooling parity."
    );

    let parity_script_content = read_live_file(&parity_script_path);
    assert!(
        parity_script_content.contains("YQ_VERSION")
            && parity_script_content.contains("TAPLO_CLI_VERSION")
            && parity_script_content.contains("docker-outside-of-docker"),
        "scripts/check-tooling-parity.sh must validate yq/taplo version parity and docker feature parity."
    );

    let validate_ci_content = read_live_file(&root.join("scripts/validate-ci.sh"));
    assert!(
        validate_ci_content.contains("check-tooling-parity.sh")
            && validate_ci_content.contains("--tools"),
        "scripts/validate-ci.sh must include tooling parity validation and expose a --tools mode."
    );

    let run_local_ci_content = read_live_file(&root.join("scripts/run-local-ci.sh"));
    assert!(
        run_local_ci_content.contains("tooling parity")
            && run_local_ci_content.contains("scripts/validate-ci.sh --quiet"),
        "scripts/run-local-ci.sh must route CI config checks through validate-ci.sh, including tooling parity checks."
    );

    let ci_content = read_live_file(&root.join(".github/workflows/ci.yml"));
    assert!(
        ci_content.contains("Validate CI/devcontainer tool parity")
            && ci_content.contains("bash scripts/check-tooling-parity.sh"),
        "ci.yml must run scripts/check-tooling-parity.sh so parity drift fails in CI."
    );
}

